/**
 * Cache Hit Rate Benchmark
 *
 * Target: <0.1ms for cache hits
 *
 * Measures cache performance including hit rate,
 * lookup time, and eviction strategies.
 */

import { benchmark, BenchmarkRunner, formatTime, meetsTarget } from '../framework/benchmark.js';

// ============================================================================
// Cache Implementations
// ============================================================================

/**
 * Simple LRU Cache implementation
 */
class LRUCache<K, V> {
  private cache = new Map<K, V>();
  private maxSize: number;
  private hits = 0;
  private misses = 0;

  constructor(maxSize: number) {
    this.maxSize = maxSize;
  }

  get(key: K): V | undefined {
    const value = this.cache.get(key);
    if (value !== undefined) {
      // Move to end (most recently used)
      this.cache.delete(key);
      this.cache.set(key, value);
      this.hits++;
      return value;
    }
    this.misses++;
    return undefined;
  }

  set(key: K, value: V): void {
    if (this.cache.has(key)) {
      this.cache.delete(key);
    } else if (this.cache.size >= this.maxSize) {
      // Evict oldest (first) entry
      const firstKey = this.cache.keys().next().value;
      this.cache.delete(firstKey);
    }
    this.cache.set(key, value);
  }

  get hitRate(): number {
    const total = this.hits + this.misses;
    return total > 0 ? this.hits / total : 0;
  }

  get size(): number {
    return this.cache.size;
  }

  clear(): void {
    this.cache.clear();
    this.hits = 0;
    this.misses = 0;
  }
}

/**
 * TTL Cache with expiration
 */
class TTLCache<K, V> {
  private cache = new Map<K, { value: V; expiry: number }>();
  private defaultTTL: number;
  private hits = 0;
  private misses = 0;

  constructor(defaultTTL: number = 60000) {
    this.defaultTTL = defaultTTL;
  }

  get(key: K): V | undefined {
    const entry = this.cache.get(key);
    if (entry !== undefined) {
      if (Date.now() < entry.expiry) {
        this.hits++;
        return entry.value;
      }
      // Expired
      this.cache.delete(key);
    }
    this.misses++;
    return undefined;
  }

  set(key: K, value: V, ttl?: number): void {
    const expiry = Date.now() + (ttl || this.defaultTTL);
    this.cache.set(key, { value, expiry });
  }

  get hitRate(): number {
    const total = this.hits + this.misses;
    return total > 0 ? this.hits / total : 0;
  }

  get size(): number {
    return this.cache.size;
  }

  cleanup(): number {
    const now = Date.now();
    let cleaned = 0;
    for (const [key, entry] of this.cache) {
      if (now >= entry.expiry) {
        this.cache.delete(key);
        cleaned++;
      }
    }
    return cleaned;
  }

  clear(): void {
    this.cache.clear();
    this.hits = 0;
    this.misses = 0;
  }
}

/**
 * Two-level cache (L1 fast, L2 larger)
 */
class TwoLevelCache<K, V> {
  private l1: LRUCache<K, V>;
  private l2: LRUCache<K, V>;
  private l1Hits = 0;
  private l2Hits = 0;
  private misses = 0;

  constructor(l1Size: number = 100, l2Size: number = 1000) {
    this.l1 = new LRUCache<K, V>(l1Size);
    this.l2 = new LRUCache<K, V>(l2Size);
  }

  get(key: K): V | undefined {
    // Check L1 first
    let value = this.l1.get(key);
    if (value !== undefined) {
      this.l1Hits++;
      return value;
    }

    // Check L2
    value = this.l2.get(key);
    if (value !== undefined) {
      this.l2Hits++;
      // Promote to L1
      this.l1.set(key, value);
      return value;
    }

    this.misses++;
    return undefined;
  }

  set(key: K, value: V): void {
    this.l1.set(key, value);
    this.l2.set(key, value);
  }

  get stats(): { l1HitRate: number; l2HitRate: number; missRate: number } {
    const total = this.l1Hits + this.l2Hits + this.misses;
    return {
      l1HitRate: total > 0 ? this.l1Hits / total : 0,
      l2HitRate: total > 0 ? this.l2Hits / total : 0,
      missRate: total > 0 ? this.misses / total : 0,
    };
  }

  clear(): void {
    this.l1.clear();
    this.l2.clear();
    this.l1Hits = 0;
    this.l2Hits = 0;
    this.misses = 0;
  }
}

/**
 * Memoization cache for function results
 */
class MemoCache<T extends (...args: unknown[]) => unknown> {
  private cache = new Map<string, ReturnType<T>>();
  private fn: T;

  constructor(fn: T) {
    this.fn = fn;
  }

  call(...args: Parameters<T>): ReturnType<T> {
    const key = JSON.stringify(args);
    if (this.cache.has(key)) {
      return this.cache.get(key)!;
    }
    const result = this.fn(...args) as ReturnType<T>;
    this.cache.set(key, result);
    return result;
  }

  get size(): number {
    return this.cache.size;
  }

  clear(): void {
    this.cache.clear();
  }
}

