/**
 * HNSW Search Benchmark (ADR-125 Phase 6).
 *
 * Vitest `bench()` suite that measures the canonical `HNSWIndex.search()`
 * against a 1k-entry index. The bench exists so `npm run bench` produces
 * non-empty output and gives the README perf table a real referent.
 *
 * Result interpretation:
 * - `hnsw.search k=10` is the headline number — single-query latency against
 *   1,000 random 128-dim vectors.
 * - `hnsw.add (single)` measures incremental insert cost; useful for tracking
 *   regression as ADR-125 Phase 3 adds persistence.
 *
 * @see {@link ../docs/adr/ADR-125-memory-consolidation.md}
 */

import { describe, bench, beforeAll } from 'vitest';
import { HNSWIndex } from '../src/hnsw-index.js';

// Bench scale chosen to fit Phase 6's "ONE simple benchmark against 1k entries"
// scope. Dimensions kept small (128) so the bench completes in seconds — the
// goal is a runnable referent, not a full perf evaluation (that's Phase 3+).
const N = 1_000;
const DIM = 128;
const M = 16;
const EF_CONSTRUCTION = 200;

function randomVector(dim: number): Float32Array {
  const v = new Float32Array(dim);
  let norm = 0;
  for (let i = 0; i < dim; i++) {
    v[i] = Math.random() * 2 - 1;
    norm += v[i] * v[i];
  }
  norm = Math.sqrt(norm) || 1;
  for (let i = 0; i < dim; i++) v[i] /= norm;
  return v;
}

describe('HNSW search — 1k entries, 128-dim', () => {
  let index: HNSWIndex;
  let queries: Float32Array[];

  beforeAll(async () => {
    index = new HNSWIndex({
      dimensions: DIM,
      M,
      efConstruction: EF_CONSTRUCTION,
      maxElements: N + 100,
      metric: 'cosine',
    });

    // Pre-populate
    for (let i = 0; i < N; i++) {
      await index.addPoint(`vec-${i}`, randomVector(DIM));
    }

    // Pre-generate query vectors so the bench measures search, not RNG.
    queries = Array.from({ length: 50 }, () => randomVector(DIM));
  });

  bench(
    'hnsw.search k=10',
    async () => {
      const q = queries[Math.floor(Math.random() * queries.length)]!;
      await index.search(q, 10);
    },
    { iterations: 100, warmupIterations: 10 }
  );

  bench(
    'hnsw.search k=50',
    async () => {
      const q = queries[Math.floor(Math.random() * queries.length)]!;
      await index.search(q, 50);
    },
    { iterations: 100, warmupIterations: 10 }
  );
});

describe('HNSW add — incremental insert cost', () => {
  let index: HNSWIndex;
  let counter = 0;

  beforeAll(() => {
    index = new HNSWIndex({
      dimensions: DIM,
      M,
      efConstruction: EF_CONSTRUCTION,
      maxElements: 10_000,
      metric: 'cosine',
    });
  });

  bench(
    'hnsw.add (single)',
    async () => {
      await index.addPoint(`add-${counter++}`, randomVector(DIM));
    },
    { iterations: 500, warmupIterations: 50 }
  );
});

/**
 * AgentDB Memory Adapter for LongMemEval
 *
 * Uses AgentDB's HNSW-indexed vector search with ONNX embeddings
 * to store and retrieve conversation memories.
 */

import type { MemoryAdapter, Session } from '../types.js';

export class AgentDBAdapter implements MemoryAdapter {
  readonly name = 'AgentDB (HNSW + ONNX)';
  private db: any = null;
  private config: {
    hnswM: number;
    hnswEfSearch: number;
    topK: number;
    similarityThreshold: number;
  };

  constructor(options?: {
    hnswM?: number;
    hnswEfSearch?: number;
    topK?: number;
    similarityThreshold?: number;
  }) {
    this.config = {
      hnswM: options?.hnswM ?? 16,
      hnswEfSearch: options?.hnswEfSearch ?? 100,
      topK: options?.topK ?? 10,
      similarityThreshold: options?.similarityThreshold ?? 0.3,
    };
  }

  async init(): Promise<void> {
    // Dynamic import to avoid circular deps
    const { AgentDBBackend } = await import('../../../src/agentdb-backend.js');

    this.db = new AgentDBBackend({
      storagePath: '.longmemeval-bench',
      enableHNSW: true,
      hnswM: this.config.hnswM,
      hnswEfConstruction: 200,
      hnswEfSearch: this.config.hnswEfSearch,
    });

    await this.db.initialize();
  }

  async ingestSession(session: Session): Promise<void> {
    if (!this.db) throw new Error('Adapter not initialized');

    for (const msg of session.messages) {
      const key = `${session.session_id}:${msg.role}:${msg.timestamp ?? Date.now()}`;
      await this.db.store({
        key,
        value: msg.content,
        namespace: 'longmemeval',
        metadata: {
          session_id: session.session_id,
          role: msg.role,
          timestamp: msg.timestamp,
        },
      });
    }
  }

  async retrieve(
    question: string,
    topK?: number
  ): Promise<Array<{ content: string; score: number; session_id: string; metadata?: Record<string, unknown> }>> {
    if (!this.db) throw new Error('Adapter not initialized');

    const k = topK ?? this.config.topK;
    const results = await this.db.search({
      query: question,
      namespace: 'longmemeval',
      limit: k,
      threshold: this.config.similarityThreshold,
    });

    return results.map((r: any) => ({
      content: r.value ?? r.content ?? '',
      score: r.score ?? r.similarity ?? 0,
      session_id: r.metadata?.session_id ?? 'unknown',
      metadata: r.metadata,
    }));
  }

  async getStats(): Promise<{ entries: number; sizeBytes: number }> {
    if (!this.db) return { entries: 0, sizeBytes: 0 };
    const stats = await this.db.getStats?.() ?? { entries: 0 };
    return {
      entries: stats.entries ?? 0,
      sizeBytes: stats.sizeBytes ?? 0,
    };
  }

  async close(): Promise<void> {
    if (this.db?.close) await this.db.close();
    this.db = null;
  }
}

/**
 * Baseline Memory Adapter for LongMemEval
 *
 * Plain cosine similarity vector search without HNSW.
 * Used as a control to measure how much HNSW indexing helps.
 */

import type { MemoryAdapter, Session } from '../types.js';

export class BaselineAdapter implements MemoryAdapter {
  readonly name = 'Baseline (Cosine Similarity)';
  private entries: Array<{
    key: string;
    content: string;
    embedding: Float32Array | null;
    session_id: string;
    metadata: Record<string, unknown>;
  }> = [];
  private embedder: any = null;

  async init(): Promise<void> {
    // Try to load ONNX embedder for fair comparison
    try {
      const { OnnxEmbedder } = await import('../../../src/onnx-embedder.js');
      this.embedder = new OnnxEmbedder();
      await this.embedder.initialize();
    } catch {
      console.warn('[BaselineAdapter] ONNX embedder unavailable, using mock embeddings');
    }
  }

  async ingestSession(session: Session): Promise<void> {
    for (const msg of session.messages) {
      const key = `${session.session_id}:${msg.role}:${msg.timestamp ?? Date.now()}`;
      let embedding: Float32Array | null = null;

      if (this.embedder) {
        embedding = await this.embedder.embed(msg.content);
      }

      this.entries.push({
        key,
        content: msg.content,
        embedding,
        session_id: session.session_id,
        metadata: {
          session_id: session.session_id,
          role: msg.role,
          timestamp: msg.timestamp,
        },
      });
    }
  }

  async retrieve(
    question: string,
    topK: number = 10
  ): Promise<Array<{ content: string; score: number; session_id: string; metadata?: Record<string, unknown> }>> {
    if (!this.embedder || this.entries.length === 0) return [];

    const queryEmbedding = await this.embedder.embed(question);
    if (!queryEmbedding) return [];

    // Brute-force cosine similarity
    const scored = this.entries
      .filter(e => e.embedding !== null)
      .map(e => ({
        content: e.content,
        score: cosineSimilarity(queryEmbedding, e.embedding!),
        session_id: e.session_id,
        metadata: e.metadata,
      }))
      .sort((a, b) => b.score - a.score)
      .slice(0, topK);

    return scored;
  }

  async getStats(): Promise<{ entries: number; sizeBytes: number }> {
    const contentBytes = this.entries.reduce((sum, e) => sum + e.content.length * 2, 0);
    const embeddingBytes = this.entries.reduce((sum, e) => sum + (e.embedding?.byteLength ?? 0), 0);
    return {
      entries: this.entries.length,
      sizeBytes: contentBytes + embeddingBytes,
    };
  }

  async close(): Promise<void> {
    this.entries = [];
    this.embedder = null;
  }
}

/** Cosine similarity between two vectors */
function cosineSimilarity(a: Float32Array, b: Float32Array): number {
  let dot = 0, normA = 0, normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  const denom = Math.sqrt(normA) * Math.sqrt(normB);
  return denom === 0 ? 0 : dot / denom;
}

/**
 * LongMemEval Benchmark Harness for AgentDB
 *
 * ADR-088: Full LongMemEval benchmark implementation
 *
 * Usage:
 *   npx tsx harness.ts --mode raw --limit 50      # Quick test (50 questions)
 *   npx tsx harness.ts --mode raw                  # Full benchmark (500 questions)
 *   npx tsx harness.ts --mode hybrid               # With Haiku reranking
 *   npx tsx harness.ts --mode baseline             # Plain cosine baseline
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import type {
  Session,
  Question,
  QuestionResult,
  CategoryResult,
  BenchmarkReport,
  BenchmarkMode,
  MemoryAdapter,
  QuestionType,
} from './types.js';

const __dirname = dirname(fileURLToPath(import.meta.url));

// ── CLI Args ──────────────────────────────────────────────────

function parseArgs(): { mode: BenchmarkMode; limit: number; dataDir: string; adapter: string } {
  const args = process.argv.slice(2);
  let mode: BenchmarkMode = 'raw';
  let limit = 0; // 0 = all
  let dataDir = join(__dirname, 'data');
  let adapter = 'agentdb';

  for (let i = 0; i < args.length; i++) {
    switch (args[i]) {
      case '--mode': mode = (args[++i] as BenchmarkMode) || 'raw'; break;
      case '--limit': limit = parseInt(args[++i], 10) || 0; break;
      case '--data': dataDir = args[++i]; break;
      case '--adapter': adapter = args[++i]; break;
    }
  }

  return { mode, limit, dataDir, adapter };
}

// ── Dataset Loading ───────────────────────────────────────────

function loadDataset(dataDir: string): { sessions: Session[]; questions: Question[] } {
  const oracleFile = join(dataDir, 'longmemeval_oracle.json');
  if (!existsSync(oracleFile)) {
    console.error(`Dataset not found at ${oracleFile}`);
    console.error('Run: bash scripts/download-dataset.sh');
    process.exit(1);
  }

  const raw = JSON.parse(readFileSync(oracleFile, 'utf-8'));

  // LongMemEval format: array of items with sessions + question
  const sessions: Session[] = [];
  const questions: Question[] = [];
  const seenSessions = new Set<string>();

  for (const item of raw) {
    // Extract sessions
    if (item.sessions) {
      for (const sess of item.sessions) {
        if (!seenSessions.has(sess.session_id)) {
          seenSessions.add(sess.session_id);
          sessions.push(sess);
        }
      }
    }

    // Extract question
    if (item.question) {
      questions.push({
        question_id: item.question_id ?? item.id ?? `q-${questions.length}`,
        question: item.question,
        answer: item.answer ?? item.answers ?? '',
        question_type: mapQuestionType(item.question_type ?? item.type ?? ''),
        evidence_session_ids: item.evidence_session_ids ?? [],
        num_hops: item.num_hops ?? 1,
      });
    }
  }

  return { sessions, questions };
}

function mapQuestionType(raw: string): QuestionType {
  const normalized = raw.toLowerCase().replace(/[^a-z-]/g, '-');
  const mapping: Record<string, QuestionType> = {
    'single-session-single-hop': 'single-session-single-hop',
    'single-session-multi-hop': 'single-session-multi-hop',
    'multi-session-single-hop': 'multi-session-single-hop',
    'multi-session-multi-hop': 'multi-session-multi-hop',
    'knowledge-update': 'knowledge-update',
    'temporal-reasoning': 'temporal-reasoning',
  };
  return mapping[normalized] ?? 'single-session-single-hop';
}

// ── Answer Evaluation ─────────────────────────────────────────

function evaluateAnswer(predicted: string, gold: string | string[]): boolean {
  const normalize = (s: string) => s.toLowerCase().trim().replace(/[^\w\s]/g, '');
  const pred = normalize(predicted);

  const golds = Array.isArray(gold) ? gold : [gold];

  for (const g of golds) {
    const ng = normalize(g);
    // Exact match
    if (pred === ng) return true;
    // Contains match (lenient — official eval is more nuanced)
    if (pred.includes(ng) || ng.includes(pred)) return true;
  }
  return false;
}

// ── Answer Generation ─────────────────────────────────────────

async function generateAnswer(
  question: string,
  context: Array<{ content: string; score: number }>,
  mode: BenchmarkMode
): Promise<string> {
  // Raw mode: extract answer directly from top retrieved chunk
  if (mode === 'raw' || mode === 'baseline') {
    // Simple extractive: return the most relevant chunk
    // A real system would use an LLM here, but raw mode = zero API
    return context.length > 0 ? context[0].content : '';
  }

  // Hybrid / Full mode: use Haiku for answer generation
  if (mode === 'hybrid' || mode === 'full') {
    const contextText = context
      .slice(0, 5)
      .map((c, i) => `[${i + 1}] ${c.content}`)
      .join('\n\n');

    try {
      const { default: Anthropic } = await import('@anthropic-ai/sdk');
      const client = new Anthropic();

      const response = await client.messages.create({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 256,
        messages: [
          {
            role: 'user',
            content: `Based on the following conversation excerpts, answer the question concisely.\n\nContext:\n${contextText}\n\nQuestion: ${question}\n\nAnswer (be concise, just the answer):`,
          },
        ],
      });

      const block = response.content[0];
      return block.type === 'text' ? block.text.trim() : '';
    } catch (err) {
      console.warn(`[Haiku] Failed: ${(err as Error).message}`);
      return context.length > 0 ? context[0].content : '';
    }
  }

  return '';
}

// ── Percentile Calculation ────────────────────────────────────

function percentile(arr: number[], p: number): number {
  if (arr.length === 0) return 0;
  const sorted = [...arr].sort((a, b) => a - b);
  const idx = Math.ceil((p / 100) * sorted.length) - 1;
  return sorted[Math.max(0, idx)];
}

// ── Main Benchmark ────────────────────────────────────────────

async function main() {
  const { mode, limit, dataDir, adapter: adapterName } = parseArgs();

  console.log('=== LongMemEval Benchmark for AgentDB ===');
  console.log(`Mode:    ${mode}`);
  console.log(`Adapter: ${adapterName}`);
  console.log(`Limit:   ${limit || 'all'}`);
  console.log('');

  // Load dataset
  console.log('[1/5] Loading dataset...');
  const { sessions, questions } = loadDataset(dataDir);
  const evalQuestions = limit > 0 ? questions.slice(0, limit) : questions;
  console.log(`  Sessions: ${sessions.length}, Questions: ${evalQuestions.length}/${questions.length}`);

  // Initialize adapter
  console.log(`[2/5] Initializing ${adapterName} adapter...`);
  let adapter: MemoryAdapter;

  if (adapterName === 'baseline') {
    const { BaselineAdapter } = await import('./adapters/baseline-adapter.js');
    adapter = new BaselineAdapter();
  } else {
    const { AgentDBAdapter } = await import('./adapters/agentdb-adapter.js');
    adapter = new AgentDBAdapter();
  }

  await adapter.init();

  // Ingest sessions
  console.log('[3/5] Ingesting sessions...');
  const ingestStart = performance.now();
  let totalMessages = 0;

  for (let i = 0; i < sessions.length; i++) {
    await adapter.ingestSession(sessions[i]);
    totalMessages += sessions[i].messages.length;
    if ((i + 1) % 50 === 0 || i === sessions.length - 1) {
      process.stdout.write(`  Ingested ${i + 1}/${sessions.length} sessions (${totalMessages} messages)\r`);
    }
  }
  const ingestMs = performance.now() - ingestStart;
  console.log(`\n  Ingestion complete in ${(ingestMs / 1000).toFixed(1)}s`);

  // Evaluate questions
  console.log('[4/5] Evaluating questions...');
  const results: QuestionResult[] = [];
  let correct = 0;

  for (let i = 0; i < evalQuestions.length; i++) {
    const q = evalQuestions[i];

    // Retrieve
    const retStart = performance.now();
    const retrieved = await adapter.retrieve(q.question);
    const retrievalMs = performance.now() - retStart;

    // Generate answer
    const genStart = performance.now();
    const predicted = await generateAnswer(q.question, retrieved, mode);
    const generationMs = performance.now() - genStart;

    // Evaluate
    const isCorrect = evaluateAnswer(predicted, q.answer);
    if (isCorrect) correct++;

    results.push({
      question_id: q.question_id,
      question_type: q.question_type,
      predicted_answer: predicted.slice(0, 200),
      gold_answer: q.answer,
      correct: isCorrect,
      retrieval_time_ms: Math.round(retrievalMs * 100) / 100,
      generation_time_ms: Math.round(generationMs * 100) / 100,
      retrieved_chunks: retrieved.length,
    });

    if ((i + 1) % 25 === 0 || i === evalQuestions.length - 1) {
      const pct = ((correct / (i + 1)) * 100).toFixed(1);
      process.stdout.write(`  ${i + 1}/${evalQuestions.length} — ${correct}/${i + 1} correct (${pct}%)\r`);
    }
  }

  const overallAccuracy = (correct / evalQuestions.length) * 100;
  console.log(`\n  Overall: ${correct}/${evalQuestions.length} (${overallAccuracy.toFixed(1)}%)`);

  // Per-category breakdown
  const categories = new Map<QuestionType, { total: number; correct: number; retMs: number[]; genMs: number[] }>();
  for (const r of results) {
    const cat = categories.get(r.question_type) ?? { total: 0, correct: 0, retMs: [], genMs: [] };
    cat.total++;
    if (r.correct) cat.correct++;
    cat.retMs.push(r.retrieval_time_ms);
    cat.genMs.push(r.generation_time_ms);
    categories.set(r.question_type, cat);
  }

  const byCategory: CategoryResult[] = [...categories.entries()].map(([type, cat]) => ({
    question_type: type,
    total: cat.total,
    correct: cat.correct,
    accuracy: Math.round((cat.correct / cat.total) * 10000) / 100,
    avg_retrieval_ms: Math.round(cat.retMs.reduce((a, b) => a + b, 0) / cat.retMs.length * 100) / 100,
    avg_generation_ms: Math.round(cat.genMs.reduce((a, b) => a + b, 0) / cat.genMs.length * 100) / 100,
  }));

  // Latency stats
  const allRetMs = results.map(r => r.retrieval_time_ms);
  const allGenMs = results.map(r => r.generation_time_ms);

  // Storage stats
  const stats = await adapter.getStats();

  // Build report
  const report: BenchmarkReport = {
    timestamp: new Date().toISOString(),
    mode,
    system: adapter.name,
    version: '3.5.78',
    overall: {
      total: evalQuestions.length,
      correct,
      accuracy: Math.round(overallAccuracy * 100) / 100,
    },
    by_category: byCategory,
    latency: {
      retrieval_p50_ms: percentile(allRetMs, 50),
      retrieval_p95_ms: percentile(allRetMs, 95),
      retrieval_p99_ms: percentile(allRetMs, 99),
      generation_p50_ms: percentile(allGenMs, 50),
      generation_p95_ms: percentile(allGenMs, 95),
    },
    storage: {
      sessions_ingested: sessions.length,
      total_messages: totalMessages,
      db_size_bytes: stats.sizeBytes,
      index_size_bytes: 0,
    },
    config: {
      embedding_model: 'all-MiniLM-L6-v2',
      embedding_dims: 384,
      hnsw_m: 16,
      hnsw_ef_search: 100,
      top_k: 10,
      similarity_threshold: 0.3,
    },
  };

  // Save report
  console.log('[5/5] Saving report...');
  const resultsDir = join(__dirname, 'results');
  mkdirSync(resultsDir, { recursive: true });

  const reportFile = join(resultsDir, `report-${mode}-${new Date().toISOString().slice(0, 10)}.json`);
  writeFileSync(reportFile, JSON.stringify(report, null, 2) + '\n', 'utf-8');
  console.log(`  Report: ${reportFile}`);

  // Save detailed results
  const detailFile = join(resultsDir, `details-${mode}-${new Date().toISOString().slice(0, 10)}.json`);
  writeFileSync(detailFile, JSON.stringify(results, null, 2) + '\n', 'utf-8');
  console.log(`  Details: ${detailFile}`);

  // Print summary table
  console.log('');
  console.log('=== Results ===');
  console.log(`System:   ${adapter.name}`);
  console.log(`Mode:     ${mode}`);
  console.log(`Overall:  ${report.overall.accuracy}% (${correct}/${evalQuestions.length})`);
  console.log('');
  console.log('By Category:');
  console.log('  Type                          | Total | Correct | Accuracy');
  console.log('  ------------------------------|-------|---------|--------');
  for (const cat of byCategory) {
    const name = cat.question_type.padEnd(30);
    console.log(`  ${name}| ${String(cat.total).padStart(5)} | ${String(cat.correct).padStart(7)} | ${cat.accuracy.toFixed(1)}%`);
  }
  console.log('');
  console.log('Latency:');
  console.log(`  Retrieval p50: ${report.latency.retrieval_p50_ms.toFixed(1)}ms`);
  console.log(`  Retrieval p95: ${report.latency.retrieval_p95_ms.toFixed(1)}ms`);
  console.log(`  Retrieval p99: ${report.latency.retrieval_p99_ms.toFixed(1)}ms`);

  // Cleanup
  await adapter.close();
  console.log('');
  console.log('Benchmark complete.');
}

main().catch(err => {
  console.error('Benchmark failed:', err);
  process.exit(1);
});

/**
 * LongMemEval Benchmark Types
 * Based on: https://github.com/xiaowu0162/LongMemEval
 */

/** A single conversation session from the dataset */
export interface Session {
  session_id: string;
  messages: Array<{
    role: 'user' | 'assistant';
    content: string;
    timestamp?: string;
  }>;
}

/** A benchmark question */
export interface Question {
  question_id: string;
  question: string;
  answer: string | string[];
  question_type: QuestionType;
  evidence_session_ids: string[];
  /** Number of reasoning hops required */
  num_hops: number;
}

/** The 6 question types in LongMemEval */
export type QuestionType =
  | 'single-session-single-hop'
  | 'single-session-multi-hop'
  | 'multi-session-single-hop'
  | 'multi-session-multi-hop'
  | 'knowledge-update'
  | 'temporal-reasoning';

/** Benchmark mode */
export type BenchmarkMode = 'raw' | 'hybrid' | 'full' | 'baseline';

/** Result for a single question */
export interface QuestionResult {
  question_id: string;
  question_type: QuestionType;
  predicted_answer: string;
  gold_answer: string | string[];
  correct: boolean;
  retrieval_time_ms: number;
  generation_time_ms: number;
  retrieved_chunks: number;
}

/** Aggregate results per question type */
export interface CategoryResult {
  question_type: QuestionType;
  total: number;
  correct: number;
  accuracy: number;
  avg_retrieval_ms: number;
  avg_generation_ms: number;
}

/** Full benchmark report */
export interface BenchmarkReport {
  timestamp: string;
  mode: BenchmarkMode;
  system: string;
  version: string;
  overall: {
    total: number;
    correct: number;
    accuracy: number;
  };
  by_category: CategoryResult[];
  latency: {
    retrieval_p50_ms: number;
    retrieval_p95_ms: number;
    retrieval_p99_ms: number;
    generation_p50_ms: number;
    generation_p95_ms: number;
  };
  storage: {
    sessions_ingested: number;
    total_messages: number;
    db_size_bytes: number;
    index_size_bytes: number;
  };
  config: {
    embedding_model: string;
    embedding_dims: number;
    hnsw_m: number;
    hnsw_ef_search: number;
    top_k: number;
    similarity_threshold: number;
  };
}

/** Memory adapter interface — implementations provide storage + retrieval */
export interface MemoryAdapter {
  /** Human-readable name */
  readonly name: string;

  /** Initialize the adapter and create indices */
  init(): Promise<void>;

  /** Ingest a conversation session */
  ingestSession(session: Session): Promise<void>;

  /** Retrieve relevant context for a question */
  retrieve(question: string, topK?: number): Promise<Array<{
    content: string;
    score: number;
    session_id: string;
    metadata?: Record<string, unknown>;
  }>>;

  /** Get storage stats */
  getStats(): Promise<{ entries: number; sizeBytes: number }>;

  /** Clean up resources */
  close(): Promise<void>;
}

/**
 * Memory Write Benchmark
 *
 * Target: <5ms (10x faster than current ~50ms)
 *
 * Measures memory write operations including key-value stores,
 * structured data, and vector embeddings.
 */

import { benchmark, BenchmarkRunner, formatTime, meetsTarget } from '../framework/benchmark.js';

// ============================================================================
// Memory Store Implementations
// ============================================================================

/**
 * Simple in-memory key-value store
 */
class SimpleMemoryStore {
  private data = new Map<string, unknown>();

  set(key: string, value: unknown): void {
    this.data.set(key, value);
  }

  get(key: string): unknown {
    return this.data.get(key);
  }

  delete(key: string): boolean {
    return this.data.delete(key);
  }

  clear(): void {
    this.data.clear();
  }

  get size(): number {
    return this.data.size;
  }
}

/**
 * Typed array store for vectors
 */
class VectorStore {
  private vectors: Map<string, Float32Array> = new Map();
  private metadata: Map<string, object> = new Map();

  set(key: string, vector: Float32Array, meta?: object): void {
    this.vectors.set(key, vector);
    if (meta) {
      this.metadata.set(key, meta);
    }
  }

  get(key: string): { vector: Float32Array; metadata?: object } | undefined {
    const vector = this.vectors.get(key);
    if (!vector) return undefined;
    return { vector, metadata: this.metadata.get(key) };
  }

  delete(key: string): boolean {
    this.metadata.delete(key);
    return this.vectors.delete(key);
  }

  get size(): number {
    return this.vectors.size;
  }
}

/**
 * Write-ahead log for durability
 */
class WriteAheadLog {
  private entries: Array<{ timestamp: number; operation: string; key: string; value: unknown }> = [];
  private maxEntries = 10000;

  append(operation: string, key: string, value: unknown): number {
    const entry = {
      timestamp: Date.now(),
      operation,
      key,
      value,
    };
    this.entries.push(entry);

    // Compact if needed
    if (this.entries.length > this.maxEntries) {
      this.entries = this.entries.slice(-this.maxEntries / 2);
    }

    return this.entries.length;
  }

  get length(): number {
    return this.entries.length;
  }
}

/**
 * Batched memory store for bulk operations
 */
class BatchedMemoryStore {
  private data = new Map<string, unknown>();
  private pendingWrites: Array<{ key: string; value: unknown }> = [];
  private batchSize = 100;

  queue(key: string, value: unknown): void {
    this.pendingWrites.push({ key, value });
    if (this.pendingWrites.length >= this.batchSize) {
      this.flush();
    }
  }

  flush(): void {
    for (const { key, value } of this.pendingWrites) {
      this.data.set(key, value);
    }
    this.pendingWrites = [];
  }

  get(key: string): unknown {
    return this.data.get(key);
  }

  get size(): number {
    return this.data.size;
  }

  get pendingCount(): number {
    return this.pendingWrites.length;
  }
}

// ============================================================================
// Helper Functions
// ============================================================================

function generateVector(dim: number): Float32Array {
  const v = new Float32Array(dim);
  for (let i = 0; i < dim; i++) {
    v[i] = Math.random() * 2 - 1;
  }
  return v;
}

function generateTestData(count: number): Array<{ key: string; value: object }> {
  return Array.from({ length: count }, (_, i) => ({
    key: `key-${i}`,
    value: {
      id: i,
      name: `Item ${i}`,
      timestamp: Date.now(),
      tags: ['tag1', 'tag2', 'tag3'],
      metadata: { source: 'benchmark', priority: i % 10 },
    },
  }));
}

// ============================================================================
// Benchmark Suite
// ============================================================================

export async function runMemoryWriteBenchmarks(): Promise<void> {
  const runner = new BenchmarkRunner('Memory Write');

  console.log('\n--- Memory Write Benchmarks ---\n');

  const store = new SimpleMemoryStore();
  const vectorStore = new VectorStore();
  const wal = new WriteAheadLog();
  const batchedStore = new BatchedMemoryStore();

  // Benchmark 1: Single Key-Value Write
  const singleWriteResult = await runner.run(
    'single-kv-write',
    async () => {
      store.set(`key-${Date.now()}`, { data: 'test value' });
    },
    { iterations: 10000 }
  );

  console.log(`Single K-V Write: ${formatTime(singleWriteResult.mean)}`);
  const kvTarget = meetsTarget('memory-write', singleWriteResult.mean);
  console.log(`  Target (<5ms): ${kvTarget.met ? 'PASS' : 'FAIL'}`);

  // Benchmark 2: Batch Write (100 items)
  const testData = generateTestData(100);

  const batch100Result = await runner.run(
    'batch-write-100',
    async () => {
      for (const { key, value } of testData) {
        store.set(key, value);
      }
    },
    { iterations: 500 }
  );

  console.log(`Batch Write (100 items): ${formatTime(batch100Result.mean)}`);
  console.log(`  Per item: ${formatTime(batch100Result.mean / 100)}`);

  // Benchmark 3: Vector Write
  const vectorWriteResult = await runner.run(
    'vector-write',
    async () => {
      const vector = generateVector(384);
      vectorStore.set(`vec-${Date.now()}`, vector, { source: 'test' });
    },
    { iterations: 5000 }
  );

  console.log(`Vector Write (384d): ${formatTime(vectorWriteResult.mean)}`);

  // Benchmark 4: Batch Vector Write (100 vectors)
  const batchVectorResult = await runner.run(
    'batch-vector-write-100',
    async () => {
      for (let i = 0; i < 100; i++) {
        const vector = generateVector(384);
        vectorStore.set(`vec-${i}`, vector, { index: i });
      }
    },
    { iterations: 100 }
  );

  console.log(`Batch Vector Write (100x 384d): ${formatTime(batchVectorResult.mean)}`);
  console.log(`  Per vector: ${formatTime(batchVectorResult.mean / 100)}`);

  // Benchmark 5: Write-Ahead Log Append
  const walAppendResult = await runner.run(
    'wal-append',
    async () => {
      wal.append('SET', 'key', { data: 'value' });
    },
    { iterations: 10000 }
  );

  console.log(`WAL Append: ${formatTime(walAppendResult.mean)}`);

  // Benchmark 6: Batched Store Queue
  const batchedQueueResult = await runner.run(
    'batched-store-queue',
    async () => {
      batchedStore.queue(`key-${Date.now()}`, { data: 'test' });
    },
    { iterations: 10000 }
  );

  console.log(`Batched Store Queue: ${formatTime(batchedQueueResult.mean)}`);

  // Benchmark 7: Batched Store Flush
  // Queue up items first
  for (let i = 0; i < 100; i++) {
    batchedStore.queue(`flush-key-${i}`, { data: i });
  }

  const batchedFlushResult = await runner.run(
    'batched-store-flush-100',
    async () => {
      // Queue and flush 100 items
      for (let i = 0; i < 100; i++) {
        batchedStore.queue(`key-${i}`, { data: i });
      }
      batchedStore.flush();
    },
    { iterations: 500 }
  );

  console.log(`Batched Flush (100 items): ${formatTime(batchedFlushResult.mean)}`);

  // Benchmark 8: Object Serialization (JSON)
  const testObject = {
    id: 'test-123',
    name: 'Test Object',
    nested: { level1: { level2: { value: 42 } } },
    array: Array.from({ length: 100 }, (_, i) => i),
    timestamp: new Date().toISOString(),
  };

  const jsonSerializeResult = await runner.run(
    'json-serialize',
    async () => {
      JSON.stringify(testObject);
    },
    { iterations: 10000 }
  );

  console.log(`JSON Serialize: ${formatTime(jsonSerializeResult.mean)}`);

  // Benchmark 9: Object Cloning (for immutability)
  const cloneResult = await runner.run(
    'object-clone',
    async () => {
      const clone = structuredClone(testObject);
      void clone;
    },
    { iterations: 5000 }
  );

  console.log(`Object Clone: ${formatTime(cloneResult.mean)}`);

  // Benchmark 10: Concurrent Writes
  const concurrentWriteResult = await runner.run(
    'concurrent-writes-10',
    async () => {
      await Promise.all(
        Array.from({ length: 10 }, (_, i) =>
          Promise.resolve(store.set(`concurrent-${i}`, { index: i }))
        )
      );
    },
    { iterations: 1000 }
  );

  console.log(`Concurrent Writes (10): ${formatTime(concurrentWriteResult.mean)}`);

  // Benchmark 11: Large Value Write
  const largeValue = {
    data: 'x'.repeat(10000),
    nested: Array.from({ length: 100 }, (_, i) => ({
      id: i,
      content: 'content'.repeat(10),
    })),
  };

  const largeWriteResult = await runner.run(
    'large-value-write',
    async () => {
      store.set('large-key', largeValue);
    },
    { iterations: 1000 }
  );

  console.log(`Large Value Write (~100KB): ${formatTime(largeWriteResult.mean)}`);

  // Summary
  console.log('\n--- Summary ---');
  console.log(`Single write: ${formatTime(singleWriteResult.mean)}`);
  console.log(`Batched (100): ${formatTime(batch100Result.mean)} (${formatTime(batch100Result.mean / 100)}/item)`);
  console.log(`Vector (384d): ${formatTime(vectorWriteResult.mean)}`);
  console.log(`WAL append: ${formatTime(walAppendResult.mean)}`);
  console.log(`Batch queue: ${formatTime(batchedQueueResult.mean)} (${(batchedQueueResult.opsPerSecond).toFixed(0)} ops/sec)`);

  // Print full results
  runner.printResults();
}

// ============================================================================
// Memory Write Optimization Strategies
// ============================================================================

export const memoryWriteOptimizations = {
  /**
   * Write batching: Batch multiple writes together
   */
  writeBatching: {
    description: 'Batch multiple writes and flush periodically',
    expectedImprovement: '5-10x',
    implementation: `
      class BatchedWriter {
        private batch: Write[] = [];
        private batchSize = 100;
        private flushInterval = 100; // ms

        write(key: string, value: unknown): void {
          this.batch.push({ key, value });
          if (this.batch.length >= this.batchSize) {
            this.flush();
          }
        }

        private flush(): void {
          const writes = this.batch;
          this.batch = [];
          for (const { key, value } of writes) {
            this.store.set(key, value);
          }
        }
      }
    `,
  },

  /**
   * Object pooling: Reuse objects to avoid allocation
   */
  objectPooling: {
    description: 'Pool and reuse objects to reduce GC pressure',
    expectedImprovement: '20-40%',
    implementation: `
      class ObjectPool<T> {
        private pool: T[] = [];

        acquire(): T {
          return this.pool.pop() || this.create();
        }

        release(obj: T): void {
          this.reset(obj);
          this.pool.push(obj);
        }
      }
    `,
  },

  /**
   * Typed arrays: Use typed arrays for numeric data
   */
  typedArrays: {
    description: 'Use Float32Array/Int32Array for numeric data',
    expectedImprovement: '2-4x memory, 1.5-2x speed',
    implementation: `
      // Instead of:
      const vector = new Array(384).fill(0);

      // Use:
      const vector = new Float32Array(384);
    `,
  },

  /**
   * Write-ahead logging: Append-only for durability
   */
  walLogging: {
    description: 'Use append-only WAL for crash recovery',
    expectedImprovement: 'Durability with <10% overhead',
    implementation: `
      class WAL {
        private fd: number;

        async append(entry: LogEntry): Promise<void> {
          const data = Buffer.from(JSON.stringify(entry) + '\\n');
          await fs.write(this.fd, data);
          await fs.fdatasync(this.fd);
        }
      }
    `,
  },

  /**
   * Copy-on-write: Avoid unnecessary copying
   */
  copyOnWrite: {
    description: 'Use COW semantics for large objects',
    expectedImprovement: '30-50% for read-heavy workloads',
    implementation: `
      class COWStore {
        private data = new Map<string, { value: unknown; version: number }>();

        set(key: string, value: unknown): void {
          const existing = this.data.get(key);
          if (existing && deepEqual(existing.value, value)) {
            return; // No change needed
          }
          this.data.set(key, { value, version: (existing?.version ?? 0) + 1 });
        }
      }
    `,
  },
};

// Run if executed directly
if (import.meta.url === `file://${process.argv[1]}`) {
  runMemoryWriteBenchmarks().catch(console.error);
}

export default runMemoryWriteBenchmarks;

#!/usr/bin/env node
/**
 * ADR-125 Phase 6 — HNSW baseline measurement script.
 *
 * Pre-builds the package (`npm run build`) then exercises the canonical
 * HNSWIndex against 1,000 random 128-dim cosine vectors. Emits a JSON blob
 * suitable for archiving alongside `baseline-<timestamp>.md`.
 *
 * Usage:
 *   cd v3/@claude-flow/memory
 *   npm run build
 *   node benchmarks/results/scripts/run-baseline.mjs
 *
 * Companion to `benchmarks/hnsw-search.bench.ts` (which runs under vitest).
 */

import { HNSWIndex } from '../../../dist/hnsw-index.js';

const N = 1000;
const DIM = 128;
const M = 16;
const EF_CONSTRUCTION = 200;
const ITERS = 200;

function randomVector(dim) {
  const v = new Float32Array(dim);
  let norm = 0;
  for (let i = 0; i < dim; i++) {
    v[i] = Math.random() * 2 - 1;
    norm += v[i] * v[i];
  }
  norm = Math.sqrt(norm) || 1;
  for (let i = 0; i < dim; i++) v[i] /= norm;
  return v;
}

const buildStart = performance.now();
const index = new HNSWIndex({
  dimensions: DIM,
  M,
  efConstruction: EF_CONSTRUCTION,
  maxElements: N + 1000,
  metric: 'cosine',
});
for (let i = 0; i < N; i++) {
  await index.addPoint('vec-' + i, randomVector(DIM));
}
const buildTime = performance.now() - buildStart;

const queries = Array.from({ length: 50 }, () => randomVector(DIM));
for (let i = 0; i < 10; i++) await index.search(queries[i % queries.length], 10);

let t = performance.now();
for (let i = 0; i < ITERS; i++) {
  await index.search(queries[i % queries.length], 10);
}
const k10Avg = (performance.now() - t) / ITERS;

t = performance.now();
for (let i = 0; i < ITERS; i++) {
  await index.search(queries[i % queries.length], 50);
}
const k50Avg = (performance.now() - t) / ITERS;

let addCounter = N;
t = performance.now();
for (let i = 0; i < 200; i++) {
  await index.addPoint('add-' + addCounter++, randomVector(DIM));
}
const addAvg = (performance.now() - t) / 200;

console.log(
  JSON.stringify(
    {
      build_time_ms: +buildTime.toFixed(2),
      search_k10_avg_ms: +k10Avg.toFixed(4),
      search_k50_avg_ms: +k50Avg.toFixed(4),
      add_avg_ms: +addAvg.toFixed(4),
      search_k10_ops_per_sec: +(1000 / k10Avg).toFixed(1),
      search_k50_ops_per_sec: +(1000 / k50Avg).toFixed(1),
    },
    null,
    2
  )
);

/**
 * Vector Search Benchmark
 *
 * Target: <1ms (150x faster than current ~150ms)
 *
 * Measures vector similarity search performance including
 * linear search baseline vs HNSW optimized search.
 */

import { benchmark, BenchmarkRunner, formatTime, meetsTarget } from '../framework/benchmark.js';

// ============================================================================
// Vector Operations
// ============================================================================

/**
 * Generate a random vector of specified dimension
 */
function generateVector(dimension: number): Float32Array {
  const vector = new Float32Array(dimension);
  for (let i = 0; i < dimension; i++) {
    vector[i] = Math.random() * 2 - 1;
  }
  return normalizeVector(vector);
}

/**
 * Normalize a vector to unit length
 */
function normalizeVector(vector: Float32Array): Float32Array {
  let sum = 0;
  for (let i = 0; i < vector.length; i++) {
    sum += vector[i]! * vector[i]!;
  }
  const magnitude = Math.sqrt(sum);
  if (magnitude > 0) {
    for (let i = 0; i < vector.length; i++) {
      vector[i]! /= magnitude;
    }
  }
  return vector;
}

/**
 * Calculate cosine similarity between two vectors
 */
function cosineSimilarity(a: Float32Array, b: Float32Array): number {
  let dot = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i]! * b[i]!;
  }
  return dot;
}

/**
 * Calculate Euclidean distance between two vectors
 */
function euclideanDistance(a: Float32Array, b: Float32Array): number {
  let sum = 0;
  for (let i = 0; i < a.length; i++) {
    const diff = a[i]! - b[i]!;
    sum += diff * diff;
  }
  return Math.sqrt(sum);
}

// ============================================================================
// Search Implementations
// ============================================================================

interface SearchResult {
  id: number;
  score: number;
}

/**
 * Linear (brute-force) search - O(n)
 */
function linearSearch(
  query: Float32Array,
  vectors: Float32Array[],
  k: number
): SearchResult[] {
  const scores: SearchResult[] = vectors.map((v, i) => ({
    id: i,
    score: cosineSimilarity(query, v),
  }));

  scores.sort((a, b) => b.score - a.score);
  return scores.slice(0, k);
}

/**
 * Simple HNSW-like graph for approximate nearest neighbors
 * Simplified implementation for benchmarking
 */
class SimpleHNSW {
  private vectors: Float32Array[] = [];
  private graph: Map<number, number[]> = new Map();
  private entryPoint = 0;
  private readonly maxConnections = 16;
  private readonly efConstruction = 100;

  add(vector: Float32Array): number {
    const id = this.vectors.length;
    this.vectors.push(vector);

    if (id === 0) {
      this.graph.set(id, []);
      return id;
    }

    // Find nearest neighbors using current graph
    const neighbors = this.searchLayer(vector, this.entryPoint, this.efConstruction);

    // Connect to nearest neighbors
    const connections = neighbors
      .slice(0, this.maxConnections)
      .map((r) => r.id);
    this.graph.set(id, connections);

    // Add reverse connections
    for (const neighborId of connections) {
      const neighborConnections = this.graph.get(neighborId) || [];
      if (neighborConnections.length < this.maxConnections) {
        neighborConnections.push(id);
        this.graph.set(neighborId, neighborConnections);
      }
    }

    return id;
  }

  search(query: Float32Array, k: number, ef = 50): SearchResult[] {
    if (this.vectors.length === 0) return [];

    const results = this.searchLayer(query, this.entryPoint, Math.max(k, ef));
    return results.slice(0, k);
  }

  private searchLayer(
    query: Float32Array,
    entryPoint: number,
    ef: number
  ): SearchResult[] {
    const visited = new Set<number>();
    const candidates: SearchResult[] = [
      { id: entryPoint, score: cosineSimilarity(query, this.vectors[entryPoint]!) },
    ];
    const results: SearchResult[] = [...candidates];

    visited.add(entryPoint);

    while (candidates.length > 0) {
      candidates.sort((a, b) => b.score - a.score);
      const current = candidates.shift()!;

      const neighbors = this.graph.get(current.id) || [];
      for (const neighborId of neighbors) {
        if (visited.has(neighborId)) continue;
        visited.add(neighborId);

        const score = cosineSimilarity(query, this.vectors[neighborId]!);
        results.push({ id: neighborId, score });
        candidates.push({ id: neighborId, score });

        if (results.length > ef) {
          results.sort((a, b) => b.score - a.score);
          results.length = ef;
        }
      }

      if (candidates.length > ef) {
        candidates.sort((a, b) => b.score - a.score);
        candidates.length = ef;
      }
    }

    results.sort((a, b) => b.score - a.score);
    return results;
  }

  get size(): number {
    return this.vectors.length;
  }
}

// ============================================================================
// Benchmark Suite
// ============================================================================

export async function runVectorSearchBenchmarks(): Promise<void> {
  const runner = new BenchmarkRunner('Vector Search');

  console.log('\n--- Vector Search Benchmarks ---\n');

  const dimensions = 384; // Common embedding dimension
  const k = 10; // Number of results to return

  // Prepare test data
  console.log('Preparing test data...');

  // Small dataset (1,000 vectors)
  const smallDataset = Array.from({ length: 1000 }, () => generateVector(dimensions));
  const smallHNSW = new SimpleHNSW();
  for (const v of smallDataset) {
    smallHNSW.add(v);
  }

  // Medium dataset (10,000 vectors)
  const mediumDataset = Array.from({ length: 10000 }, () => generateVector(dimensions));
  const mediumHNSW = new SimpleHNSW();
  for (const v of mediumDataset) {
    mediumHNSW.add(v);
  }

  // Query vector
  const query = generateVector(dimensions);

  console.log('Test data prepared.\n');

  // Benchmark 1: Linear Search - 1,000 vectors
  const linear1kResult = await runner.run(
    'linear-search-1k',
    async () => {
      linearSearch(query, smallDataset, k);
    },
    { iterations: 100 }
  );

  console.log(`Linear Search (1k vectors): ${formatTime(linear1kResult.mean)}`);

  // Benchmark 2: HNSW Search - 1,000 vectors
  const hnsw1kResult = await runner.run(
    'hnsw-search-1k',
    async () => {
      smallHNSW.search(query, k);
    },
    { iterations: 500 }
  );

  console.log(`HNSW Search (1k vectors): ${formatTime(hnsw1kResult.mean)}`);
  const speedup1k = linear1kResult.mean / hnsw1kResult.mean;
  console.log(`  Speedup: ${speedup1k.toFixed(1)}x`);

  // Benchmark 3: Linear Search - 10,000 vectors
  const linear10kResult = await runner.run(
    'linear-search-10k',
    async () => {
      linearSearch(query, mediumDataset, k);
    },
    { iterations: 20 }
  );

  console.log(`Linear Search (10k vectors): ${formatTime(linear10kResult.mean)}`);

  // Benchmark 4: HNSW Search - 10,000 vectors
  const hnsw10kResult = await runner.run(
    'hnsw-search-10k',
    async () => {
      mediumHNSW.search(query, k);
    },
    { iterations: 200 }
  );

  console.log(`HNSW Search (10k vectors): ${formatTime(hnsw10kResult.mean)}`);
  const speedup10k = linear10kResult.mean / hnsw10kResult.mean;
  console.log(`  Speedup: ${speedup10k.toFixed(1)}x`);

  // Check target
  const target = meetsTarget('vector-search', hnsw10kResult.mean);
  console.log(`  Target (<1ms): ${target.met ? 'PASS' : 'FAIL'}`);

  // Benchmark 5: Cosine Similarity Calculation
  const v1 = generateVector(dimensions);
  const v2 = generateVector(dimensions);

  const cosineResult = await runner.run(
    'cosine-similarity',
    async () => {
      cosineSimilarity(v1, v2);
    },
    { iterations: 10000 }
  );

  console.log(`Cosine Similarity: ${formatTime(cosineResult.mean)}`);

  // Benchmark 6: Euclidean Distance Calculation
  const euclideanResult = await runner.run(
    'euclidean-distance',
    async () => {
      euclideanDistance(v1, v2);
    },
    { iterations: 10000 }
  );

  console.log(`Euclidean Distance: ${formatTime(euclideanResult.mean)}`);

  // Benchmark 7: Vector Normalization
  const normResult = await runner.run(
    'vector-normalization',
    async () => {
      const v = new Float32Array(dimensions);
      for (let i = 0; i < dimensions; i++) {
        v[i] = Math.random();
      }
      normalizeVector(v);
    },
    { iterations: 5000 }
  );

  console.log(`Vector Normalization: ${formatTime(normResult.mean)}`);

  // Benchmark 8: Batch Search (5 queries)
  const queries = Array.from({ length: 5 }, () => generateVector(dimensions));

  const batchSearchResult = await runner.run(
    'batch-search-5-queries',
    async () => {
      for (const q of queries) {
        smallHNSW.search(q, k);
      }
    },
    { iterations: 100 }
  );

  console.log(`Batch Search (5 queries): ${formatTime(batchSearchResult.mean)}`);

  // Benchmark 9: Parallel Batch Search
  const parallelBatchResult = await runner.run(
    'parallel-batch-search',
    async () => {
      await Promise.all(queries.map((q) => Promise.resolve(smallHNSW.search(q, k))));
    },
    { iterations: 100 }
  );

  console.log(`Parallel Batch Search: ${formatTime(parallelBatchResult.mean)}`);

  // Summary
  console.log('\n--- Summary ---');
  console.log(`1k vectors: Linear ${formatTime(linear1kResult.mean)} -> HNSW ${formatTime(hnsw1kResult.mean)} (${speedup1k.toFixed(1)}x)`);
  console.log(`10k vectors: Linear ${formatTime(linear10kResult.mean)} -> HNSW ${formatTime(hnsw10kResult.mean)} (${speedup10k.toFixed(1)}x)`);
  console.log(`\nProjected for 100k vectors: ~${((speedup10k * 10)).toFixed(0)}x improvement`);
  console.log(`Projected for 1M vectors: ~${((speedup10k * 100)).toFixed(0)}x improvement`);

  // Print full results
  runner.printResults();
}

