    const entries: MemoryEntry[] = [];
    for (let i = 0; i < n; i++) {
      const refs: string[] = [];
      for (let j = 0; j < 3; j++) {
        const r = Math.floor(Math.random() * n);
        if (r !== i) refs.push(`entry-${r}`);
      }
      entries.push(makeEntry(`entry-${i}`, refs));
