      e.namespace = 'learnings';
      sourceEntries.push(e);
    }
    const sourceBackend = createMockBackend(sourceEntries);
    const targetBackend = createMockBackend();
    const targetBridge = new AutoMemoryBridge(targetBackend, { memoryDir: '/tmp/bench-target' });
    const t0 = performance.now();
    const result = await transferKnowledge(sourceBackend, targetBridge, { sourceNamespace: 'learnings', minConfidence: 0.8, maxEntries: 20 });
    const dt = performance.now() - t0;
    console.log(`  Transfer knowledge: ${dt.toFixed(2)}ms  (${result.transferred} transferred)  [target: <100ms]`);
    targets.push({ name: 'Knowledge transfer', actual: dt, target: 100, unit: 'ms' });
    expect(dt).toBeLessThan(100);
  });

  it('SUMMARY: all targets met', () => {
    console.log('\n=== ADR-049 Performance Summary ===\n');
    for (const t of targets) {
      const pass = t.actual <= t.target;
      const ratio = (t.target / t.actual).toFixed(1);
      console.log(`  ${pass ? 'PASS' : 'FAIL'}  ${t.name.padEnd(28)} ${t.actual.toFixed(2).padStart(8)} ${t.unit.padEnd(8)}  target: <${t.target}${t.unit}  (${ratio}x headroom)`);
    }
    console.log('');
    const allPass = targets.every(t => t.actual <= t.target);
    expect(allPass).toBe(true);
  });
});

/**
 * V3 Cache Manager
 *
 * High-performance LRU cache with TTL support, memory pressure handling,
 * and write-through caching for the unified memory system.
 *
 * @module v3/memory/cache-manager
 */

import { EventEmitter } from 'node:events';
import {
  CacheConfig,
  CacheStats,
  CachedEntry,
  MemoryEntry,
  MemoryEvent,
} from './types.js';

/**
 * Doubly-linked list node for LRU implementation
 */
interface LRUNode<T> {
  key: string;
  value: CachedEntry<T>;
  prev: LRUNode<T> | null;
  next: LRUNode<T> | null;
}

/**
 * High-performance LRU Cache with TTL support
 *
 * Features:
 * - O(1) get, set, delete operations
 * - LRU eviction policy
 * - TTL-based expiration
 * - Memory pressure handling
 * - Write-through caching support
 * - Performance statistics
 */
export class CacheManager<T = MemoryEntry> extends EventEmitter {
  private config: CacheConfig;
  private cache: Map<string, LRUNode<T>> = new Map();
  private head: LRUNode<T> | null = null;
  private tail: LRUNode<T> | null = null;
  private currentMemory: number = 0;

  // Statistics
  private stats: {
    hits: number;
    misses: number;
    evictions: number;
    expirations: number;
    writes: number;
  } = {
    hits: 0,
    misses: 0,
    evictions: 0,
    expirations: 0,
    writes: 0,
  };

  // Cleanup timer
  private cleanupInterval: NodeJS.Timeout | null = null;

  constructor(config: Partial<CacheConfig> = {}) {
    super();
    this.config = this.mergeConfig(config);
    this.startCleanupTimer();
  }

  /**
   * Get a value from the cache
   */
  get(key: string): T | null {
    const node = this.cache.get(key);

    if (!node) {
      this.stats.misses++;
      this.emit('cache:miss', { key });
      return null;
    }

    // Check if expired
    if (this.isExpired(node.value)) {
      this.delete(key);
      this.stats.misses++;
      this.stats.expirations++;
      this.emit('cache:expired', { key });
      return null;
    }

    // Update access time and count
    node.value.lastAccessedAt = Date.now();
    node.value.accessCount++;

    // Move to front (most recently used)
    this.moveToFront(node);

    this.stats.hits++;
    this.emit('cache:hit', { key });

    return node.value.data;
  }

  /**
   * Set a value in the cache
   */
  set(key: string, data: T, ttl?: number): void {
    const now = Date.now();
    const entryTtl = ttl || this.config.ttl;

    // Check if key already exists
    const existingNode = this.cache.get(key);
    if (existingNode) {
      // Update existing entry
      existingNode.value.data = data;
      existingNode.value.cachedAt = now;
      existingNode.value.expiresAt = now + entryTtl;
      existingNode.value.lastAccessedAt = now;

      this.moveToFront(existingNode);
      this.stats.writes++;
      return;
    }

    // Calculate memory for new entry
    const entryMemory = this.estimateSize(data);

    // Evict entries if needed for memory pressure
    if (this.config.maxMemory) {
      while (
        this.currentMemory + entryMemory > this.config.maxMemory &&
        this.cache.size > 0
      ) {
        this.evictLRU();
      }
    }

    // Evict entries if at capacity
    while (this.cache.size >= this.config.maxSize) {
      this.evictLRU();
    }

    // Create new node
    const cachedEntry: CachedEntry<T> = {
      data,
      cachedAt: now,
      expiresAt: now + entryTtl,
      lastAccessedAt: now,
      accessCount: 0,
    };

    const node: LRUNode<T> = {
      key,
      value: cachedEntry,
      prev: null,
      next: null,
    };

    // Add to cache
    this.cache.set(key, node);
    this.addToFront(node);
    this.currentMemory += entryMemory;
    this.stats.writes++;

    this.emit('cache:set', { key, ttl: entryTtl });
  }

  /**
   * Delete a value from the cache
   */
  delete(key: string): boolean {
    const node = this.cache.get(key);
    if (!node) {
      return false;
    }

    this.removeNode(node);
    this.cache.delete(key);
    this.currentMemory -= this.estimateSize(node.value.data);

    this.emit('cache:delete', { key });
    return true;
  }

  /**
   * Check if a key exists in the cache (without affecting LRU order)
   */
  has(key: string): boolean {
    const node = this.cache.get(key);
    if (!node) return false;
    if (this.isExpired(node.value)) {
      this.delete(key);
      return false;
    }
    return true;
  }

  /**
   * Clear all entries from the cache
   */
  clear(): void {
    this.cache.clear();
    this.head = null;
    this.tail = null;
    this.currentMemory = 0;

    this.emit('cache:cleared', { previousSize: this.cache.size });
  }

  /**
   * Get cache statistics
   */
  getStats(): CacheStats {
    const total = this.stats.hits + this.stats.misses;
    return {
      size: this.cache.size,
      hitRate: total > 0 ? this.stats.hits / total : 0,
      hits: this.stats.hits,
      misses: this.stats.misses,
      evictions: this.stats.evictions,
      memoryUsage: this.currentMemory,
    };
  }

  /**
   * Get all keys in the cache
   */
  keys(): string[] {
    return Array.from(this.cache.keys());
  }

  /**
   * Get the size of the cache
   */
  get size(): number {
    return this.cache.size;
  }

  /**
   * Prefetch multiple keys in a single batch
   */
  async prefetch(
    keys: string[],
    loader: (keys: string[]) => Promise<Map<string, T>>,
    ttl?: number
  ): Promise<void> {
    const missing = keys.filter((key) => !this.has(key));

    if (missing.length === 0) {
      return;
    }

    const data = await loader(missing);

    for (const [key, value] of data) {
      this.set(key, value, ttl);
    }

    this.emit('cache:prefetched', { keys: missing.length });
  }

  /**
   * Get or set pattern - get from cache or load and cache
   */
  async getOrSet(
    key: string,
    loader: () => Promise<T>,
    ttl?: number
  ): Promise<T> {
    const cached = this.get(key);
    if (cached !== null) {
      return cached;
    }

    const data = await loader();
    this.set(key, data, ttl);
    return data;
  }

  /**
   * Warm the cache with initial data
   */
  warmUp(entries: Array<{ key: string; data: T; ttl?: number }>): void {
    for (const entry of entries) {
      this.set(entry.key, entry.data, entry.ttl);
    }
    this.emit('cache:warmedUp', { count: entries.length });
  }

  /**
   * Invalidate entries matching a pattern
   */
  invalidatePattern(pattern: string | RegExp): number {
    const regex = typeof pattern === 'string' ? new RegExp(pattern) : pattern;
    let invalidated = 0;

    for (const key of this.cache.keys()) {
      if (regex.test(key)) {
        this.delete(key);
        invalidated++;
      }
    }

    this.emit('cache:invalidated', { pattern: pattern.toString(), count: invalidated });
    return invalidated;
  }

  /**
   * Shutdown the cache manager
   */
  shutdown(): void {
    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval);
      this.cleanupInterval = null;
    }
    this.clear();
    this.emit('cache:shutdown');
  }

  // ===== Private Methods =====

  private mergeConfig(config: Partial<CacheConfig>): CacheConfig {
    return {
      maxSize: config.maxSize || 10000,
      ttl: config.ttl || 300000, // 5 minutes default
      lruEnabled: config.lruEnabled !== false,
      maxMemory: config.maxMemory,
      writeThrough: config.writeThrough || false,
    };
  }

  private isExpired(entry: CachedEntry<T>): boolean {
    return Date.now() > entry.expiresAt;
  }

  private estimateSize(data: T): number {
    try {
      return JSON.stringify(data).length * 2; // Rough UTF-16 estimate
    } catch {
      return 1000; // Default for non-serializable objects
    }
  }

  private addToFront(node: LRUNode<T>): void {
    node.prev = null;
    node.next = this.head;

    if (this.head) {
      this.head.prev = node;
    }

    this.head = node;

    if (!this.tail) {
      this.tail = node;
    }
  }

  private removeNode(node: LRUNode<T>): void {
    if (node.prev) {
      node.prev.next = node.next;
    } else {
      this.head = node.next;
    }

    if (node.next) {
      node.next.prev = node.prev;
    } else {
      this.tail = node.prev;
    }
  }

  private moveToFront(node: LRUNode<T>): void {
    if (node === this.head) return;

    this.removeNode(node);
    this.addToFront(node);
  }

  private evictLRU(): void {
    if (!this.tail) return;

    const evictedKey = this.tail.key;
    const evictedSize = this.estimateSize(this.tail.value.data);

    this.removeNode(this.tail);
    this.cache.delete(evictedKey);
    this.currentMemory -= evictedSize;
    this.stats.evictions++;

    this.emit('cache:eviction', { key: evictedKey });
  }

  private startCleanupTimer(): void {
    // Clean up expired entries every minute
    this.cleanupInterval = setInterval(() => {
      this.cleanupExpired();
    }, 60000);
  }

  private cleanupExpired(): void {
    const now = Date.now();
    let cleaned = 0;

    for (const [key, node] of this.cache) {
      if (node.value.expiresAt < now) {
        this.delete(key);
        cleaned++;
      }
    }

    if (cleaned > 0) {
      this.emit('cache:cleanup', { expired: cleaned });
    }
  }
}

/**
 * Multi-layer cache with L1 (memory) and L2 (storage) tiers
 */
export class TieredCacheManager<T = MemoryEntry> extends EventEmitter {
  private l1Cache: CacheManager<T>;
  private l2Loader: ((key: string) => Promise<T | null>) | null = null;
  private l2Writer: ((key: string, value: T) => Promise<void>) | null = null;

  constructor(
    l1Config: Partial<CacheConfig> = {},
    l2Options?: {
      loader: (key: string) => Promise<T | null>;
      writer?: (key: string, value: T) => Promise<void>;
    }
  ) {
    super();
    this.l1Cache = new CacheManager<T>(l1Config);

    if (l2Options) {
      this.l2Loader = l2Options.loader;
      this.l2Writer = l2Options.writer ?? null;
    }

    // Forward L1 events
    this.l1Cache.on('cache:hit', (data) => this.emit('l1:hit', data));
    this.l1Cache.on('cache:miss', (data) => this.emit('l1:miss', data));
    this.l1Cache.on('cache:eviction', (data) => this.emit('l1:eviction', data));
  }

  /**
   * Get from tiered cache
   */
  async get(key: string): Promise<T | null> {
    // Try L1 first
    const l1Result = this.l1Cache.get(key);
    if (l1Result !== null) {
      return l1Result;
    }

    // Try L2 if available
    if (this.l2Loader) {
      const l2Result = await this.l2Loader(key);
      if (l2Result !== null) {
        // Promote to L1
        this.l1Cache.set(key, l2Result);
        this.emit('l2:hit', { key });
        return l2Result;
      }
      this.emit('l2:miss', { key });
    }

    return null;
  }

  /**
   * Set in tiered cache
   */
  async set(key: string, value: T, ttl?: number): Promise<void> {
    // Write to L1
    this.l1Cache.set(key, value, ttl);

    // Write-through to L2 if configured
    if (this.l2Writer) {
      await this.l2Writer(key, value);
      this.emit('l2:write', { key });
    }
  }

  /**
   * Delete from tiered cache
   */
  delete(key: string): boolean {
    return this.l1Cache.delete(key);
  }

  /**
   * Get L1 cache statistics
   */
  getStats(): CacheStats {
    return this.l1Cache.getStats();
  }

  /**
   * Clear L1 cache
   */
  clear(): void {
    this.l1Cache.clear();
  }

  /**
   * Shutdown tiered cache
   */
  shutdown(): void {
    this.l1Cache.shutdown();
  }
}

export default CacheManager;

/**
 * Phase 4 — MemoryConsolidator (ADR-125)
 *
 * Verifies:
 * - `sweepExpired()` after 1000 entries with `expiresAt` in the past →
 *   `entries.size === 0` AND `hnsw.size === 0` (Acceptance Criterion #4).
 * - `dedup('keep-newest')` collapses content-hash duplicates and keeps the
 *   newest by `updatedAt`.
 * - `dedup('keep-oldest')` keeps the oldest by `createdAt`.
 * - `dedup('merge-tags')` unions tags and keeps the newest.
 * - `compactHnsw` rebuilds the index so size matches `entries.size`.
 * - Auto-run timer with a small interval calls `runAll()` at least once.
 * - `nightlyLearner` controller delegates to `MemoryConsolidator.runAll()`
 *   when a `MemoryService` is registered.
 */

import { describe, it, expect, vi } from 'vitest';
import { MemoryService } from './index.js';
import { MemoryConsolidator } from './consolidator.js';
import { ControllerRegistry } from './controller-registry.js';
import { createDefaultEntry } from './types.js';

function randomVec(dim: number, seed: number): Float32Array {
  const out = new Float32Array(dim);
  let s = seed | 0 || 1;
  for (let i = 0; i < dim; i++) {
    s ^= s << 13;
    s ^= s >>> 17;
    s ^= s << 5;
    out[i] = ((s | 0) / 2 ** 31);
  }
  return out;
}

async function newService(opts: Partial<ConstructorParameters<typeof MemoryService>[0]> = {}) {
  const svc = new MemoryService({
    dimensions: 8,
    persistenceEnabled: false,
    snapshotInterval: 0,
    ...opts,
  } as any);
  await svc.initialize();
  return svc;
}

describe('Phase 4 — MemoryConsolidator.sweepExpired', () => {
  it('Acceptance Criterion #4 — 1000 expired entries → 0 remaining + HNSW emptied', async () => {
    const svc = await newService();
    const consolidator = new MemoryConsolidator(svc as any);

    const past = Date.now() - 1;
    for (let i = 0; i < 1000; i++) {
      const entry = createDefaultEntry({
        key: `expired-${i}`,
        content: `content-${i}`,
        expiresAt: past,
      });
      entry.embedding = randomVec(8, i + 1);
      await svc.store(entry);
    }

    const adapter: any = svc.getAdapter();
    expect(adapter.entries.size).toBe(1000);
    expect(adapter.index.size).toBe(1000);

    const result = await consolidator.sweepExpired();

    expect(result.removed).toBe(1000);
    expect(result.remaining).toBe(0);
    expect(result.hnswRemoved).toBe(1000);
    expect(adapter.entries.size).toBe(0);
    expect(adapter.index.size).toBe(0);

    await svc.close();
  });

  it('leaves non-expired entries untouched', async () => {
    const svc = await newService();
    const consolidator = new MemoryConsolidator(svc as any);

    // 5 expired + 5 fresh
    for (let i = 0; i < 5; i++) {
      const entry = createDefaultEntry({
        key: `e-${i}`,
        content: `e-${i}`,
        expiresAt: Date.now() - 1,
      });
      entry.embedding = randomVec(8, i + 1);
      await svc.store(entry);
    }
    for (let i = 0; i < 5; i++) {
      const entry = createDefaultEntry({ key: `f-${i}`, content: `f-${i}` });
      entry.embedding = randomVec(8, i + 100);
      await svc.store(entry);
    }

    const result = await consolidator.sweepExpired();
    expect(result.removed).toBe(5);
    expect(result.remaining).toBe(5);
    await svc.close();
  });
});

describe('Phase 4 — MemoryConsolidator.dedup', () => {
  it('keep-newest: drops 10 duplicates and keeps newest by updatedAt', async () => {
    const svc = await newService();
    const consolidator = new MemoryConsolidator(svc as any);

    // 40 unique + 10 dupes of the same content as entry 0
    const dupContent = 'duplicate-marker';
    const newestTimestamps: number[] = [];
    for (let i = 0; i < 40; i++) {
      const entry = createDefaultEntry({ key: `u-${i}`, content: `unique-${i}` });
      entry.embedding = randomVec(8, i + 1);
      await svc.store(entry);
    }
    // The first dup has the OLDEST updatedAt; the last dup has the NEWEST.
    for (let i = 0; i < 10; i++) {
      const entry = createDefaultEntry({ key: `dup-${i}`, content: dupContent });
      entry.embedding = randomVec(8, i + 500);
      entry.updatedAt = 1_000_000_000 + i; // monotonic, last is newest
      await svc.store(entry);
      newestTimestamps.push(entry.updatedAt);
    }

    const result = await consolidator.dedup('keep-newest');
    expect(result.merged).toBe(9);
    expect(result.groups).toBe(1);

    // Survivor's updatedAt should equal the max of the dup timestamps
    const adapter: any = svc.getAdapter();
    const survivors = [...adapter.entries.values()].filter(
      (e: any) => e.content === dupContent
    );
    expect(survivors.length).toBe(1);
    expect(survivors[0].updatedAt).toBe(Math.max(...newestTimestamps));

    await svc.close();
  });

  it('keep-oldest: keeps the entry with the lowest createdAt', async () => {
    const svc = await newService();
    const consolidator = new MemoryConsolidator(svc as any);

    const ids: string[] = [];
    for (let i = 0; i < 3; i++) {
      const entry = createDefaultEntry({ key: `o-${i}`, content: 'same' });
      entry.embedding = randomVec(8, i + 1);
      entry.createdAt = 1000 + i; // i=0 is oldest
      await svc.store(entry);
      ids.push(entry.id);
    }

    const result = await consolidator.dedup('keep-oldest');
    expect(result.merged).toBe(2);

    const adapter: any = svc.getAdapter();
    expect(adapter.entries.size).toBe(1);
    expect(adapter.entries.has(ids[0])).toBe(true);
    await svc.close();
  });

  it('merge-tags: unions tag sets across the duplicates and keeps newest', async () => {
    const svc = await newService();
    const consolidator = new MemoryConsolidator(svc as any);

    for (let i = 0; i < 3; i++) {
      const entry = createDefaultEntry({
        key: `t-${i}`,
        content: 'same',
        tags: [`tag-${i}`, 'common'],
      });
      entry.embedding = randomVec(8, i + 1);
      entry.updatedAt = 1000 + i;
      await svc.store(entry);
    }

    const result = await consolidator.dedup('merge-tags');
    expect(result.merged).toBe(2);

    const adapter: any = svc.getAdapter();
    const survivors = [...adapter.entries.values()];
    expect(survivors.length).toBe(1);
    const survivor: any = survivors[0];
    expect(new Set(survivor.tags)).toEqual(new Set(['tag-0', 'tag-1', 'tag-2', 'common']));

    await svc.close();
  });
});

describe('Phase 4 — MemoryConsolidator.compactHnsw', () => {
  it('rebuilds the HNSW index so size matches entries.size after sweep', async () => {
    const svc = await newService();
    const consolidator = new MemoryConsolidator(svc as any);

    // Insert + expire half
    const half = 20;
    for (let i = 0; i < half * 2; i++) {
      const entry = createDefaultEntry({
        key: `c-${i}`,
        content: `c-${i}`,
        expiresAt: i < half ? Date.now() - 1 : undefined,
      });
      entry.embedding = randomVec(8, i + 1);
      await svc.store(entry);
    }

    await consolidator.sweepExpired();
    const result = await consolidator.compactHnsw();
    expect(result.before).toBeGreaterThanOrEqual(half);
    expect(result.after).toBe(half);

    const adapter: any = svc.getAdapter();
    expect(adapter.index.size).toBe(adapter.entries.size);

    await svc.close();
  });
});

describe('Phase 4 — MemoryService auto-run timer', () => {
  it('invokes consolidator.runAll() at the configured interval', async () => {
    const svc = new MemoryService({
      dimensions: 8,
      persistenceEnabled: false,
      snapshotInterval: 0,
      consolidator: { autoRun: true, intervalMs: 50 },
    });
    await svc.initialize();

    // Spy on the lazily-loaded consolidator. getConsolidator() returns a
    // singleton, so swap its runAll for a spy after first construction.
    const consolidator = await svc.getConsolidator();
    const spy = vi.spyOn(consolidator, 'runAll');

    // Wait long enough for at least one tick.
    await new Promise((r) => setTimeout(r, 180));

    expect(spy).toHaveBeenCalled();
    await svc.close();
  });

  it('close() clears the consolidator timer', async () => {
    const svc = new MemoryService({
      dimensions: 8,
      persistenceEnabled: false,
      snapshotInterval: 0,
      consolidator: { autoRun: true, intervalMs: 50 },
    });
    await svc.initialize();
    const consolidator = await svc.getConsolidator();
    const spy = vi.spyOn(consolidator, 'runAll');

    await svc.close();
    await new Promise((r) => setTimeout(r, 150));

    // No new calls after close()
    const callCountAtClose = spy.mock.calls.length;
    await new Promise((r) => setTimeout(r, 150));
    expect(spy.mock.calls.length).toBe(callCountAtClose);
  });
});

describe('Phase 4 — nightlyLearner controller delegates to MemoryConsolidator', () => {
  it('returns a wrapper bound to consolidator.runAll when memoryService is registered', async () => {
    const svc = await newService();
    const registry = new ControllerRegistry();
    await registry.initialize({ memoryService: svc });

    const inst = registry.get<any>('nightlyLearner');
    expect(inst).toBeTruthy();
    expect(inst.source).toBe('memory-consolidator');
    expect(typeof inst.runAll).toBe('function');

    const result = await inst.runAll();
    expect(result).toHaveProperty('sweep');
    expect(result).toHaveProperty('dedup');
    expect(result).toHaveProperty('compact');

    await registry.shutdown();
    await svc.close();
  });
});

/**
 * MemoryConsolidator — ADR-125 Phase 4
 *
 * Periodic maintenance for the in-memory state owned by {@link UnifiedMemoryService}.
 *
 * Operations:
 * - `sweepExpired()` — drop entries past `expiresAt` from all indexes (including HNSW).
 * - `dedup(strategy)` — collapse content-hash duplicates per strategy.
 * - `compactHnsw()` — rebuild the HNSW index from current `entries`.
 * - `runAll()` — sweep → dedup → compact in order.
 *
 * Invoked from two paths:
 * 1. {@link UnifiedMemoryService}'s lifecycle (background timer when
 *    `consolidator.autoRun === true`, plus `close()`).
 * 2. The AgentDB `nightlyLearner` controller (`src/controller-registry.ts`)
 *    delegates to `runAll()` instead of hitting AgentDB directly.
 *
 * Phase 3 placeholder lives in this file too — it provides the typed
 * surface that {@link UnifiedMemoryService.getConsolidator} resolves to.
 * The real implementation lands with Phase 4.
 *
 * @module v3/memory/consolidator
 */

import { createHash } from 'node:crypto';
import { HNSWIndex } from './hnsw-index.js';
import type { MemoryEntry } from './types.js';

/**
 * Strategy for resolving content-hash duplicates inside {@link MemoryConsolidator.dedup}.
 */
export type DedupStrategy = 'keep-newest' | 'keep-oldest' | 'merge-tags';

export interface ConsolidatorOptions {
  /** Default strategy when `dedup()` is invoked with no argument. */
  dedupStrategy?: DedupStrategy;
  /** Used by `MemoryService` when scheduling automatic runs (ms). */
  intervalMs?: number;
}

export interface SweepResult {
  removed: number;
  remaining: number;
  hnswRemoved: number;
}

export interface DedupResult {
  merged: number;
  groups: number;
}

export interface CompactResult {
  before: number;
  after: number;
  durationMs: number;
}

export interface ConsolidationResult {
  sweep: SweepResult;
  dedup: DedupResult;
  compact: CompactResult;
  totalDurationMs: number;
}

/**
 * Minimal surface the consolidator needs from `UnifiedMemoryService`. Avoids
 * a circular type import.
 */
interface ServiceLike {
  getAdapter(): {
    // Internals we mutate. Cast-safe at runtime.
    entries: Map<string, MemoryEntry>;
    namespaceIndex: Map<string, Set<string>>;
    keyIndex: Map<string, string>;
    tagIndex: Map<string, Set<string>>;
    // Public HNSW accessor exists on AgentDBAdapter; cast through.
    [key: string]: any;
  };
}

export class MemoryConsolidator {
  constructor(
    private readonly service: ServiceLike,
    private readonly opts: ConsolidatorOptions = {}
  ) {}

  /**
   * Drop all entries whose `expiresAt` is in the past.
   */
  async sweepExpired(): Promise<SweepResult> {
    const adapter = this.service.getAdapter() as any;
    const entries: Map<string, MemoryEntry> = adapter.entries;
    const namespaceIndex: Map<string, Set<string>> = adapter.namespaceIndex;
    const keyIndex: Map<string, string> = adapter.keyIndex;
    const tagIndex: Map<string, Set<string>> = adapter.tagIndex;
    const index: HNSWIndex = adapter.index;

    const now = Date.now();
    const toRemove: MemoryEntry[] = [];
    for (const entry of entries.values()) {
      if (entry.expiresAt != null && entry.expiresAt < now) {
        toRemove.push(entry);
      }
    }

    let hnswRemoved = 0;
    for (const entry of toRemove) {
      entries.delete(entry.id);
      namespaceIndex.get(entry.namespace)?.delete(entry.id);
      keyIndex.delete(`${entry.namespace}:${entry.key}`);
      for (const tag of entry.tags) tagIndex.get(tag)?.delete(entry.id);
      if (entry.embedding) {
        const removed = await index.removePoint(entry.id);
        if (removed) hnswRemoved += 1;
      }
    }

    // Clean up empty namespace/tag sets to keep memory bounded
    for (const [ns, ids] of namespaceIndex) {
      if (ids.size === 0) namespaceIndex.delete(ns);
    }
    for (const [tag, ids] of tagIndex) {
      if (ids.size === 0) tagIndex.delete(tag);
    }

    return {
      removed: toRemove.length,
      remaining: entries.size,
      hnswRemoved,
    };
  }

  /**
   * Collapse content-hash duplicates across all namespaces per `strategy`.
   *
   * - `keep-newest`: keep the entry with the highest `updatedAt`, drop the rest.
   * - `keep-oldest`: keep the entry with the lowest `createdAt`, drop the rest.
   * - `merge-tags`: keep newest, but union the tag sets of the duplicates first.
   */
  async dedup(strategy?: DedupStrategy): Promise<DedupResult> {
    const adapter = this.service.getAdapter() as any;
    const entries: Map<string, MemoryEntry> = adapter.entries;
    const namespaceIndex: Map<string, Set<string>> = adapter.namespaceIndex;
    const keyIndex: Map<string, string> = adapter.keyIndex;
    const tagIndex: Map<string, Set<string>> = adapter.tagIndex;
    const index: HNSWIndex = adapter.index;

    const effective = strategy ?? this.opts.dedupStrategy ?? 'keep-newest';

    // Bucket by content hash
    const buckets = new Map<string, MemoryEntry[]>();
    for (const entry of entries.values()) {
      const hash = createHash('sha256').update(entry.content).digest('hex');
      const bucket = buckets.get(hash);
      if (bucket) bucket.push(entry);
      else buckets.set(hash, [entry]);
    }

    let merged = 0;
    let dupGroups = 0;
    for (const bucket of buckets.values()) {
      if (bucket.length <= 1) continue;
      dupGroups += 1;

      // Choose keeper
      let keeper: MemoryEntry;
      if (effective === 'keep-oldest') {
        keeper = bucket.reduce((acc, e) =>
          e.createdAt < acc.createdAt ? e : acc
        );
      } else {
        // keep-newest + merge-tags share this branch
        keeper = bucket.reduce((acc, e) =>
          e.updatedAt > acc.updatedAt ? e : acc
        );
      }

      if (effective === 'merge-tags') {
        const tagSet = new Set<string>(keeper.tags);
        for (const e of bucket) for (const t of e.tags) tagSet.add(t);
        const oldTags = keeper.tags;
        keeper.tags = [...tagSet];
        // Update tagIndex membership for newly-added tags
        for (const t of keeper.tags) {
          if (!oldTags.includes(t)) {
            if (!tagIndex.has(t)) tagIndex.set(t, new Set());
            tagIndex.get(t)!.add(keeper.id);
          }
        }
      }

      // Drop everyone except the keeper
      for (const e of bucket) {
        if (e.id === keeper.id) continue;
        entries.delete(e.id);
        namespaceIndex.get(e.namespace)?.delete(e.id);
        const compositeKey = `${e.namespace}:${e.key}`;
        if (keyIndex.get(compositeKey) === e.id) {
          keyIndex.delete(compositeKey);
        }
        for (const tag of e.tags) tagIndex.get(tag)?.delete(e.id);
        if (e.embedding) {
          await index.removePoint(e.id);
        }
        merged += 1;
      }
    }

    return { merged, groups: dupGroups };
  }

  /**
   * Rebuild the HNSW index from the current set of entries with embeddings.
   * Returns a count snapshot + duration.
   */
  async compactHnsw(): Promise<CompactResult> {
    const adapter = this.service.getAdapter() as any;
    const entries: Map<string, MemoryEntry> = adapter.entries;
    const index: HNSWIndex = adapter.index;

    const before = index.size;
    const t0 = Date.now();

    // Build a fresh HNSW from current entries that have embeddings.
    const cfg = index.getConfig();
    const fresh = new HNSWIndex({
      dimensions: cfg.dimensions,
      M: cfg.M,
      efConstruction: cfg.efConstruction,
      maxElements: cfg.maxElements,
      metric: cfg.metric,
    });

    for (const entry of entries.values()) {
      if (entry.embedding) {
        try {
          await fresh.addPoint(entry.id, entry.embedding);
        } catch {
          // Tolerate dimension mismatches in malformed datasets.
        }
      }
    }

    // Swap pointers atomically and re-forward events
    adapter.index = fresh;
    if (typeof adapter.emit === 'function') {
      fresh.on('point:added', (data: any) => adapter.emit('index:added', data));
    }

    const durationMs = Date.now() - t0;
    return { before, after: fresh.size, durationMs };
  }

  /**
   * Sweep → dedup → compact. Used by the background timer and by the
   * `nightlyLearner` AgentDB controller.
   */
  async runAll(): Promise<ConsolidationResult> {
    const start = Date.now();
    const sweep = await this.sweepExpired();
    const dedup = await this.dedup();
    const compact = await this.compactHnsw();
    return {
      sweep,
      dedup,
      compact,
      totalDurationMs: Date.now() - start,
    };
  }
}

export default MemoryConsolidator;

/**
 * Comprehensive tests for ControllerRegistry (ADR-053)
 *
 * Covers:
 * - Initialization lifecycle and level-based ordering
 * - Graceful degradation (isolated controller failures)
 * - Config-driven activation
 * - Health check aggregation
 * - Shutdown ordering
 * - Cross-platform path handling (Linux/Mac/Windows)
 * - AgentDB unavailable scenarios
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import {
  ControllerRegistry,
  INIT_LEVELS,
  type RuntimeConfig,
  type ControllerName,
  type RegistryHealthReport,
} from './controller-registry.js';
import { LearningBridge } from './learning-bridge.js';
import { MemoryGraph } from './memory-graph.js';
import { TieredCacheManager } from './cache-manager.js';
import type {
  IMemoryBackend,
  MemoryEntry,
  MemoryQuery,
  MemoryEntryUpdate,
  SearchOptions,
  SearchResult,
  BackendStats,
  HealthCheckResult,
  MemoryType,
} from './types.js';

// ===== Mock Backend =====

function createMockBackend(): IMemoryBackend {
  const entries = new Map<string, MemoryEntry>();

  return {
    async initialize() {},
    async shutdown() {},
    async store(entry: MemoryEntry) {
      entries.set(entry.id, entry);
    },
    async get(id: string) {
      return entries.get(id) ?? null;
    },
    async getByKey(namespace: string, key: string) {
      for (const e of entries.values()) {
        if (e.namespace === namespace && e.key === key) return e;
      }
      return null;
    },
    async update(id: string, update: MemoryEntryUpdate) {
      const entry = entries.get(id);
      if (!entry) return null;
      Object.assign(entry, update, { updatedAt: Date.now() });
      return entry;
    },
    async delete(id: string) {
      return entries.delete(id);
    },
    async query(query: MemoryQuery) {
      const results = Array.from(entries.values());
      if (query.namespace) {
        return results.filter((e) => e.namespace === query.namespace).slice(0, query.limit);
      }
      return results.slice(0, query.limit);
    },
    async search(_embedding: Float32Array, _options: SearchOptions): Promise<SearchResult[]> {
      return [];
    },
    async bulkInsert(newEntries: MemoryEntry[]) {
      for (const entry of newEntries) entries.set(entry.id, entry);
    },
    async bulkDelete(ids: string[]) {
      let count = 0;
      for (const id of ids) {
        if (entries.delete(id)) count++;
      }
      return count;
    },
    async count(namespace?: string) {
      if (namespace) {
        return Array.from(entries.values()).filter((e) => e.namespace === namespace).length;
      }
      return entries.size;
    },
    async listNamespaces() {
      return [...new Set(Array.from(entries.values()).map((e) => e.namespace))];
    },
    async clearNamespace(namespace: string) {
      let count = 0;
      for (const [id, entry] of entries) {
        if (entry.namespace === namespace) {
          entries.delete(id);
          count++;
        }
      }
      return count;
    },
    async getStats(): Promise<BackendStats> {
      return {
        totalEntries: entries.size,
        entriesByNamespace: {},
        entriesByType: { episodic: 0, semantic: 0, procedural: 0, working: 0, cache: 0 },
        memoryUsage: 0,
        avgQueryTime: 0,
        avgSearchTime: 0,
      };
    },
    async healthCheck(): Promise<HealthCheckResult> {
      return {
        status: 'healthy',
        components: {
          storage: { status: 'healthy', latency: 0 },
          index: { status: 'healthy', latency: 0 },
          cache: { status: 'healthy', latency: 0 },
        },
        timestamp: Date.now(),
        issues: [],
        recommendations: [],
      };
    },
  };
}

// ===== Test Suite =====

describe('ControllerRegistry', () => {
  let registry: ControllerRegistry;
  let mockBackend: IMemoryBackend;

  beforeEach(() => {
    registry = new ControllerRegistry();
    mockBackend = createMockBackend();
  });

  afterEach(async () => {
    if (registry.isInitialized()) {
      await registry.shutdown();
    }
  });

  // ----- Lifecycle Tests -----

  describe('initialization lifecycle', () => {
    it('should initialize with default config', async () => {
      await registry.initialize({ backend: mockBackend });
      expect(registry.isInitialized()).toBe(true);
    });

    it('should not initialize twice', async () => {
      await registry.initialize({ backend: mockBackend });
      const count1 = registry.getActiveCount();
      await registry.initialize({ backend: mockBackend });
      expect(registry.getActiveCount()).toBe(count1);
    });

    it('should initialize with empty config', async () => {
      await registry.initialize();
      expect(registry.isInitialized()).toBe(true);
    });

    it('should emit initialized event', async () => {
      const handler = vi.fn();
      registry.on('initialized', handler);
      await registry.initialize({ backend: mockBackend });
      expect(handler).toHaveBeenCalledOnce();
      expect(handler).toHaveBeenCalledWith(
        expect.objectContaining({
          initTimeMs: expect.any(Number),
          activeControllers: expect.any(Number),
          totalControllers: expect.any(Number),
        }),
      );
    });

    it('should emit controller:initialized events', async () => {
      const handler = vi.fn();
      registry.on('controller:initialized', handler);
      await registry.initialize({ backend: mockBackend });
      // At minimum learningBridge and tieredCache should init
      expect(handler.mock.calls.length).toBeGreaterThanOrEqual(1);
    });

    it('should track init time', async () => {
      await registry.initialize({ backend: mockBackend });
      const report = await registry.healthCheck();
      expect(report.initTimeMs).toBeGreaterThan(0);
    });
  });

  // ----- Level-Based Ordering -----

  describe('level-based initialization ordering', () => {
    it('should define 7 initialization levels (0-6)', () => {
      expect(INIT_LEVELS).toHaveLength(7);
      expect(INIT_LEVELS[0].level).toBe(0);
      expect(INIT_LEVELS[6].level).toBe(6);
    });

    it('should have monotonically increasing levels', () => {
      for (let i = 1; i < INIT_LEVELS.length; i++) {
        expect(INIT_LEVELS[i].level).toBeGreaterThan(INIT_LEVELS[i - 1].level);
      }
    });

    it('should include core controllers in level 1', () => {
      const level1 = INIT_LEVELS.find((l) => l.level === 1);
      expect(level1?.controllers).toContain('reasoningBank');
      expect(level1?.controllers).toContain('learningBridge');
      expect(level1?.controllers).toContain('tieredCache');
    });

    it('should include graph controllers in level 2', () => {
      const level2 = INIT_LEVELS.find((l) => l.level === 2);
      expect(level2?.controllers).toContain('memoryGraph');
      expect(level2?.controllers).toContain('agentMemoryScope');
    });

    it('should include specialization controllers in level 3', () => {
      const level3 = INIT_LEVELS.find((l) => l.level === 3);
      expect(level3?.controllers).toContain('skills');
      expect(level3?.controllers).toContain('explainableRecall');
      expect(level3?.controllers).toContain('reflexion');
    });

    it('should include causal controllers in level 4', () => {
      const level4 = INIT_LEVELS.find((l) => l.level === 4);
      expect(level4?.controllers).toContain('causalGraph');
      expect(level4?.controllers).toContain('nightlyLearner');
    });

    it('should include advanced services in level 5', () => {
      const level5 = INIT_LEVELS.find((l) => l.level === 5);
      expect(level5?.controllers).toContain('graphTransformer');
      expect(level5?.controllers).toContain('sonaTrajectory');
    });

    it('should include session management in level 6', () => {
      const level6 = INIT_LEVELS.find((l) => l.level === 6);
      expect(level6?.controllers).toContain('federatedSession');
    });

    it('should not have duplicate controller names across levels', () => {
      const allNames: ControllerName[] = [];
      for (const level of INIT_LEVELS) {
        for (const name of level.controllers) {
          expect(allNames).not.toContain(name);
          allNames.push(name);
        }
      }
    });
  });

  // ----- Graceful Degradation -----

  describe('graceful degradation', () => {
    it('should continue when AgentDB is unavailable', async () => {
      // No AgentDB module available — should still init CLI-layer controllers
      await registry.initialize({ backend: mockBackend });
      expect(registry.isInitialized()).toBe(true);
    });

    it('should mark failed controllers as unavailable without crashing', async () => {
      await registry.initialize({ backend: mockBackend });
      const report = await registry.healthCheck();

      // Some controllers should be unavailable (no AgentDB)
      // but the registry itself should be functional
      expect(report.status).not.toBe('unhealthy');
    });

    it('should emit controller:failed for failed controllers', async () => {
      const handler = vi.fn();
      registry.on('controller:failed', handler);

      // Enable a controller that requires AgentDB (which is unavailable)
      await registry.initialize({
        backend: mockBackend,
        controllers: { reasoningBank: true },
      });

      // ReasoningBank requires AgentDB, so it should fail or be unavailable
      // The exact behavior depends on whether agentdb is importable
    });

    it('should handle null backend gracefully', async () => {
      await registry.initialize({});
      expect(registry.isInitialized()).toBe(true);
      expect(registry.getBackend()).toBeNull();
    });

    it('should isolate controller failures from each other', async () => {
      // Initialize with backend - learningBridge and tieredCache should work
      await registry.initialize({ backend: mockBackend });

