/**
 * DatabaseProvider - Platform-aware database selection
 *
 * Automatically selects best backend:
 * - Linux/macOS: better-sqlite3 (native, fast)
 * - Windows: sql.js (WASM, universal) when native fails
 * - Fallback: JSON file storage
 *
 * @module v3/memory/database-provider
 */

import { platform } from 'node:os';
import { existsSync } from 'node:fs';
import {
  IMemoryBackend,
  MemoryEntry,
  MemoryEntryInput,
  MemoryQuery,
  SearchOptions,
  SearchResult,
  BackendStats,
  HealthCheckResult,
  MemoryEntryUpdate,
} from './types.js';
import { SQLiteBackend, SQLiteBackendConfig } from './sqlite-backend.js';
import { SqlJsBackend, SqlJsBackendConfig } from './sqljs-backend.js';
import type { EmbeddingGenerator } from './types.js';

/**
 * Available database provider types.
 *
 * ADR-125 Phase 2 added `'hybrid'` and `'agentdb'` so the package can deliver
 * ADR-009's "HybridBackend by default" promise through `createDatabase`.
 */
export type DatabaseProvider =
  | 'better-sqlite3'
  | 'sql.js'
  | 'json'
  | 'rvf'
  | 'hybrid'
  | 'agentdb'
  | 'auto';

/**
 * Database creation options
 */
export interface DatabaseOptions {
  /** Preferred provider (auto = platform-aware selection) */
  provider?: DatabaseProvider;

  /** Enable verbose logging */
  verbose?: boolean;

  /** Enable WAL mode (better-sqlite3 only) */
  walMode?: boolean;

  /** Enable query optimization */
  optimize?: boolean;

  /** Default namespace */
  defaultNamespace?: string;

  /** Maximum entries before auto-cleanup */
  maxEntries?: number;

  /** Auto-persist interval for sql.js (milliseconds) */
  autoPersistInterval?: number;

  /** Path to sql.js WASM file */
  wasmPath?: string;

  /**
   * Embedding generator. Required for `'hybrid'` and `'agentdb'` providers
   * (and recommended for semantic search on any provider).
   */
  embeddingGenerator?: EmbeddingGenerator;

  /** Vector dimensions for `'hybrid'` and `'agentdb'` providers (default 1536) */
  dimensions?: number;
}

/**
 * Platform detection result
 */
interface PlatformInfo {
  os: string;
  isWindows: boolean;
  isMacOS: boolean;
  isLinux: boolean;
  recommendedProvider: DatabaseProvider;
}

/**
 * Detect platform and recommend provider
 */
function detectPlatform(): PlatformInfo {
  const os = platform();
  const isWindows = os === 'win32';
  const isMacOS = os === 'darwin';
  const isLinux = os === 'linux';

  // Recommend better-sqlite3 for Unix-like systems, sql.js for Windows
  const recommendedProvider: DatabaseProvider = isWindows ? 'sql.js' : 'better-sqlite3';

  return {
    os,
    isWindows,
    isMacOS,
    isLinux,
    recommendedProvider,
  };
}

/**
 * Test if RVF backend is available (always true — pure-TS fallback)
 */
async function testRvf(): Promise<boolean> {
  return true;
}

/**
 * Test if better-sqlite3 is available and working
 */
async function testBetterSqlite3(): Promise<boolean> {
  try {
    const Database = (await import('better-sqlite3')).default;
    const testDb = new Database(':memory:');
    testDb.close();
    return true;
  } catch (error) {
    return false;
  }
}

/**
 * Test if sql.js is available and working
 */
async function testSqlJs(): Promise<boolean> {
  try {
    const initSqlJs = (await import('sql.js')).default;
    const SQL = await initSqlJs();
    const testDb = new SQL.Database();
    testDb.close();
    return true;
  } catch (error) {
    return false;
  }
}

/**
 * Select best available provider
 */
async function selectProvider(
  preferred?: DatabaseProvider,
  verbose: boolean = false
): Promise<DatabaseProvider> {
  if (preferred && preferred !== 'auto') {
    if (verbose) {
      console.log(`[DatabaseProvider] Using explicitly specified provider: ${preferred}`);
    }
    return preferred;
  }

  const platformInfo = detectPlatform();

  if (verbose) {
    console.log(`[DatabaseProvider] Platform detected: ${platformInfo.os}`);
    console.log(`[DatabaseProvider] Recommended provider: ${platformInfo.recommendedProvider}`);
  }

  // Try RVF first (always available via pure-TS fallback, native when @ruvector/rvf installed)
  if (await testRvf()) {
    if (verbose) {
      console.log('[DatabaseProvider] RVF backend available');
    }
    return 'rvf';
  }

  // Try recommended provider
  if (platformInfo.recommendedProvider === 'better-sqlite3') {
    if (await testBetterSqlite3()) {
      if (verbose) {
        console.log('[DatabaseProvider] better-sqlite3 available and working');
      }
      return 'better-sqlite3';
    } else if (verbose) {
      console.log('[DatabaseProvider] better-sqlite3 not available, trying sql.js');
    }
  }

  // Try sql.js as fallback
  if (await testSqlJs()) {
    if (verbose) {
      console.log('[DatabaseProvider] sql.js available and working');
    }
    return 'sql.js';
  } else if (verbose) {
    console.log('[DatabaseProvider] sql.js not available, using JSON fallback');
  }

  // Final fallback to JSON
  return 'json';
}

/**
 * Create a database instance with platform-aware provider selection
 *
 * @param path - Database file path (:memory: for in-memory)
 * @param options - Database configuration options
 * @returns Initialized database backend
 *
 * @example
 * ```typescript
 * // Auto-select best provider for platform
 * const db = await createDatabase('./data/memory.db');
 *
 * // Force specific provider
 * const db = await createDatabase('./data/memory.db', {
 *   provider: 'sql.js'
 * });
 *
 * // With custom options
 * const db = await createDatabase('./data/memory.db', {
 *   verbose: true,
 *   optimize: true,
 *   autoPersistInterval: 10000
 * });
 * ```
 */
export async function createDatabase(
  path: string,
  options: DatabaseOptions = {}
): Promise<IMemoryBackend> {
  const {
    provider = 'auto',
    verbose = false,
    walMode = true,
    optimize = true,
    defaultNamespace = 'default',
    maxEntries = 1000000,
    autoPersistInterval = 5000,
    wasmPath,
    embeddingGenerator,
    dimensions = 1536,
  } = options;

  // Select provider
  const selectedProvider = await selectProvider(provider, verbose);

  if (verbose) {
    console.log(`[DatabaseProvider] Creating database with provider: ${selectedProvider}`);
    console.log(`[DatabaseProvider] Database path: ${path}`);
  }

  let backend: IMemoryBackend;

  switch (selectedProvider) {
    case 'better-sqlite3': {
      const config: Partial<SQLiteBackendConfig> = {
        databasePath: path,
        walMode,
        optimize,
        defaultNamespace,
        maxEntries,
        verbose,
      };

      backend = new SQLiteBackend(config);
      break;
    }

    case 'sql.js': {
      const config: Partial<SqlJsBackendConfig> = {
        databasePath: path,
        optimize,
        defaultNamespace,
        maxEntries,
        verbose,
        autoPersistInterval,
        wasmPath,
      };

      backend = new SqlJsBackend(config);
      break;
    }

    case 'rvf': {
      const { RvfBackend } = await import('./rvf-backend.js');
      backend = new RvfBackend({
        databasePath: path.replace(/\.(db|json)$/, '.rvf'),
        dimensions,
        verbose,
        defaultNamespace,
        autoPersistInterval,
      });
      break;
    }

    case 'hybrid': {
      // ADR-009: SQLite for structured queries + AgentDB for semantic search.
      const { HybridBackend } = await import('./hybrid-backend.js');
      backend = new HybridBackend({
        sqlite: {
          databasePath: path,
          walMode,
          optimize,
          defaultNamespace,
          maxEntries,
          verbose,
        },
        agentdb: {
          dbPath: path.replace(/\.(db|json|rvf)$/, '.agentdb'),
          namespace: defaultNamespace,
          vectorDimension: dimensions,
          embeddingGenerator,
          maxEntries,
        },
        defaultNamespace,
        embeddingGenerator,
      });
      break;
    }

    case 'agentdb': {
      const { AgentDBBackend } = await import('./agentdb-backend.js');
      backend = new AgentDBBackend({
        dbPath: path,
        namespace: defaultNamespace,
        vectorDimension: dimensions,
        embeddingGenerator,
        maxEntries,
      });
      break;
    }

    case 'json': {
      // Simple JSON file backend (minimal implementation)
      backend = new JsonBackend(path, verbose);
      break;
    }

    default:
      throw new Error(`Unknown database provider: ${selectedProvider}`);
  }

  // Initialize the backend
  await backend.initialize();

  if (verbose) {
    console.log(`[DatabaseProvider] Database initialized successfully`);
  }

  return backend;
}

/**
 * Get platform information
 */
export function getPlatformInfo(): PlatformInfo {
  return detectPlatform();
}

/**
 * Check which providers are available
 */
export async function getAvailableProviders(): Promise<{
  rvf: boolean;
  betterSqlite3: boolean;
  sqlJs: boolean;
  json: boolean;
}> {
  return {
    rvf: true,
    betterSqlite3: await testBetterSqlite3(),
    sqlJs: await testSqlJs(),
    json: true,
  };
}

// ===== JSON Fallback Backend =====

/**
 * Simple JSON file backend for when no SQLite is available
 */
class JsonBackend implements IMemoryBackend {
  private entries: Map<string, MemoryEntry> = new Map();
  private path: string;
  private verbose: boolean;
  private initialized: boolean = false;

  constructor(path: string, verbose: boolean = false) {
    this.path = path;
    this.verbose = verbose;
  }

  async initialize(): Promise<void> {
    if (this.initialized) return;

    // Load from file if exists
    if (this.path !== ':memory:' && existsSync(this.path)) {
      try {
        const fs = await import('node:fs/promises');
        const data = await fs.readFile(this.path, 'utf-8');
        const entries = JSON.parse(data);

        for (const entry of entries) {
          // Convert embedding array back to Float32Array
          if (entry.embedding) {
            entry.embedding = new Float32Array(entry.embedding);
          }
          this.entries.set(entry.id, entry);
        }

        if (this.verbose) {
          console.log(`[JsonBackend] Loaded ${this.entries.size} entries from ${this.path}`);
        }
      } catch (error) {
        if (this.verbose) {
          console.error('[JsonBackend] Error loading file:', error);
        }
      }
    }

    this.initialized = true;
  }

  async shutdown(): Promise<void> {
    await this.persist();
    this.initialized = false;
  }

  async store(entry: MemoryEntry): Promise<void> {
    this.entries.set(entry.id, entry);
    await this.persist();
  }

  async get(id: string): Promise<MemoryEntry | null> {
    return this.entries.get(id) || null;
  }

  async getByKey(namespace: string, key: string): Promise<MemoryEntry | null> {
    for (const entry of this.entries.values()) {
      if (entry.namespace === namespace && entry.key === key) {
        return entry;
      }
    }
    return null;
  }

  async update(id: string, updateData: MemoryEntryUpdate): Promise<MemoryEntry | null> {
    const entry = this.entries.get(id);
    if (!entry) return null;

    const updated = { ...entry, ...updateData, updatedAt: Date.now(), version: entry.version + 1 };
    this.entries.set(id, updated);
    await this.persist();
    return updated;
  }

  async delete(id: string): Promise<boolean> {
    const result = this.entries.delete(id);
    await this.persist();
    return result;
  }

  async query(query: MemoryQuery): Promise<MemoryEntry[]> {
    let results = Array.from(this.entries.values());

    if (query.namespace) {
      results = results.filter((e) => e.namespace === query.namespace);
    }

    if (query.key) {
      results = results.filter((e) => e.key === query.key);
    }

    if (query.tags && query.tags.length > 0) {
      results = results.filter((e) => query.tags!.every((tag) => e.tags.includes(tag)));
    }

    return results.slice(0, query.limit);
  }

  async search(embedding: Float32Array, options: SearchOptions): Promise<SearchResult[]> {
    // Simple brute-force search
    const results: SearchResult[] = [];

    for (const entry of this.entries.values()) {
      if (!entry.embedding) continue;

      const similarity = this.cosineSimilarity(embedding, entry.embedding);
      if (options.threshold && similarity < options.threshold) continue;

      results.push({ entry, score: similarity, distance: 1 - similarity });
    }

    results.sort((a, b) => b.score - a.score);
    return results.slice(0, options.k);
  }

  async bulkInsert(entries: MemoryEntry[]): Promise<void> {
    for (const entry of entries) {
      this.entries.set(entry.id, entry);
    }
    await this.persist();
  }

  async bulkDelete(ids: string[]): Promise<number> {
    let count = 0;
    for (const id of ids) {
      if (this.entries.delete(id)) count++;
    }
    await this.persist();
    return count;
  }

  async count(namespace?: string): Promise<number> {
    if (!namespace) return this.entries.size;

    let count = 0;
    for (const entry of this.entries.values()) {
      if (entry.namespace === namespace) count++;
    }
    return count;
  }

  async listNamespaces(): Promise<string[]> {
    const namespaces = new Set<string>();
    for (const entry of this.entries.values()) {
      namespaces.add(entry.namespace);
    }
    return Array.from(namespaces);
  }

  async clearNamespace(namespace: string): Promise<number> {
    let count = 0;
    for (const [id, entry] of this.entries.entries()) {
      if (entry.namespace === namespace) {
        this.entries.delete(id);
        count++;
      }
    }
    await this.persist();
    return count;
  }

  async getStats(): Promise<BackendStats> {
    return {
      totalEntries: this.entries.size,
      entriesByNamespace: {},
      entriesByType: {} as any,
      memoryUsage: 0,
      avgQueryTime: 0,
      avgSearchTime: 0,
    };
  }

  async healthCheck(): Promise<HealthCheckResult> {
    return {
      status: 'healthy',
      components: {
        storage: { status: 'healthy', latency: 0 },
        index: { status: 'healthy', latency: 0 },
        cache: { status: 'healthy', latency: 0 },
      },
      timestamp: Date.now(),
      issues: [],
      recommendations: ['Consider using SQLite backend for better performance'],
    };
  }

  private async persist(): Promise<void> {
    if (this.path === ':memory:') return;

    const fs = await import('node:fs/promises');
    const entries = Array.from(this.entries.values()).map((e) => ({
      ...e,
      // Convert Float32Array to regular array for JSON serialization
      embedding: e.embedding ? Array.from(e.embedding) : undefined,
    }));

    await fs.writeFile(this.path, JSON.stringify(entries, null, 2));
  }

  private cosineSimilarity(a: Float32Array, b: Float32Array): number {
    let dot = 0;
    let normA = 0;
    let normB = 0;

    for (let i = 0; i < a.length; i++) {
      dot += a[i] * b[i];
      normA += a[i] * a[i];
      normB += b[i] * b[i];
    }

    if (normA === 0 || normB === 0) return 0;
    return dot / (Math.sqrt(normA) * Math.sqrt(normB));
  }
}

/**
 * Memory Entry Entity - Domain Layer
 *
 * Core domain entity representing a stored memory item.
 * Implements DDD principles with encapsulated business logic.
 *
 * @module v3/memory/domain/entities
 */

import { randomUUID } from 'crypto';

/**
 * Memory entry types
 */
export type MemoryType = 'semantic' | 'episodic' | 'procedural' | 'working';

/**
 * Memory entry status
 */
export type MemoryStatus = 'active' | 'archived' | 'deleted';

/**
 * Memory entry properties
 */
export interface MemoryEntryProps {
  id?: string;
  namespace: string;
  key: string;
  value: unknown;
  type: MemoryType;
  vector?: Float32Array;
  metadata?: Record<string, unknown>;
  accessCount?: number;
  lastAccessedAt?: Date;
  createdAt?: Date;
  updatedAt?: Date;
  status?: MemoryStatus;
  ttl?: number; // Time-to-live in milliseconds
}

/**
 * Memory Entry - Aggregate Root
 *
 * Represents a single memory entry with business logic
 * for access tracking, expiration, and state management.
 */
export class MemoryEntry {
  private _id: string;
  private _namespace: string;
  private _key: string;
  private _value: unknown;
  private _type: MemoryType;
  private _vector?: Float32Array;
  private _metadata: Record<string, unknown>;
  private _accessCount: number;
  private _lastAccessedAt: Date;
  private _createdAt: Date;
  private _updatedAt: Date;
  private _status: MemoryStatus;
  private _ttl?: number;

  private constructor(props: MemoryEntryProps) {
    const now = new Date();
    this._id = props.id ?? randomUUID();
    this._namespace = props.namespace;
    this._key = props.key;
    this._value = props.value;
    this._type = props.type;
    this._vector = props.vector;
    this._metadata = props.metadata ?? {};
    this._accessCount = props.accessCount ?? 0;
    this._lastAccessedAt = props.lastAccessedAt ?? now;
    this._createdAt = props.createdAt ?? now;
    this._updatedAt = props.updatedAt ?? now;
    this._status = props.status ?? 'active';
    this._ttl = props.ttl;
  }

  /**
   * Factory method - Create new memory entry
   */
  static create(props: MemoryEntryProps): MemoryEntry {
    return new MemoryEntry(props);
  }

  /**
   * Factory method - Reconstruct from persistence
   */
  static fromPersistence(props: MemoryEntryProps): MemoryEntry {
    return new MemoryEntry(props);
  }

  // Getters
  get id(): string {
    return this._id;
  }

  get namespace(): string {
    return this._namespace;
  }

  get key(): string {
    return this._key;
  }

  get value(): unknown {
    return this._value;
  }

  get type(): MemoryType {
    return this._type;
  }

  get vector(): Float32Array | undefined {
    return this._vector;
  }

  get metadata(): Record<string, unknown> {
    return { ...this._metadata };
  }

  get accessCount(): number {
    return this._accessCount;
  }

  get lastAccessedAt(): Date {
    return new Date(this._lastAccessedAt);
  }

  get createdAt(): Date {
    return new Date(this._createdAt);
  }

  get updatedAt(): Date {
    return new Date(this._updatedAt);
  }

  get status(): MemoryStatus {
    return this._status;
  }

  get ttl(): number | undefined {
    return this._ttl;
  }

  get compositeKey(): string {
    return `${this._namespace}:${this._key}`;
  }

  // Business Logic Methods

  /**
   * Record an access to this memory entry
   */
  recordAccess(): void {
    this._accessCount++;
    this._lastAccessedAt = new Date();
  }

  /**
   * Update the value of this memory entry
   */
  updateValue(value: unknown): void {
    this._value = value;
    this._updatedAt = new Date();
  }

  /**
   * Update the vector embedding
   */
  updateVector(vector: Float32Array): void {
    this._vector = vector;
    this._updatedAt = new Date();
  }

  /**
   * Add or update metadata
   */
  setMetadata(key: string, value: unknown): void {
    this._metadata[key] = value;
    this._updatedAt = new Date();
  }

  /**
   * Remove metadata key
   */
  removeMetadata(key: string): void {
    delete this._metadata[key];
    this._updatedAt = new Date();
  }

  /**
   * Archive this memory entry
   */
  archive(): void {
    this._status = 'archived';
    this._updatedAt = new Date();
  }

  /**
   * Restore archived memory entry
   */
  restore(): void {
    if (this._status === 'archived') {
      this._status = 'active';
      this._updatedAt = new Date();
    }
  }

  /**
   * Mark as deleted (soft delete)
   */
  delete(): void {
    this._status = 'deleted';
    this._updatedAt = new Date();
  }

  /**
   * Check if memory has expired based on TTL
   */
  isExpired(): boolean {
    if (!this._ttl) return false;
    const expiresAt = this._createdAt.getTime() + this._ttl;
    return Date.now() > expiresAt;
  }

  /**
   * Check if memory is accessible (active and not expired)
   */
  isAccessible(): boolean {
    return this._status === 'active' && !this.isExpired();
  }

  /**
   * Calculate age in milliseconds
   */
  getAge(): number {
    return Date.now() - this._createdAt.getTime();
  }

  /**
   * Calculate time since last access in milliseconds
   */
  getTimeSinceLastAccess(): number {
    return Date.now() - this._lastAccessedAt.getTime();
  }

  /**
   * Check if memory is considered "hot" (frequently accessed)
   */
  isHot(threshold: number = 10): boolean {
    return this._accessCount >= threshold;
  }

  /**
   * Check if memory is considered "cold" (not accessed recently)
   */
  isCold(milliseconds: number = 3600000): boolean {
    return this.getTimeSinceLastAccess() > milliseconds;
  }

  /**
   * Convert to plain object for persistence
   */
  toPersistence(): Record<string, unknown> {
    return {
      id: this._id,
      namespace: this._namespace,
      key: this._key,
      value: this._value,
      type: this._type,
      vector: this._vector ? Array.from(this._vector) : undefined,
      metadata: this._metadata,
      accessCount: this._accessCount,
      lastAccessedAt: this._lastAccessedAt.toISOString(),
      createdAt: this._createdAt.toISOString(),
      updatedAt: this._updatedAt.toISOString(),
      status: this._status,
      ttl: this._ttl,
    };
  }

  /**
   * Convert to JSON-serializable object
   */
  toJSON(): Record<string, unknown> {
    return this.toPersistence();
  }
}

/**
 * Memory Domain Layer - Public Exports
 *
 * Exports all domain entities, value objects, services, and interfaces.
 *
 * @module v3/memory/domain
 */

// Entities
export {
  MemoryEntry,
  type MemoryType,
  type MemoryStatus,
  type MemoryEntryProps,
} from './entities/memory-entry.js';

// Repository Interfaces
export {
  type IMemoryRepository,
  type MemoryQueryOptions,
  type VectorSearchOptions,
  type VectorSearchResult,
  type BulkOperationResult,
  type MemoryStatistics,
} from './repositories/memory-repository.interface.js';

// Domain Services
export {
  MemoryDomainService,
  type ConsolidationStrategy,
  type ConsolidationOptions,
  type ConsolidationResult,
  type DeduplicationResult,
  type NamespaceAnalysis,
} from './services/memory-domain-service.js';

/**
 * Memory Repository Interface - Domain Layer
 *
 * Defines the contract for memory persistence.
 * Following DDD, the interface belongs to the domain layer
 * while implementations belong to infrastructure.
 *
 * @module v3/memory/domain/repositories
 */

import { MemoryEntry, MemoryType, MemoryStatus } from '../entities/memory-entry.js';

/**
 * Query options for memory retrieval
 */
export interface MemoryQueryOptions {
  namespace?: string;
  type?: MemoryType;
  status?: MemoryStatus;
  limit?: number;
  offset?: number;
  orderBy?: 'createdAt' | 'updatedAt' | 'accessCount' | 'lastAccessedAt';
  orderDirection?: 'asc' | 'desc';
}

/**
 * Vector search options
 */
export interface VectorSearchOptions {
  vector: Float32Array;
  namespace?: string;
  limit?: number;
  threshold?: number; // Minimum similarity score
  type?: MemoryType;
}

/**
 * Vector search result
 */
export interface VectorSearchResult {
  entry: MemoryEntry;
  similarity: number;
  distance: number;
}

/**
 * Bulk operation result
 */
export interface BulkOperationResult {
  success: number;
  failed: number;
  errors: Array<{ id: string; error: string }>;
}

/**
 * Memory statistics
 */
export interface MemoryStatistics {
  totalEntries: number;
  activeEntries: number;
  archivedEntries: number;
  deletedEntries: number;
  totalSize: number;
  entriesByNamespace: Record<string, number>;
  entriesByType: Record<MemoryType, number>;
  averageAccessCount: number;
  hottestEntries: string[];
  coldestEntries: string[];
}

/**
 * Memory Repository Interface
 *
 * Defines all operations for memory persistence.
 * Implementations can use SQLite, AgentDB, or hybrid backends.
 */
export interface IMemoryRepository {
  // Basic CRUD Operations
  save(entry: MemoryEntry): Promise<void>;
  findById(id: string): Promise<MemoryEntry | null>;
  findByKey(namespace: string, key: string): Promise<MemoryEntry | null>;
  findByCompositeKey(compositeKey: string): Promise<MemoryEntry | null>;
  delete(id: string): Promise<boolean>;
  exists(id: string): Promise<boolean>;

  // Bulk Operations
  saveMany(entries: MemoryEntry[]): Promise<BulkOperationResult>;
  findByIds(ids: string[]): Promise<MemoryEntry[]>;
  deleteMany(ids: string[]): Promise<BulkOperationResult>;

  // Query Operations
  findAll(options?: MemoryQueryOptions): Promise<MemoryEntry[]>;
  findByNamespace(namespace: string, options?: Omit<MemoryQueryOptions, 'namespace'>): Promise<MemoryEntry[]>;
  findByType(type: MemoryType, options?: Omit<MemoryQueryOptions, 'type'>): Promise<MemoryEntry[]>;
  findByStatus(status: MemoryStatus, options?: Omit<MemoryQueryOptions, 'status'>): Promise<MemoryEntry[]>;

  // Vector Search Operations
  searchByVector(options: VectorSearchOptions): Promise<VectorSearchResult[]>;
  findSimilar(entryId: string, limit?: number): Promise<VectorSearchResult[]>;

  // Maintenance Operations
  findExpired(): Promise<MemoryEntry[]>;
  deleteExpired(): Promise<number>;
  findCold(milliseconds: number): Promise<MemoryEntry[]>;
  archiveCold(milliseconds: number): Promise<number>;

  // Statistics
  getStatistics(): Promise<MemoryStatistics>;
  count(options?: MemoryQueryOptions): Promise<number>;

  // Namespace Operations
  listNamespaces(): Promise<string[]>;
  deleteNamespace(namespace: string): Promise<number>;
  getNamespaceSize(namespace: string): Promise<number>;

  // Lifecycle
  initialize(): Promise<void>;
  shutdown(): Promise<void>;
  clear(): Promise<void>;
}

/**
 * Memory Domain Service - Domain Layer
 *
 * Contains domain logic that doesn't naturally fit within a single entity.
 * Coordinates between multiple memory entries and enforces domain rules.
 *
 * @module v3/memory/domain/services
 */

import { MemoryEntry, MemoryType, MemoryEntryProps } from '../entities/memory-entry.js';
import { IMemoryRepository, VectorSearchResult } from '../repositories/memory-repository.interface.js';

/**
 * Memory consolidation strategy
 */
export type ConsolidationStrategy = 'merge' | 'dedupe' | 'prune' | 'summarize';

/**
 * Memory consolidation options
 */
export interface ConsolidationOptions {
  strategy: ConsolidationStrategy;
  namespace?: string;
  threshold?: number;
  maxAge?: number; // Maximum age in milliseconds
  keepHot?: boolean; // Keep frequently accessed memories
}

/**
 * Consolidation result
 */
export interface ConsolidationResult {
  processed: number;
  consolidated: number;
  removed: number;
  newEntries: MemoryEntry[];
}

/**
 * Memory deduplication result
 */
export interface DeduplicationResult {
  duplicatesFound: number;
  duplicatesRemoved: number;
  groupsProcessed: number;
}

/**
 * Memory namespace statistics
 */
export interface NamespaceAnalysis {
  namespace: string;
  totalEntries: number;
  activeEntries: number;
  totalSize: number;
  averageAccessCount: number;
  oldestEntry: Date;
  newestEntry: Date;
  typeDistribution: Record<MemoryType, number>;
}

/**
 * Memory Domain Service
 *
 * Provides domain-level operations that span multiple entities.
 * Implements business rules for memory management.
 */
export class MemoryDomainService {
  constructor(private readonly repository: IMemoryRepository) {}

  /**
   * Store a new memory with automatic type detection
   */
  async storeWithTypeDetection(
    namespace: string,
    key: string,
    value: unknown,
    vector?: Float32Array
  ): Promise<MemoryEntry> {
    const type = this.detectMemoryType(value);
    const entry = MemoryEntry.create({
      namespace,
      key,
      value,
      type,
      vector,
    });
    await this.repository.save(entry);
    return entry;
  }

  /**
   * Retrieve and record access
   */
  async retrieveWithAccessTracking(
    namespace: string,
    key: string
  ): Promise<MemoryEntry | null> {
    const entry = await this.repository.findByKey(namespace, key);
    if (entry && entry.isAccessible()) {
      entry.recordAccess();
      await this.repository.save(entry);
    }
    return entry;
  }

  /**
   * Search for similar memories and record access
   */
  async searchSimilarWithTracking(
    vector: Float32Array,
    namespace?: string,
    limit: number = 10
  ): Promise<VectorSearchResult[]> {
    const results = await this.repository.searchByVector({
      vector,
      namespace,
      limit,
    });

    // Record access for all returned entries
    await Promise.all(
      results.map(async (result) => {
        result.entry.recordAccess();
        await this.repository.save(result.entry);
      })
    );

    return results;
  }

  /**
   * Consolidate memories based on strategy
   */
  async consolidate(options: ConsolidationOptions): Promise<ConsolidationResult> {
    const entries = await this.repository.findByNamespace(
      options.namespace ?? 'default',
      { status: 'active' }
    );

    let result: ConsolidationResult = {
      processed: entries.length,
      consolidated: 0,
      removed: 0,
      newEntries: [],
    };

    switch (options.strategy) {
      case 'prune':
        result = await this.pruneOldMemories(entries, options);
        break;
      case 'dedupe':
        const dedupeResult = await this.deduplicateMemories(entries, options);
        result.removed = dedupeResult.duplicatesRemoved;
        break;
      case 'merge':
        result = await this.mergeRelatedMemories(entries, options);
        break;
      default:
        // No-op for unknown strategies
    }

    return result;
  }

  /**
   * Detect memory type based on value structure
   */
  private detectMemoryType(value: unknown): MemoryType {
    if (typeof value === 'string') {
      // Long text is likely semantic
      if (value.length > 500) return 'semantic';
      // Short instructions are procedural
      if (value.includes('->') || value.includes('then')) return 'procedural';
    }

    if (typeof value === 'object' && value !== null) {
      const obj = value as Record<string, unknown>;
      // Objects with timestamps are episodic
      if ('timestamp' in obj || 'when' in obj || 'date' in obj) return 'episodic';
      // Objects with steps are procedural
      if ('steps' in obj || 'actions' in obj) return 'procedural';
    }

    // Default to working memory for short-term storage
    return 'working';
  }

  /**
   * Prune old, rarely accessed memories
   */
  private async pruneOldMemories(
    entries: MemoryEntry[],
    options: ConsolidationOptions
  ): Promise<ConsolidationResult> {
    const maxAge = options.maxAge ?? 7 * 24 * 60 * 60 * 1000; // 7 days default
    const threshold = options.threshold ?? 5; // Minimum access count to keep
    const now = Date.now();
    const toRemove: string[] = [];

    for (const entry of entries) {
      const age = now - entry.createdAt.getTime();
      const isOld = age > maxAge;
      const isRarelyAccessed = entry.accessCount < threshold;

      // Keep hot memories if requested
      if (options.keepHot && entry.isHot()) continue;

      if (isOld && isRarelyAccessed) {
        entry.archive();
        toRemove.push(entry.id);
      }
    }

    if (toRemove.length > 0) {
      await this.repository.deleteMany(toRemove);
    }

    return {
      processed: entries.length,
      consolidated: 0,
      removed: toRemove.length,
      newEntries: [],
    };
  }

  /**
   * Find and remove duplicate memories
   */
  private async deduplicateMemories(
    entries: MemoryEntry[],
    options: ConsolidationOptions
  ): Promise<DeduplicationResult> {
    const threshold = options.threshold ?? 0.95; // Similarity threshold
    const duplicates: string[] = [];
    const processed = new Set<string>();

    for (let i = 0; i < entries.length; i++) {
      if (processed.has(entries[i].id)) continue;

      const entry = entries[i];
      if (!entry.vector) continue;

      // Find similar entries
      const similar = await this.repository.searchByVector({
        vector: entry.vector,
        namespace: entry.namespace,
        limit: 10,
        threshold,
      });

      // Mark duplicates (keep the one with highest access count)
      const group = similar
        .filter((s) => s.entry.id !== entry.id && s.similarity >= threshold)
        .sort((a, b) => b.entry.accessCount - a.entry.accessCount);

      for (const dup of group.slice(1)) {
        duplicates.push(dup.entry.id);
        processed.add(dup.entry.id);
      }

      processed.add(entry.id);
    }

    if (duplicates.length > 0) {
      await this.repository.deleteMany(duplicates);
    }

    return {
      duplicatesFound: duplicates.length,
      duplicatesRemoved: duplicates.length,
      groupsProcessed: processed.size,
    };
  }

  /**
   * Merge related memories into consolidated entries
   */
  private async mergeRelatedMemories(
    entries: MemoryEntry[],
    options: ConsolidationOptions
  ): Promise<ConsolidationResult> {
    const threshold = options.threshold ?? 0.8;
    const newEntries: MemoryEntry[] = [];
    const toRemove: string[] = [];
    const processed = new Set<string>();

    for (const entry of entries) {
      if (processed.has(entry.id)) continue;
      if (!entry.vector) {
        processed.add(entry.id);
        continue;
      }

      // Find related entries
      const related = await this.repository.searchByVector({
        vector: entry.vector,
        namespace: entry.namespace,
        limit: 5,
        threshold,
      });

      if (related.length > 1) {
        // Merge related entries
        const merged = this.mergeEntries(related.map((r) => r.entry));
        newEntries.push(merged);

        for (const r of related) {
          toRemove.push(r.entry.id);
          processed.add(r.entry.id);
        }
      } else {
        processed.add(entry.id);
      }
    }

    // Remove old entries and save merged ones
    if (toRemove.length > 0) {
      await this.repository.deleteMany(toRemove);
    }
    if (newEntries.length > 0) {
      await this.repository.saveMany(newEntries);
    }

    return {
      processed: entries.length,
      consolidated: newEntries.length,
      removed: toRemove.length,
      newEntries,
    };
  }

  /**
   * Merge multiple entries into one
   */
  private mergeEntries(entries: MemoryEntry[]): MemoryEntry {
    // Sort by access count to prioritize most accessed
    const sorted = [...entries].sort((a, b) => b.accessCount - a.accessCount);
    const primary = sorted[0];

    // Combine metadata
    const combinedMetadata: Record<string, unknown> = {};
    for (const entry of entries) {
      Object.assign(combinedMetadata, entry.metadata);
    }
    combinedMetadata.mergedFrom = entries.map((e) => e.id);
    combinedMetadata.mergedAt = new Date().toISOString();

    // Create merged entry
    return MemoryEntry.create({
      namespace: primary.namespace,
      key: `merged_${Date.now()}`,
      value: {
        primary: primary.value,
        related: sorted.slice(1).map((e) => e.value),
      },
      type: primary.type,
      vector: primary.vector,
      metadata: combinedMetadata,
      accessCount: entries.reduce((sum, e) => sum + e.accessCount, 0),
    });
  }

  /**
   * Analyze a namespace
   */
  async analyzeNamespace(namespace: string): Promise<NamespaceAnalysis> {
    const entries = await this.repository.findByNamespace(namespace);
    const active = entries.filter((e) => e.status === 'active');

    const typeDistribution: Record<MemoryType, number> = {
      semantic: 0,
      episodic: 0,
      procedural: 0,
      working: 0,
    };

    let totalAccessCount = 0;
    let totalSize = 0;
    let oldestDate = new Date();
    let newestDate = new Date(0);

    for (const entry of entries) {
      typeDistribution[entry.type]++;
      totalAccessCount += entry.accessCount;
      totalSize += JSON.stringify(entry.value).length;

      if (entry.createdAt < oldestDate) oldestDate = entry.createdAt;
      if (entry.createdAt > newestDate) newestDate = entry.createdAt;
    }

    return {
      namespace,
      totalEntries: entries.length,
      activeEntries: active.length,
      totalSize,
      averageAccessCount: entries.length > 0 ? totalAccessCount / entries.length : 0,
      oldestEntry: oldestDate,
      newestEntry: newestDate,
      typeDistribution,
    };
  }
}

/**
 * Tests for the regex entity tagger (ADR-147 P2, ruvnet/ruflo#2317).
 *
 * Goal of the tagger: a conservative third signal for hybridSearch.
 * False negatives are fine (dense + sparse cover the rest); false
 * positives would dilute the RRF score by adding noise rows. These
 * tests pin the conservatism — generic prose returns nothing, and
 * concrete structured tokens (email, URL, path, quote, proper-noun
 * bigram) round-trip cleanly.
 */

import { describe, it, expect } from 'vitest';
import { extractEntities } from './entity-tagger.js';

describe('extractEntities', () => {
  it('returns empty for empty / nullish input', () => {
    expect(extractEntities('')).toEqual([]);
    expect(extractEntities(undefined as unknown as string)).toEqual([]);
  });

  it('returns empty for plain prose with no entities', () => {
    expect(extractEntities('how do i debug this very slow query')).toEqual([]);
  });

  it('extracts email addresses', () => {
    const got = extractEntities('contact alice@example.com or bob+ops@team.io');
    expect(got).toContain('alice@example.com');
    expect(got).toContain('bob+ops@team.io');
  });

  it('extracts URLs', () => {
    const got = extractEntities('see https://example.com/path?x=1 and http://internal');
    expect(got).toContain('https://example.com/path?x=1');
    expect(got).toContain('http://internal');
  });

  it('extracts POSIX file paths', () => {
    const got = extractEntities('open src/foo/bar.ts and ./scripts/build.mjs');
    expect(got).toContain('src/foo/bar.ts');
    expect(got).toContain('./scripts/build.mjs');
  });

  it('extracts Windows file paths', () => {
    const got = extractEntities(String.raw`look at C:\Users\ruv\repo\file.ts`);
    expect(got.some((e) => e.includes(String.raw`C:\Users\ruv\repo\file.ts`))).toBe(true);
  });

  it('does not pick up "and/or" style false positives', () => {
    expect(extractEntities('proceed and/or stop')).not.toContain('and/or');
  });

  it('extracts quoted phrases (both quote styles)', () => {
    const got = extractEntities(`open "config alpha" then 'session beta'`);
    expect(got).toContain('config alpha');
    expect(got).toContain('session beta');
  });

  it('extracts proper-noun 2-grams', () => {
    const got = extractEntities('hand off to Alice Smith and notify Acme Corp');
    expect(got).toContain('Alice Smith');
    expect(got).toContain('Acme Corp');
  });

  it('does not extract single capitalized words (too noisy)', () => {
    expect(extractEntities('Reset the database now')).toEqual([]);
  });

  it('deduplicates repeats while preserving first-seen order', () => {
    const got = extractEntities(
      'Alice Smith filed Alice Smith again at alice@x.io. Alice Smith.'
    );
    // 'Alice Smith' should appear exactly once even though the source
    // mentions it three times.
    expect(got.filter((e) => e === 'Alice Smith').length).toBe(1);
    // Both entity types are present.
    expect(got).toContain('Alice Smith');
    expect(got).toContain('alice@x.io');
  });

  it('drops trimmed-to-shorter-than-2 fragments', () => {
    // Quoted single-char phrase ("a") should be filtered by the min-length guard.
    expect(extractEntities(`prefer "a" over "b"`)).toEqual([]);
  });
});

/**
 * Entity tagger — regex-based proper-noun / structured-token extractor.
 *
 * Used by the `hybridSearch` controller as a third RRF arm alongside the
 * dense (vector) and sparse (BM25/FTS5) signals (ADR-147, ruvnet/ruflo#2317).
 *
 * Entity matching is a distinct signal because BM25 weights documents by
 * overall token frequency; a per-entity exact match avoids downweighting
 * for tokens that happen to be common but mention an entity by name.
 * Example: querying "Alice OAuth tokens" — BM25 may rank a doc about
 * generic OAuth above one mentioning Alice specifically; entity arm
 * surfaces the Alice doc independently.
 *
 * P1 is regex-only — no NLP model dependency. Tags:
 *   - Emails: foo@bar.com
 *   - URLs: http(s)://...
 *   - File paths: ./foo/bar.ts, C:\foo\bar.ts, src/foo
 *   - Quoted phrases: "..." or '...'
 *   - Proper-noun 2-grams: "Alice Smith", "Acme Corp"
 *
 * Deliberately conservative — false negatives are fine (the dense + sparse
 * arms still cover the query); false positives would dilute the RRF score
 * by adding noise rows. A future P2 can swap this for a CRF/spaCy tagger
 * behind the same `extractEntities(text)` contract.
 */

/**
 * Extract entity-like tokens from free text. Returns a unique list,
 * trimmed and deduplicated, in extraction order.
 */
export function extractEntities(text: string): string[] {
  if (!text) return [];

  const seen = new Set<string>();
  const ordered: string[] = [];

  const add = (raw: string | undefined): void => {
    if (!raw) return;
    const trimmed = raw.trim();
    if (trimmed.length < 2) return;
    if (seen.has(trimmed)) return;
    seen.add(trimmed);
    ordered.push(trimmed);
  };

  // Emails — anchored on @ so we don't pick up arbitrary handles.
  for (const m of text.matchAll(/[\w.+-]+@[\w-]+(?:\.[\w-]+)+/g)) add(m[0]);

  // URLs — http(s) only. Stop at whitespace and common boundary chars.
  for (const m of text.matchAll(/https?:\/\/[^\s)>"'`]+/g)) add(m[0]);

  // File paths — two complementary patterns:
  //
  //   (a) Path with a file extension. Catches `src/foo/bar.ts`, the most
  //       common case. The extension (`.\w{1,5}`) is what separates a
  //       real path from prose like `and/or`.
  //
  //   (b) Path with an explicit leading sentinel: `./...`, `../...`, `/...`,
  //       or `C:\...`. Catches extensionless paths the user clearly meant
  //       (like `./scripts/build` or `/etc/hosts`).
  for (const m of text.matchAll(
    /(?:[A-Za-z]:[\\/])?(?:[\w.-]+[\\/])+[\w-]+\.\w{1,5}\b/g,
  )) {
    add(m[0]);
  }
  for (const m of text.matchAll(/(?:\.{1,2}|[A-Za-z]:)[\\/][\w./\\-]+/g)) add(m[0]);

  // Quoted phrases. Inner content only, both quote styles. The
  // (?<!\w)/(?!\w) guards keep us from pairing a *closing* quote of one
  // phrase with the *opening* quote of the next — e.g. `"a" over "b"`
  // should NOT capture ` over ` from positions 9–16.
  for (const m of text.matchAll(/(?<!\w)"([^"]{2,})"(?!\w)/g)) add(m[1]);
  for (const m of text.matchAll(/(?<!\w)'([^']{2,})'(?!\w)/g)) add(m[1]);

  // Proper-noun 2+ grams — capitalized words with capitalized neighbours.
  // Skip single capitals (too noisy: sentence-initial common nouns).
  for (const m of text.matchAll(/\b[A-Z][a-z]+(?:\s+[A-Z][a-z]+)+\b/g)) add(m[0]);

  return ordered;
}

/**
 * Phase 5 — FTS5 keyword index (ADR-125)
 *
 * Verifies the FTS5 wiring on the two SQL backends:
 * - SqlJsBackend  (sql.js — WASM, ships FTS5 since 1.10)
 * - SQLiteBackend (better-sqlite3 — bundles FTS5 since 11.x)
 *
 * The SQLiteBackend test is conditional: better-sqlite3 is an optional
 * dependency. If it isn't installable in the current env, that test is
 * skipped.
 */

import { describe, it, expect } from 'vitest';
import { existsSync } from 'node:fs';
import { createRequire } from 'node:module';
import { SqlJsBackend } from './sqljs-backend.js';
import { createDefaultEntry } from './types.js';

const require = createRequire(import.meta.url);

/**
 * Locate the local sql-wasm.wasm so vitest doesn't try to fetch it over HTTP.
 * Returns null if sql.js isn't installed in this env (treated as a skip
 * signal by the suite).
 */
function locateSqlWasm(): string | null {
  try {
    const sqljsPkg = require.resolve('sql.js/package.json');
    const wasmPath = sqljsPkg.replace(/package\.json$/, 'dist/sql-wasm.wasm');
    return existsSync(wasmPath) ? wasmPath : null;
  } catch {
    return null;
  }
}

const WASM_PATH = locateSqlWasm();

async function newSqlJs() {
  if (!WASM_PATH) throw new Error('sql.js/dist/sql-wasm.wasm not found');
  const backend = new SqlJsBackend({ databasePath: ':memory:', wasmPath: WASM_PATH });
  await backend.initialize();
  return backend;
}

describe('Phase 5 — SqlJsBackend FTS5', () => {
  it('searchKeyword returns matching entries for an FTS phrase', async () => {
    const backend = await newSqlJs();

    const phrases = [
      'authentication patterns for OAuth flow',
      'database migrations and schema changes',
      'rate limiting and throttling middleware',
      'caching strategies for distributed systems',
      'jwt token validation security',
    ];
    for (let i = 0; i < 20; i++) {
      const phrase = phrases[i % phrases.length];
      const entry = createDefaultEntry({ key: `k-${i}`, content: `${phrase} ${i}` });
      await backend.store(entry);
    }

    const results = await (backend as any).searchKeyword('authentication patterns', 10);
    expect(results.length).toBeGreaterThan(0);
    for (const r of results) {
      const c = r.entry.content.toLowerCase();
      // At least one of the two query tokens should appear
      expect(c.includes('authentication') || c.includes('patterns')).toBe(true);
    }

    await backend.shutdown();
  });

  it('searchKeyword does not return a deleted entry', async () => {
    const backend = await newSqlJs();
    const entry = createDefaultEntry({ key: 'doomed', content: 'unique-marker-phrase' });
    await backend.store(entry);
    let results = await (backend as any).searchKeyword('unique-marker-phrase', 5);
    expect(results.length).toBe(1);

    await backend.delete(entry.id);
    results = await (backend as any).searchKeyword('unique-marker-phrase', 5);
    expect(results.length).toBe(0);

    await backend.shutdown();
  });

  it('searchKeyword reflects content updates', async () => {
    const backend = await newSqlJs();
    const entry = createDefaultEntry({ key: 'updatable', content: 'original phrase about apples' });
    await backend.store(entry);

    let results = await (backend as any).searchKeyword('apples', 5);
    expect(results.length).toBe(1);

    await backend.update(entry.id, { content: 'rewritten phrase about bananas' });
    results = await (backend as any).searchKeyword('apples', 5);
    expect(results.length).toBe(0);
    results = await (backend as any).searchKeyword('bananas', 5);
    expect(results.length).toBe(1);

    await backend.shutdown();
  });

  it('searchKeyword returns [] for an empty query', async () => {
    const backend = await newSqlJs();
    const results = await (backend as any).searchKeyword('   ', 5);
    expect(results).toEqual([]);
    await backend.shutdown();
  });
});

