      const neighbors = graph.getNeighbors('a', 2);
      expect(neighbors.size).toBe(2);
      expect(neighbors.has('b')).toBe(true);
      expect(neighbors.has('c')).toBe(true);
    });

    it('should return all reachable nodes at depth 3', () => {
      const neighbors = graph.getNeighbors('a', 3);
      expect(neighbors.size).toBe(3);
      expect(neighbors.has('b')).toBe(true);
      expect(neighbors.has('c')).toBe(true);
      expect(neighbors.has('d')).toBe(true);
    });

    it('should handle node with no neighbors', () => {
      const neighbors = graph.getNeighbors('d', 1);
      expect(neighbors.size).toBe(0);
    });

    it('should not include the start node in results', () => {
      const neighbors = graph.getNeighbors('a', 10);
      expect(neighbors.has('a')).toBe(false);
    });

    it('should default to depth 1', () => {
      const neighbors = graph.getNeighbors('a');
      expect(neighbors.size).toBe(1);
      expect(neighbors.has('b')).toBe(true);
    });
  });

  // ===== addSimilarityEdges =====

  describe('addSimilarityEdges', () => {
    it('should add edges for similar entries above threshold', async () => {
      const embedding = new Float32Array([1, 0, 0]);
      const entryA = { ...makeEntry('a'), embedding };
      const entryB = makeEntry('b');
      graph.addNode(entryA);
      graph.addNode(entryB);

      const searchResults: SearchResult[] = [
        { entry: entryB, score: 0.9, distance: 0.1 },
      ];
      const backend = createMockBackend([entryA, entryB]);
      (backend.search as ReturnType<typeof vi.fn>).mockResolvedValue(searchResults);

      const added = await graph.addSimilarityEdges(backend, 'a');
      expect(added).toBe(1);
      expect(graph.getStats().edgeCount).toBe(1);
    });

    it('should return 0 if entry has no embedding', async () => {
      const entry = makeEntry('a');
      graph.addNode(entry);
      const backend = createMockBackend([entry]);

      const added = await graph.addSimilarityEdges(backend, 'a');
      expect(added).toBe(0);
    });

    it('should return 0 if entry does not exist', async () => {
      const backend = createMockBackend([]);
      const added = await graph.addSimilarityEdges(backend, 'missing');
      expect(added).toBe(0);
    });

    it('should skip self-references in search results', async () => {
      const embedding = new Float32Array([1, 0, 0]);
      const entryA = { ...makeEntry('a'), embedding };
      graph.addNode(entryA);

      const searchResults: SearchResult[] = [
        { entry: entryA, score: 1.0, distance: 0.0 },
      ];
      const backend = createMockBackend([entryA]);
      (backend.search as ReturnType<typeof vi.fn>).mockResolvedValue(searchResults);

      const added = await graph.addSimilarityEdges(backend, 'a');
      expect(added).toBe(0);
    });
  });

  // ===== getStats =====

  describe('getStats', () => {
    it('should return correct initial stats', () => {
      const stats = graph.getStats();
      expect(stats.nodeCount).toBe(0);
      expect(stats.edgeCount).toBe(0);
      expect(stats.avgDegree).toBe(0);
      expect(stats.communityCount).toBe(0);
      expect(stats.pageRankComputed).toBe(false);
      expect(stats.maxPageRank).toBe(0);
      expect(stats.minPageRank).toBe(0);
    });

    it('should reflect graph state after adding nodes and edges', () => {
      graph.addNode(makeEntry('a'));
      graph.addNode(makeEntry('b'));
      graph.addNode(makeEntry('c'));
      graph.addEdge('a', 'b', 'reference');
      graph.addEdge('a', 'c', 'reference');

      const stats = graph.getStats();
      expect(stats.nodeCount).toBe(3);
      expect(stats.edgeCount).toBe(2);
      expect(stats.avgDegree).toBeCloseTo(2 / 3, 5);
    });

    it('should report pageRank min/max after computation', () => {
      graph.addNode(makeEntry('a'));
      graph.addNode(makeEntry('b'));
      graph.addEdge('a', 'b', 'reference');
      graph.computePageRank();

      const stats = graph.getStats();
      expect(stats.pageRankComputed).toBe(true);
      expect(stats.maxPageRank).toBeGreaterThan(0);
      expect(stats.minPageRank).toBeGreaterThan(0);
      expect(stats.maxPageRank).toBeGreaterThanOrEqual(stats.minPageRank);
    });

    it('should count communities after detection', () => {
      graph.addNode(makeEntry('a'));
      graph.addNode(makeEntry('b'));
      graph.detectCommunities();

      const stats = graph.getStats();
      expect(stats.communityCount).toBe(2);
    });
  });
});

/**
 * Knowledge Graph Module for @claude-flow/memory
 *
 * Builds a graph from MemoryEntry.references, computes PageRank,
 * detects communities via label propagation, and provides
 * graph-aware ranking for search results.
 *
 * Pure TypeScript - no external graph libraries.
 * @module v3/memory/memory-graph
 */
import { EventEmitter } from 'node:events';
import type { IMemoryBackend, MemoryEntry, SearchResult } from './types.js';

// ===== Types =====

export type EdgeType = 'reference' | 'similar' | 'temporal' | 'co-accessed' | 'causal';

export interface MemoryGraphConfig {
  similarityThreshold?: number;   // Auto-edge threshold (default: 0.8)
  pageRankDamping?: number;       // Damping factor (default: 0.85)
  pageRankIterations?: number;    // Max iterations (default: 50)
  pageRankConvergence?: number;   // Convergence threshold (default: 1e-6)
  maxNodes?: number;              // Cap graph size (default: 5000)
  enableAutoEdges?: boolean;      // Auto-create edges from similarity (default: true)
  communityAlgorithm?: 'louvain' | 'label-propagation';  // default: label-propagation
}

export interface GraphNode {
  id: string;
  category: string;
  confidence: number;
  accessCount: number;
  createdAt: number;
}

export interface GraphEdge {
  targetId: string;
  type: EdgeType;
  weight: number;
}

export interface RankedResult {
  entry: MemoryEntry;
  score: number;
  pageRank: number;
  combinedScore: number;
  community?: string;
}

export interface GraphStats {
  nodeCount: number;
  edgeCount: number;
  avgDegree: number;
  communityCount: number;
  pageRankComputed: boolean;
  maxPageRank: number;
  minPageRank: number;
}

const DEFAULT_CONFIG: Required<MemoryGraphConfig> = {
  similarityThreshold: 0.8,
  pageRankDamping: 0.85,
  pageRankIterations: 50,
  pageRankConvergence: 1e-6,
  maxNodes: 5000,
  enableAutoEdges: true,
  communityAlgorithm: 'label-propagation',
};

/**
 * Knowledge graph built from memory entry references.
 * Supports PageRank, community detection (label propagation),
 * and graph-aware result ranking blending vector similarity with structural importance.
 */
export class MemoryGraph extends EventEmitter {
  private nodes: Map<string, GraphNode> = new Map();
  private edges: Map<string, GraphEdge[]> = new Map();
  private reverseEdges: Map<string, Set<string>> = new Map();
  private pageRanks: Map<string, number> = new Map();
  private communities: Map<string, string> = new Map();
  private config: Required<MemoryGraphConfig>;
  private dirty: boolean = true;

  constructor(config?: MemoryGraphConfig) {
    super();
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /** Build graph from all entries in a backend. Creates nodes and reference edges. */
  async buildFromBackend(backend: IMemoryBackend, namespace?: string): Promise<void> {
    const entries = await backend.query({
      type: 'hybrid',
      namespace,
      limit: this.config.maxNodes,
    });
    for (const entry of entries) {
      this.addNode(entry);
    }
    for (const entry of entries) {
      for (const refId of entry.references) {
        this.addEdge(entry.id, refId, 'reference');
      }
    }
    this.dirty = true;
    this.emit('graph:built', { nodeCount: this.nodes.size });
  }

  /** Add a node from a MemoryEntry. Skips silently at maxNodes capacity. */
  addNode(entry: MemoryEntry): void {
    if (this.nodes.size >= this.config.maxNodes && !this.nodes.has(entry.id)) {
      return;
    }
    this.nodes.set(entry.id, {
      id: entry.id,
      category: (entry.metadata?.category as string) || 'general',
      confidence: (entry.metadata?.confidence as number) || 0.5,
      accessCount: entry.accessCount,
      createdAt: entry.createdAt,
    });
    if (!this.edges.has(entry.id)) this.edges.set(entry.id, []);
    if (!this.reverseEdges.has(entry.id)) this.reverseEdges.set(entry.id, new Set());
    this.dirty = true;
  }

  /** Add a directed edge. Skips if either node missing. Updates weight to max if exists. */
  addEdge(sourceId: string, targetId: string, type: EdgeType, weight: number = 1.0): void {
    if (!this.nodes.has(sourceId) || !this.nodes.has(targetId)) return;

    const edgeList = this.edges.get(sourceId) || [];
    if (!this.edges.has(sourceId)) this.edges.set(sourceId, edgeList);

    const existing = edgeList.find((e) => e.targetId === targetId);
    if (existing) {
      existing.weight = Math.max(existing.weight, weight);
    } else {
      edgeList.push({ targetId, type, weight });
    }

    if (!this.reverseEdges.has(targetId)) this.reverseEdges.set(targetId, new Set());
    this.reverseEdges.get(targetId)!.add(sourceId);
    this.dirty = true;
  }

  /** Remove a node and all associated edges (both directions). */
  removeNode(id: string): void {
    if (!this.nodes.has(id)) return;

    // Remove outgoing edges and their reverse entries
    for (const edge of this.edges.get(id) || []) {
      this.reverseEdges.get(edge.targetId)?.delete(id);
    }
    this.edges.delete(id);

    // Remove incoming edges pointing to this node
    const incoming = this.reverseEdges.get(id);
    if (incoming) {
      for (const sourceId of incoming) {
        const srcEdges = this.edges.get(sourceId);
        if (srcEdges) this.edges.set(sourceId, srcEdges.filter((e) => e.targetId !== id));
      }
    }
    this.reverseEdges.delete(id);
    this.nodes.delete(id);
    this.pageRanks.delete(id);
    this.communities.delete(id);
    this.dirty = true;
  }

  /** Add similarity edges by searching backend. Returns count of edges added. */
  async addSimilarityEdges(backend: IMemoryBackend, entryId: string): Promise<number> {
    const entry = await backend.get(entryId);
    if (!entry || !entry.embedding) return 0;

    const results = await backend.search(entry.embedding, {
      k: 20,
      threshold: this.config.similarityThreshold,
    });

    let added = 0;
    for (const result of results) {
      if (result.entry.id === entryId) continue;
      if (result.score >= this.config.similarityThreshold) {
        const hadEdge = this.hasEdge(entryId, result.entry.id);
        this.addEdge(entryId, result.entry.id, 'similar', result.score);
        if (!hadEdge) added++;
      }
    }
    return added;
  }

  /**
   * Compute PageRank via power iteration with dangling node redistribution.
   * Returns map of node ID to PageRank score.
   */
  computePageRank(): Map<string, number> {
    const N = this.nodes.size;
    if (N === 0) {
      this.dirty = false;
      this.emit('pagerank:computed', { iterations: 0 });
      return new Map();
    }

    const d = this.config.pageRankDamping;
    for (const nodeId of this.nodes.keys()) {
      this.pageRanks.set(nodeId, 1 / N);
    }

    // Identify dangling nodes (no outgoing edges)
    const danglingNodes: string[] = [];
    for (const nodeId of this.nodes.keys()) {
      const out = this.edges.get(nodeId);
      if (!out || out.length === 0) danglingNodes.push(nodeId);
    }

    let iterations = 0;
    for (let iter = 0; iter < this.config.pageRankIterations; iter++) {
      let maxDelta = 0;
      const newRanks = new Map<string, number>();

      let danglingSum = 0;
      for (const nodeId of danglingNodes) {
        danglingSum += this.pageRanks.get(nodeId) || 0;
      }

      for (const nodeId of this.nodes.keys()) {
        let sum = 0;
        const incoming = this.reverseEdges.get(nodeId);
        if (incoming) {
          for (const sourceId of incoming) {
            const outDegree = this.edges.get(sourceId)?.length || 1;
            sum += (this.pageRanks.get(sourceId) || 0) / outDegree;
          }
        }
        const newRank = (1 - d) / N + d * (sum + danglingSum / N);
        newRanks.set(nodeId, newRank);
        maxDelta = Math.max(maxDelta, Math.abs(newRank - (this.pageRanks.get(nodeId) || 0)));
      }

      this.pageRanks = newRanks;
      iterations = iter + 1;
      if (maxDelta < this.config.pageRankConvergence) break;
    }

    this.dirty = false;
    this.emit('pagerank:computed', { iterations });
    return new Map(this.pageRanks);
  }

  /** Detect communities using label propagation. Returns map of nodeId to communityId. */
  detectCommunities(): Map<string, string> {
    const labels = new Map<string, string>();
    for (const nodeId of this.nodes.keys()) labels.set(nodeId, nodeId);

    for (let iter = 0; iter < 20; iter++) {
      let changed = false;
      const nodeIds = this.shuffleArray([...this.nodes.keys()]);

      for (const nodeId of nodeIds) {
        const labelCounts = new Map<string, number>();

        for (const edge of this.edges.get(nodeId) || []) {
          const lbl = labels.get(edge.targetId);
          if (lbl !== undefined) labelCounts.set(lbl, (labelCounts.get(lbl) || 0) + edge.weight);
        }
        const incoming = this.reverseEdges.get(nodeId);
        if (incoming) {
          for (const sourceId of incoming) {
            const lbl = labels.get(sourceId);
            if (lbl !== undefined) labelCounts.set(lbl, (labelCounts.get(lbl) || 0) + 1);
          }
        }

        if (labelCounts.size > 0) {
          let maxLabel = labels.get(nodeId)!;
          let maxCount = 0;
          for (const [label, count] of labelCounts) {
            if (count > maxCount) { maxCount = count; maxLabel = label; }
          }
          if (maxLabel !== labels.get(nodeId)) {
            labels.set(nodeId, maxLabel);
            changed = true;
          }
        }
      }
      if (!changed) break;
    }

    this.communities = labels;
    this.emit('communities:detected', { communityCount: new Set(labels.values()).size });
    return new Map(this.communities);
  }

  /**
   * Rank search results blending vector similarity and PageRank.
   * @param alpha - Weight for vector score (default 0.7). PageRank weight is (1 - alpha).
   */
  rankWithGraph(searchResults: SearchResult[], alpha: number = 0.7): RankedResult[] {
    if (this.dirty) this.computePageRank();
    const N = this.nodes.size || 1;

    return searchResults
      .map((result) => {
        const pageRank = this.pageRanks.get(result.entry.id) || 0;
        return {
          entry: result.entry,
          score: result.score,
          pageRank,
          combinedScore: alpha * result.score + (1 - alpha) * (pageRank * N),
          community: this.communities.get(result.entry.id),
        };
      })
      .sort((a, b) => b.combinedScore - a.combinedScore);
  }

  /** Get top N nodes by PageRank score. */
  getTopNodes(n: number): Array<{ id: string; pageRank: number; community: string }> {
    if (this.dirty) this.computePageRank();
    return [...this.pageRanks.entries()]
      .sort((a, b) => b[1] - a[1])
      .slice(0, n)
      .map(([id, pageRank]) => ({
        id,
        pageRank,
        community: this.communities.get(id) || id,
      }));
  }

  /** BFS neighbors from a node up to given depth. Excludes the start node. */
  getNeighbors(id: string, depth: number = 1): Set<string> {
    const visited = new Set<string>();
    let frontier = new Set<string>([id]);

    for (let d = 0; d < depth; d++) {
      const nextFrontier = new Set<string>();
      for (const nodeId of frontier) {
        for (const edge of this.edges.get(nodeId) || []) {
          if (!visited.has(edge.targetId) && edge.targetId !== id) {
            visited.add(edge.targetId);
            nextFrontier.add(edge.targetId);
          }
        }
      }
      frontier = nextFrontier;
      if (frontier.size === 0) break;
    }
    return visited;
  }

  /** Get statistics about the current graph state. */
  getStats(): GraphStats {
    let totalEdges = 0;
    for (const edgeList of this.edges.values()) totalEdges += edgeList.length;

    const nodeCount = this.nodes.size;
    let maxPageRank = 0;
    let minPageRank = Infinity;
    if (this.pageRanks.size > 0) {
      for (const rank of this.pageRanks.values()) {
        if (rank > maxPageRank) maxPageRank = rank;
        if (rank < minPageRank) minPageRank = rank;
      }
    } else {
      minPageRank = 0;
    }

    return {
      nodeCount,
      edgeCount: totalEdges,
      avgDegree: nodeCount > 0 ? totalEdges / nodeCount : 0,
      communityCount: new Set(this.communities.values()).size,
      pageRankComputed: !this.dirty,
      maxPageRank,
      minPageRank,
    };
  }

  // ===== Internal Helpers =====

  private hasEdge(sourceId: string, targetId: string): boolean {
    const edgeList = this.edges.get(sourceId);
    return edgeList ? edgeList.some((e) => e.targetId === targetId) : false;
  }

  private shuffleArray<T>(arr: T[]): T[] {
    const shuffled = [...arr];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  }
}

/**
 * V3 Memory Migration Utility
 *
 * Migrates data from legacy memory systems (SQLite, Markdown, JSON, etc.)
 * to the unified AgentDB-backed memory system with HNSW indexing.
 *
 * @module v3/memory/migration
 */

import { EventEmitter } from 'node:events';
import { promises as fs } from 'node:fs';
import * as path from 'node:path';
import {
  MigrationConfig,
  MigrationProgress,
  MigrationResult,
  MigrationError,
  MigrationSource,
  MemoryEntry,
  MemoryType,
  MemoryEntryInput,
  EmbeddingGenerator,
  createDefaultEntry,
} from './types.js';
import { AgentDBAdapter } from './agentdb-adapter.js';

/**
 * Default migration configuration
 */
const DEFAULT_MIGRATION_CONFIG: Partial<MigrationConfig> = {
  batchSize: 100,
  generateEmbeddings: true,
  validateData: true,
  continueOnError: true,
};

/**
 * Legacy entry format (common structure)
 */
interface LegacyEntry {
  id?: string;
  key: string;
  value: unknown;
  namespace?: string;
  tags?: string[];
  metadata?: Record<string, unknown>;
  timestamp?: number;
  createdAt?: string | number;
  updatedAt?: string | number;
  created_at?: string | number;
  updated_at?: string | number;
}

/**
 * Memory Migration Manager
 *
 * Handles migration from:
 * - SQLite backends (.db files)
 * - Markdown backends (.md files)
 * - JSON memory stores (.json files)
 * - MemoryManager instances
 * - SwarmMemory instances
 * - DistributedMemory instances
 */
export class MemoryMigrator extends EventEmitter {
  private config: MigrationConfig;
  private target: AgentDBAdapter;
  private embeddingGenerator?: EmbeddingGenerator;
  private progress: MigrationProgress;

  constructor(
    target: AgentDBAdapter,
    config: Partial<MigrationConfig>,
    embeddingGenerator?: EmbeddingGenerator
  ) {
    super();
    this.target = target;
    this.config = { ...DEFAULT_MIGRATION_CONFIG, ...config } as MigrationConfig;
    this.embeddingGenerator = embeddingGenerator;
    this.progress = this.initializeProgress();
  }

  /**
   * Run the migration
   */
  async migrate(): Promise<MigrationResult> {
    const startTime = Date.now();
    this.progress = this.initializeProgress();

    this.emit('migration:started', { source: this.config.source });

    try {
      // Load entries from source
      const entries = await this.loadFromSource();
      this.progress.total = entries.length;
      this.progress.totalBatches = Math.ceil(entries.length / this.config.batchSize);

      this.emit('migration:progress', { ...this.progress });

      // Process in batches
      for (let i = 0; i < entries.length; i += this.config.batchSize) {
        const batch = entries.slice(i, i + this.config.batchSize);
        this.progress.currentBatch = Math.floor(i / this.config.batchSize) + 1;

        await this.processBatch(batch);

        this.progress.percentage = Math.round(
          (this.progress.migrated / this.progress.total) * 100
        );
        this.progress.estimatedTimeRemaining = this.estimateTimeRemaining(
          startTime,
          this.progress.migrated,
          this.progress.total
        );

        this.emit('migration:progress', { ...this.progress });
      }

      const duration = Date.now() - startTime;

      const result: MigrationResult = {
        success: this.progress.failed === 0 || this.config.continueOnError,
        progress: { ...this.progress },
        duration,
        summary: this.generateSummary(),
      };

      this.emit('migration:completed', result);
      return result;
    } catch (error) {
      const duration = Date.now() - startTime;

      const result: MigrationResult = {
        success: false,
        progress: { ...this.progress },
        duration,
        summary: `Migration failed: ${(error as Error).message}`,
      };

      this.emit('migration:failed', { error, result });
      return result;
    }
  }

  /**
   * Get current migration progress
   */
  getProgress(): MigrationProgress {
    return { ...this.progress };
  }

  // ===== Source Loaders =====

  private async loadFromSource(): Promise<LegacyEntry[]> {
    switch (this.config.source) {
      case 'sqlite':
        return this.loadFromSQLite();
      case 'markdown':
        return this.loadFromMarkdown();
      case 'json':
        return this.loadFromJSON();
      case 'memory-manager':
        return this.loadFromMemoryManager();
      case 'swarm-memory':
        return this.loadFromSwarmMemory();
      case 'distributed-memory':
        return this.loadFromDistributedMemory();
      default:
        throw new Error(`Unknown migration source: ${this.config.source}`);
    }
  }

  private async loadFromSQLite(): Promise<LegacyEntry[]> {
    const entries: LegacyEntry[] = [];
    const dbPath = this.config.sourcePath;

    try {
      // Dynamic import for better-sqlite3 or similar
      // In production, would use actual SQLite library
      const fileContent = await fs.readFile(dbPath);

      // Parse SQLite format (simplified - actual implementation would use SQLite library)
      // For now, we'll try to read it as a JSON export format
      if (dbPath.endsWith('.json')) {
        const data = JSON.parse(fileContent.toString());
        if (Array.isArray(data)) {
          return data;
        } else if (data.entries) {
          return data.entries;
        }
      }

      // SQLite parsing would go here using better-sqlite3 or sql.js
      this.emit('migration:warning', {
        message: 'Direct SQLite parsing requires additional setup. Using export format.',
      });

      return entries;
    } catch (error) {
      throw new Error(`Failed to load SQLite: ${(error as Error).message}`);
    }
  }

  private async loadFromMarkdown(): Promise<LegacyEntry[]> {
    const entries: LegacyEntry[] = [];
    const basePath = this.config.sourcePath;

    try {
      const files = await this.walkDirectory(basePath, '.md');

      for (const filePath of files) {
        try {
          const content = await fs.readFile(filePath, 'utf-8');
          const entry = this.parseMarkdownEntry(filePath, content, basePath);
          if (entry) {
            entries.push(entry);
          }
        } catch (error) {
          this.addError(filePath, (error as Error).message, 'PARSE_ERROR', true);
        }
      }

      return entries;
    } catch (error) {
      throw new Error(`Failed to load Markdown: ${(error as Error).message}`);
    }
  }

  private async loadFromJSON(): Promise<LegacyEntry[]> {
    const filePath = this.config.sourcePath;

    try {
      const content = await fs.readFile(filePath, 'utf-8');
      const data = JSON.parse(content);

      // Handle different JSON formats
      if (Array.isArray(data)) {
        return data;
      } else if (data.entries) {
        return data.entries;
      } else if (typeof data === 'object') {
        // Assume it's a namespace -> entries map
        const entries: LegacyEntry[] = [];
        for (const [namespace, namespaceEntries] of Object.entries(data)) {
          if (Array.isArray(namespaceEntries)) {
            for (const entry of namespaceEntries) {
              entries.push({ ...entry, namespace });
            }
          }
        }
        return entries;
      }

      return [];
    } catch (error) {
      throw new Error(`Failed to load JSON: ${(error as Error).message}`);
    }
  }

  private async loadFromMemoryManager(): Promise<LegacyEntry[]> {
    // Would integrate with existing MemoryManager instance
    // For now, try to load from common paths
    const possiblePaths = [
      './memory/memory-store.json',
      './.swarm/memory.db',
      './memory.json',
    ];

    for (const p of possiblePaths) {
      try {
        const fullPath = path.resolve(this.config.sourcePath, p);
        await fs.access(fullPath);
        return this.loadFromJSON();
      } catch {
        continue;
      }
    }

    return [];
  }

  private async loadFromSwarmMemory(): Promise<LegacyEntry[]> {
    // Would integrate with SwarmMemory partitions
    const entries: LegacyEntry[] = [];
    const basePath = this.config.sourcePath;

    try {
      // Check for swarm memory directory structure
      const partitionsPath = path.join(basePath, '.swarm', 'memory');
      const files = await this.walkDirectory(partitionsPath, '.json');

      for (const filePath of files) {
        try {
          const content = await fs.readFile(filePath, 'utf-8');
          const data = JSON.parse(content);

          // Extract namespace from file path
          const relativePath = path.relative(partitionsPath, filePath);
          const namespace = path.dirname(relativePath).replace(/\\/g, '/');

          if (Array.isArray(data)) {
            entries.push(...data.map((e: LegacyEntry) => ({ ...e, namespace })));
          } else if (data.entries) {
            entries.push(...data.entries.map((e: LegacyEntry) => ({ ...e, namespace })));
          }
        } catch (error) {
          this.addError(filePath, (error as Error).message, 'PARSE_ERROR', true);
        }
      }

      return entries;
    } catch (error) {
      return [];
    }
  }

  private async loadFromDistributedMemory(): Promise<LegacyEntry[]> {
    // Would integrate with DistributedMemorySystem nodes
    return this.loadFromSwarmMemory(); // Similar structure
  }

  // ===== Batch Processing =====

  private async processBatch(batch: LegacyEntry[]): Promise<void> {
    for (const legacyEntry of batch) {
      try {
        // Validate if enabled
        if (this.config.validateData) {
          const validation = this.validateEntry(legacyEntry);
          if (!validation.valid) {
            if (this.config.continueOnError) {
              this.addError(
                legacyEntry.key || 'unknown',
                validation.reason || 'Validation failed',
                'VALIDATION_ERROR',
                false
              );
              this.progress.skipped++;
              continue;
            } else {
              throw new Error(validation.reason);
            }
          }
        }

        // Transform to new format
        const newEntry = await this.transformEntry(legacyEntry);

        // Store in target
        await this.target.store(newEntry);
        this.progress.migrated++;
      } catch (error) {
        if (this.config.continueOnError) {
          this.addError(
            legacyEntry.key || 'unknown',
            (error as Error).message,
            'STORE_ERROR',
            true
          );
          this.progress.failed++;
        } else {
          throw error;
        }
      }
    }
  }

  private async transformEntry(legacy: LegacyEntry): Promise<MemoryEntry> {
    // Map namespace if configured
    let namespace = legacy.namespace || 'default';
    if (this.config.namespaceMapping && this.config.namespaceMapping[namespace]) {
      namespace = this.config.namespaceMapping[namespace];
    }

    // Determine content
    const content =
      typeof legacy.value === 'string'
        ? legacy.value
        : JSON.stringify(legacy.value);

    // Map type if configured
    let type: MemoryType = 'semantic';
    if (legacy.metadata?.type && typeof legacy.metadata.type === 'string') {
      if (this.config.typeMapping && this.config.typeMapping[legacy.metadata.type]) {
        type = this.config.typeMapping[legacy.metadata.type];
      } else if (this.isValidMemoryType(legacy.metadata.type)) {
        type = legacy.metadata.type as MemoryType;
      }
    }

    // Parse timestamps
    const createdAt = this.parseTimestamp(
      legacy.createdAt || legacy.created_at || legacy.timestamp
    );
    const updatedAt = this.parseTimestamp(
      legacy.updatedAt || legacy.updated_at || legacy.timestamp
    );

    const input: MemoryEntryInput = {
      key: legacy.key,
      content,
      type,
      namespace,
      tags: legacy.tags || [],
      metadata: {
        ...legacy.metadata,
        migrated: true,
        migrationSource: this.config.source,
        migrationTimestamp: Date.now(),
        originalValue: legacy.value,
      },
    };

    const entry = createDefaultEntry(input);
    entry.createdAt = createdAt;
    entry.updatedAt = updatedAt;

    // Generate embedding if configured
    if (this.config.generateEmbeddings && this.embeddingGenerator) {
      try {
        entry.embedding = await this.embeddingGenerator(content);
      } catch (error) {
        // Log but don't fail
        this.emit('migration:warning', {
          message: `Failed to generate embedding for ${legacy.key}: ${(error as Error).message}`,
        });
      }
    }

    return entry;
  }

  // ===== Helper Methods =====

  private initializeProgress(): MigrationProgress {
    return {
      total: 0,
      migrated: 0,
      failed: 0,
      skipped: 0,
      currentBatch: 0,
      totalBatches: 0,
      percentage: 0,
      estimatedTimeRemaining: 0,
      errors: [],
    };
  }

  private validateEntry(entry: LegacyEntry): { valid: boolean; reason?: string } {
    if (!entry.key || typeof entry.key !== 'string') {
      return { valid: false, reason: 'Missing or invalid key' };
    }

    if (entry.value === undefined) {
      return { valid: false, reason: 'Missing value' };
    }

    if (entry.key.length > 500) {
      return { valid: false, reason: 'Key too long (max 500 chars)' };
    }

    return { valid: true };
  }

  private addError(
    entryId: string,
    message: string,
    code: string,
    recoverable: boolean
  ): void {
    const error: MigrationError = {
      entryId,
      message,
      code,
      recoverable,
    };
    this.progress.errors.push(error);
    this.emit('migration:error', error);
  }

  private parseTimestamp(value: string | number | undefined): number {
    if (!value) return Date.now();

    if (typeof value === 'number') {
      // Handle both milliseconds and seconds
      return value > 1e12 ? value : value * 1000;
    }

    const parsed = Date.parse(value);
    return isNaN(parsed) ? Date.now() : parsed;
  }

  private isValidMemoryType(type: string): boolean {
    return ['episodic', 'semantic', 'procedural', 'working', 'cache'].includes(type);
  }

  private estimateTimeRemaining(
    startTime: number,
    completed: number,
    total: number
  ): number {
    if (completed === 0) return 0;

    const elapsed = Date.now() - startTime;
    const rate = completed / elapsed;
    const remaining = total - completed;

    return Math.round(remaining / rate);
  }

  private generateSummary(): string {
    const { migrated, failed, skipped, total, errors } = this.progress;

    let summary = `Migrated ${migrated}/${total} entries`;

    if (failed > 0) {
      summary += `, ${failed} failed`;
    }

    if (skipped > 0) {
      summary += `, ${skipped} skipped`;
    }

    if (errors.length > 0) {
      const errorTypes = new Map<string, number>();
      for (const error of errors) {
        errorTypes.set(error.code, (errorTypes.get(error.code) || 0) + 1);
      }

      const errorSummary = Array.from(errorTypes.entries())
        .map(([code, count]) => `${code}: ${count}`)
        .join(', ');

      summary += `. Errors: ${errorSummary}`;
    }

    return summary;
  }

  private async walkDirectory(dir: string, extension: string): Promise<string[]> {
    const files: string[] = [];

    try {
      const entries = await fs.readdir(dir, { withFileTypes: true });

      for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);

        if (entry.isDirectory()) {
          const subFiles = await this.walkDirectory(fullPath, extension);
          files.push(...subFiles);
        } else if (entry.isFile() && entry.name.endsWith(extension)) {
          files.push(fullPath);
        }
      }
    } catch (error) {
      // Directory doesn't exist or isn't readable
    }

    return files;
  }

  private parseMarkdownEntry(
    filePath: string,
    content: string,
    basePath: string
  ): LegacyEntry | null {
    // Extract frontmatter if present
    const frontmatterMatch = content.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);

    let metadata: Record<string, unknown> = {};
    let body = content;

    if (frontmatterMatch) {
      try {
        // Simple YAML-like parsing
        const frontmatter = frontmatterMatch[1];
        for (const line of frontmatter.split('\n')) {
          const colonIndex = line.indexOf(':');
          if (colonIndex > 0) {
            const key = line.substring(0, colonIndex).trim();
            let value: unknown = line.substring(colonIndex + 1).trim();

            // Parse common types
            if (value === 'true') value = true;
            else if (value === 'false') value = false;
            else if (typeof value === 'string' && /^\d+$/.test(value)) value = parseInt(value, 10);
            else if (typeof value === 'string' && value.startsWith('[') && value.endsWith(']')) {
              try {
                value = JSON.parse(value.replace(/'/g, '"'));
              } catch {
                // Keep as string
              }
            }

            metadata[key] = value;
          }
        }
        body = frontmatterMatch[2];
      } catch {
        // Failed to parse frontmatter, use whole content
      }
    }

    // Derive key from file path
    const relativePath = path.relative(basePath, filePath);
    const key = relativePath
      .replace(/\\/g, '/')
      .replace(/\.md$/, '')
      .replace(/\//g, ':');

    // Derive namespace from directory structure
    const namespace = path.dirname(relativePath).replace(/\\/g, '/') || 'default';

    return {
      key,
      value: body.trim(),
      namespace,
      tags: Array.isArray(metadata.tags) ? metadata.tags : [],
      metadata,
      timestamp: Date.now(),
    };
  }
}

/**
 * Convenience function to create a migrator
 */
export function createMigrator(
  target: AgentDBAdapter,
  source: MigrationSource,
  sourcePath: string,
  options: Partial<MigrationConfig> = {},
  embeddingGenerator?: EmbeddingGenerator
): MemoryMigrator {
  return new MemoryMigrator(
    target,
    { source, sourcePath, ...options },
    embeddingGenerator
  );
}

/**
 * Migrate from multiple sources
 */
export async function migrateMultipleSources(
  target: AgentDBAdapter,
  sources: Array<{ source: MigrationSource; path: string }>,
  options: Partial<MigrationConfig> = {},
  embeddingGenerator?: EmbeddingGenerator
): Promise<MigrationResult[]> {
  const results: MigrationResult[] = [];

  for (const { source, path: sourcePath } of sources) {
    const migrator = createMigrator(
      target,
      source,
      sourcePath,
      options,
      embeddingGenerator
    );
    const result = await migrator.migrate();
    results.push(result);
  }

  return results;
}

export default MemoryMigrator;

/**
 * PersistentSonaCoordinator - SONA learning with RVF persistence
 *
 * Wraps RvfLearningStore to provide an in-memory pattern bank with
 * brute-force cosine similarity, trajectory buffering, EWC tracking,
 * and automatic periodic persistence to disk.
 *
 * This is intentionally decoupled from the ruvector SONA classes:
 * it defines its own compatible types and delegates persistence to
 * RvfLearningStore.
 *
 * @module @claude-flow/memory/persistent-sona
 */

import {
  RvfLearningStore,
} from './rvf-learning-store.js';
import type {
  RvfLearningStoreConfig,
  PatternRecord,
  EwcRecord,
  TrajectoryRecord,
} from './rvf-learning-store.js';

// ===== Types =====

export interface PersistentSonaConfig {
  /** Path to the RVF learning store file */
  storePath: string;
  /** Cosine similarity threshold for pattern matching (default: 0.85) */
  patternThreshold?: number;
  /** Maximum buffered trajectories before oldest are evicted (default: 1000) */
  maxTrajectoryBuffer?: number;
  /** Auto-persist interval in ms (default: 30000) */
  autoPersistInterval?: number;
  /** Enable verbose logging (default: false) */
  verbose?: boolean;
}

// ===== Constants =====

const DEFAULT_PATTERN_THRESHOLD = 0.85;
const DEFAULT_MAX_TRAJECTORY_BUFFER = 1000;
const DEFAULT_AUTO_PERSIST_MS = 30_000;

// ===== Helpers =====

/**
 * Compute cosine similarity between two number arrays.
 * Returns 0 when either vector has zero magnitude.
 */
function cosineSimilarity(a: number[], b: number[]): number {
  const len = Math.min(a.length, b.length);
  let dot = 0;
  let normA = 0;
  let normB = 0;

  // Process in groups of 4 for better throughput
  let i = 0;
  for (; i + 3 < len; i += 4) {
    dot += a[i] * b[i] + a[i + 1] * b[i + 1] + a[i + 2] * b[i + 2] + a[i + 3] * b[i + 3];
    normA += a[i] * a[i] + a[i + 1] * a[i + 1] + a[i + 2] * a[i + 2] + a[i + 3] * a[i + 3];
    normB += b[i] * b[i] + b[i + 1] * b[i + 1] + b[i + 2] * b[i + 2] + b[i + 3] * b[i + 3];
  }
  for (; i < len; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }

  const denom = Math.sqrt(normA) * Math.sqrt(normB);
  return denom > 0 ? dot / denom : 0;
}

function generateId(prefix: string): string {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

// ===== PersistentSonaCoordinator =====

/**
 * Coordinates SONA learning with persistent storage.
 *
 * @example
 * ```typescript
 * const sona = new PersistentSonaCoordinator({
 *   storePath: './data/sona-learning.rvls',
 * });
 * await sona.initialize();
 *
 * // Store a pattern
 * const id = sona.storePattern('query_response', embedding);
 *
 * // Find similar patterns
 * const matches = sona.findSimilarPatterns(queryEmbedding, 5);
 *
 * // Record a trajectory
 * sona.recordTrajectory({ id: 'traj-1', steps: [...], outcome: 'success', ... });
 *
 * // Periodic background learning
 * const result = sona.runBackgroundLoop();
 *
 * await sona.shutdown();
 * ```
 */
export class PersistentSonaCoordinator {
  private store: RvfLearningStore;
  private patterns: Map<string, PatternRecord> = new Map();
  private trajectoryBuffer: TrajectoryRecord[] = [];
  private ewcState: EwcRecord | null = null;
  private patternThreshold: number;
  private maxTrajectoryBuffer: number;
  private verbose: boolean;
  private initialized = false;

  constructor(config: PersistentSonaConfig) {
    this.patternThreshold = config.patternThreshold ?? DEFAULT_PATTERN_THRESHOLD;
    this.maxTrajectoryBuffer = config.maxTrajectoryBuffer ?? DEFAULT_MAX_TRAJECTORY_BUFFER;
    this.verbose = config.verbose ?? false;

    const storeConfig: RvfLearningStoreConfig = {
      storePath: config.storePath,
      autoPersistInterval: config.autoPersistInterval ?? DEFAULT_AUTO_PERSIST_MS,
      verbose: config.verbose,
    };

    this.store = new RvfLearningStore(storeConfig);
  }

  /**
   * Initialize by loading persisted state from the RVF store.
   */
  async initialize(): Promise<void> {
    if (this.initialized) return;

    await this.store.initialize();

    // Rebuild in-memory state from store
    const patterns = await this.store.loadPatterns();
    for (const p of patterns) {
      this.patterns.set(p.id, p);
    }

    const ewc = await this.store.loadEwcState();
    this.ewcState = ewc;

    const trajectories = await this.store.getTrajectories();
    // getTrajectories returns newest-first, reverse for chronological buffer
    this.trajectoryBuffer = trajectories.reverse();

    this.initialized = true;
    this.log(
      `Initialized: ${this.patterns.size} patterns, ` +
      `${this.trajectoryBuffer.length} trajectories, ` +
      `EWC: ${this.ewcState ? 'yes' : 'no'}`,
    );
  }

  // ===== Pattern operations =====

  /**
   * Store a new pattern and return its ID.
   *
   * @param type - Pattern type (e.g. 'query_response', 'routing')
   * @param embedding - The pattern embedding vector
   * @param metadata - Optional extra metadata (currently unused, reserved)
   * @returns The generated pattern ID
   */
  storePattern(
    type: string,
    embedding: number[],
    metadata?: Record<string, unknown>,
  ): string {
    this.ensureInitialized();

    const id = generateId('pat');
    const record: PatternRecord = {
      id,
      type,
      embedding: [...embedding],
      successRate: 1.0,
      useCount: 0,
      lastUsed: new Date().toISOString(),
    };

    this.patterns.set(id, record);
    // Mark for persistence on next persist() call
    void this.store.savePatterns([record]).catch(() => {});
    return id;
  }

  /**
   * Find the k most similar patterns above the configured threshold.
   * Uses brute-force cosine similarity (suitable for small pattern sets).
   */
  findSimilarPatterns(embedding: number[], k: number = 5): PatternRecord[] {
    this.ensureInitialized();

    const results: Array<{ record: PatternRecord; score: number }> = [];

    for (const record of this.patterns.values()) {
      const score = cosineSimilarity(embedding, record.embedding);
      if (score >= this.patternThreshold) {
        results.push({ record, score });
      }
    }

    // Sort descending by score and take top-k
    results.sort((a, b) => b.score - a.score);

    return results.slice(0, k).map((r) => r.record);
  }

  /**
   * Record a pattern usage outcome. Updates the success rate using an
   * exponential moving average (alpha = 0.1).
   */
  recordPatternUsage(patternId: string, success: boolean): void {
    this.ensureInitialized();

    const pattern = this.patterns.get(patternId);
    if (!pattern) return;

    pattern.useCount++;
    pattern.lastUsed = new Date().toISOString();

    const alpha = 0.1;
    const outcome = success ? 1.0 : 0.0;
    pattern.successRate = alpha * outcome + (1 - alpha) * pattern.successRate;
  }

  /**
   * Remove patterns that have low success rates after sufficient usage.
   *
   * @returns The number of patterns pruned
   */
  prunePatterns(minSuccessRate: number = 0.3, minUseCount: number = 5): number {
    this.ensureInitialized();

    let pruned = 0;
    for (const [id, pattern] of this.patterns) {
      if (pattern.useCount >= minUseCount && pattern.successRate < minSuccessRate) {
        this.patterns.delete(id);
        pruned++;
      }
    }

    if (pruned > 0) {
      this.log(`Pruned ${pruned} low-performing patterns`);
    }

    return pruned;
  }

  // ===== Trajectory tracking =====

  /**
   * Buffer a completed trajectory for later processing.
   * When the buffer exceeds maxTrajectoryBuffer, the oldest entries
   * are evicted.
   */
  recordTrajectory(trajectory: TrajectoryRecord): void {
    this.ensureInitialized();

    const copy = { ...trajectory };
    this.trajectoryBuffer.push(copy);

    // Persist to store immediately so evicted entries are not lost
    void this.store.appendTrajectory(copy).catch(() => {});

    while (this.trajectoryBuffer.length > this.maxTrajectoryBuffer) {
      this.trajectoryBuffer.shift();
    }
  }

  // ===== Learning loop =====

  /**
   * Process buffered trajectories to extract new patterns.
   * Successful and partial trajectories are mined for high-confidence
   * steps; new patterns are stored if they are sufficiently different
   * from existing ones.
   *
   * After processing, the trajectory buffer is cleared and low-performing
   * patterns are pruned.
   *
   * @returns Summary of the learning pass
   */
  runBackgroundLoop(): {
    patternsLearned: number;
    trajectoriesProcessed: number;
  } {
    this.ensureInitialized();

    let patternsLearned = 0;
    const trajectoriesProcessed = this.trajectoryBuffer.length;

    for (const traj of this.trajectoryBuffer) {
      if (traj.outcome === 'success' || traj.outcome === 'partial') {
        patternsLearned += this.extractPatternsFromTrajectory(traj);
      }
    }

    this.prunePatterns();
    this.trajectoryBuffer = [];

    this.log(
      `Background loop: ${patternsLearned} patterns learned, ` +
      `${trajectoriesProcessed} trajectories processed`,
    );

    return { patternsLearned, trajectoriesProcessed };
  }

  // ===== Persistence =====

  /**
   * Flush current in-memory state to the RVF store on disk.
   */
  async persist(): Promise<void> {
    const allPatterns = Array.from(this.patterns.values());
    await this.store.savePatterns(allPatterns);

    if (this.ewcState) {
      await this.store.saveEwcState(this.ewcState);
    }

    // Persist any buffered trajectories that have not yet been saved
    for (const traj of this.trajectoryBuffer) {
      await this.store.appendTrajectory(traj);
    }

    await this.store.persist();
  }

  /**
   * Persist state and shut down the store.
   */
  async shutdown(): Promise<void> {
    if (!this.initialized) return;

    await this.persist();
    await this.store.close();
    this.initialized = false;
    this.log('Shutdown complete');
  }

  // ===== Stats =====

  /**
   * Return a summary of the coordinator's current state.
   */
  getStats(): {
    patterns: number;
    avgSuccessRate: number;
    trajectoriesBuffered: number;
    ewcTasksLearned: number;
  } {
    let totalSuccessRate = 0;
    let count = 0;
    for (const p of this.patterns.values()) {
      totalSuccessRate += p.successRate;
      count++;
    }

    return {
      patterns: this.patterns.size,
      avgSuccessRate: count > 0 ? totalSuccessRate / count : 0,
      trajectoriesBuffered: this.trajectoryBuffer.length,
      ewcTasksLearned: this.ewcState?.tasksLearned ?? 0,
    };
  }

  // ===== Private =====

  /**
   * Extract patterns from a trajectory's high-confidence steps.
   * A step produces a new pattern only if no sufficiently similar
   * pattern already exists.
   */
  private extractPatternsFromTrajectory(trajectory: TrajectoryRecord): number {
    let extracted = 0;

    for (const step of trajectory.steps) {
      if (step.confidence < this.patternThreshold) continue;

      const embedding = this.createHashEmbedding(step.input + step.output);
      const similar = this.findSimilarPatterns(embedding, 1);

      if (similar.length === 0) {
        this.storePattern(step.type, embedding);
        extracted++;
      }
    }

    return extracted;
  }

  /**
   * Deterministic hash-based embedding for pattern extraction.
   * This is a lightweight stand-in for a real embedding model,
   * matching the approach used in SonaCoordinator.
   */
  private createHashEmbedding(text: string, dim: number = 64): number[] {
    const embedding = new Array<number>(dim).fill(0);

    for (let i = 0; i < text.length; i++) {
      const idx = (text.charCodeAt(i) * (i + 1)) % dim;
      embedding[idx] += 0.1;
    }

    let norm = 0;
    for (let i = 0; i < dim; i++) {
      norm += embedding[i] * embedding[i];
    }
    norm = Math.sqrt(norm) || 1;

    for (let i = 0; i < dim; i++) {
      embedding[i] /= norm;
    }

    return embedding;
  }

  private ensureInitialized(): void {
    if (!this.initialized) {
      throw new Error(
        'PersistentSonaCoordinator has not been initialized. Call initialize() first.',
      );
    }
  }

  private log(message: string): void {
    if (this.verbose) {
      // eslint-disable-next-line no-console
      console.log(`[PersistentSona] ${message}`);
    }
  }
}

/**
 * V3 Query Builder
 *
 * Fluent API for building memory queries with filter chaining,
 * sorting options, and pagination support.
 *
 * @module v3/memory/query-builder
 */

import {
  MemoryQuery,
  QueryType,
  MemoryType,
  AccessLevel,
  DistanceMetric,
} from './types.js';

/**
 * Sort direction
 */
export type SortDirection = 'asc' | 'desc';

/**
 * Sort field options
 */
export type SortField =
  | 'createdAt'
  | 'updatedAt'
  | 'lastAccessedAt'
  | 'accessCount'
  | 'key'
  | 'score';

/**
 * Query builder state
 */
interface QueryBuilderState {
  type: QueryType;
  content?: string;
  embedding?: Float32Array;
  key?: string;
  keyPrefix?: string;
  namespace?: string;
  tags: string[];
  memoryType?: MemoryType;
  accessLevel?: AccessLevel;
  ownerId?: string;
  metadata: Record<string, unknown>;
  createdAfter?: number;
  createdBefore?: number;
  updatedAfter?: number;
  updatedBefore?: number;
  limit: number;
  offset: number;
  threshold?: number;
  includeExpired: boolean;
  distanceMetric?: DistanceMetric;
  sortField?: SortField;
  sortDirection: SortDirection;
}

/**
 * Fluent query builder for constructing memory queries
 *
 * @example
 * ```typescript
 * const query = new QueryBuilder()
 *   .semantic('user authentication patterns')
 *   .inNamespace('security')
 *   .withTags(['auth', 'patterns'])
 *   .ofType('semantic')
 *   .limit(10)
 *   .threshold(0.8)
 *   .build();
 * ```
 */
export class QueryBuilder {
  private state: QueryBuilderState;

  constructor() {
    this.state = {
      type: 'hybrid',
      tags: [],
      metadata: {},
      limit: 10,
      offset: 0,
      includeExpired: false,
      sortDirection: 'desc',
    };
  }

  /**
   * Create a semantic (vector similarity) query
   */
  semantic(content: string): this {
    this.state.type = 'semantic';
    this.state.content = content;
    return this;
  }

  /**
   * Create a semantic query with pre-computed embedding
   */
  semanticWithEmbedding(embedding: Float32Array): this {
    this.state.type = 'semantic';
    this.state.embedding = embedding;
    return this;
  }

  /**
   * Create an exact key match query
   */
  exact(key: string): this {
    this.state.type = 'exact';
    this.state.key = key;
    return this;
  }

  /**
   * Create a key prefix match query
   */
  prefix(keyPrefix: string): this {
    this.state.type = 'prefix';
    this.state.keyPrefix = keyPrefix;
    return this;
  }

  /**
   * Create a tag-based query
   */
  byTags(tags: string[]): this {
    this.state.type = 'tag';
    this.state.tags = tags;
    return this;
  }

  /**
   * Create a hybrid query (semantic + filters)
   */
  hybrid(content: string): this {
    this.state.type = 'hybrid';
    this.state.content = content;
    return this;
  }

  /**
   * Filter by namespace
   */
  inNamespace(namespace: string): this {
    this.state.namespace = namespace;
    return this;
  }

  /**
   * Add tag filter (entries must have all specified tags)
   */
  withTags(tags: string[]): this {
    this.state.tags = [...this.state.tags, ...tags];
    return this;
  }

  /**
   * Add a single tag filter
   */
  withTag(tag: string): this {
    this.state.tags.push(tag);
    return this;
  }

  /**
   * Filter by memory type
   */
  ofType(type: MemoryType): this {
    this.state.memoryType = type;
    return this;
  }

  /**
   * Filter by access level
   */
  withAccessLevel(level: AccessLevel): this {
    this.state.accessLevel = level;
    return this;
  }

  /**
   * Filter by owner
   */
  ownedBy(ownerId: string): this {
    this.state.ownerId = ownerId;
    return this;
  }

  /**
   * Filter by metadata field
   */
  whereMetadata(key: string, value: unknown): this {
    this.state.metadata[key] = value;
    return this;
  }

  /**
   * Filter by creation date range
   */
  createdBetween(after: Date | number, before?: Date | number): this {
    this.state.createdAfter = after instanceof Date ? after.getTime() : after;
    if (before !== undefined) {
      this.state.createdBefore = before instanceof Date ? before.getTime() : before;
    }
    return this;
  }

  /**
   * Filter entries created after a date
   */
  createdAfter(date: Date | number): this {
    this.state.createdAfter = date instanceof Date ? date.getTime() : date;
    return this;
  }

  /**
   * Filter entries created before a date
   */
  createdBefore(date: Date | number): this {
    this.state.createdBefore = date instanceof Date ? date.getTime() : date;
    return this;
  }

  /**
   * Filter by update date range
   */
  updatedBetween(after: Date | number, before?: Date | number): this {
    this.state.updatedAfter = after instanceof Date ? after.getTime() : after;
    if (before !== undefined) {
      this.state.updatedBefore = before instanceof Date ? before.getTime() : before;
    }
    return this;
  }

  /**
   * Filter entries updated in the last N milliseconds
   */
  updatedWithin(milliseconds: number): this {
    this.state.updatedAfter = Date.now() - milliseconds;
    return this;
  }

  /**
   * Set maximum number of results
   */
  limit(count: number): this {
    this.state.limit = Math.max(1, count);
    return this;
  }

  /**
   * Set pagination offset
   */
  offset(count: number): this {
    this.state.offset = Math.max(0, count);
    return this;
  }

  /**
   * Set pagination with page number and size
   */
  page(pageNumber: number, pageSize: number): this {
    this.state.limit = Math.max(1, pageSize);
    this.state.offset = Math.max(0, (pageNumber - 1) * pageSize);
    return this;
  }

  /**
   * Set minimum similarity threshold for semantic search
   */
  threshold(minScore: number): this {
    this.state.threshold = Math.max(0, Math.min(1, minScore));
    return this;
  }

  /**
   * Include expired entries in results
   */
  includeExpired(include: boolean = true): this {
    this.state.includeExpired = include;
    return this;
  }

  /**
   * Set distance metric for semantic search
   */
  withMetric(metric: DistanceMetric): this {
    this.state.distanceMetric = metric;
    return this;
  }

  /**
   * Sort results by field
   */
  sortBy(field: SortField, direction: SortDirection = 'desc'): this {
    this.state.sortField = field;
    this.state.sortDirection = direction;
    return this;
  }

  /**
   * Sort by creation date (newest first)
   */
  newestFirst(): this {
    return this.sortBy('createdAt', 'desc');
  }

  /**
   * Sort by creation date (oldest first)
   */
  oldestFirst(): this {
    return this.sortBy('createdAt', 'asc');
  }

  /**
   * Sort by relevance score (highest first)
   */
  mostRelevant(): this {
    return this.sortBy('score', 'desc');
  }

  /**
   * Sort by access count (most accessed first)
   */
  mostAccessed(): this {
    return this.sortBy('accessCount', 'desc');
  }

  /**
   * Sort by last accessed time (most recent first)
   */
  recentlyAccessed(): this {
    return this.sortBy('lastAccessedAt', 'desc');
  }

  /**
   * Build the final query object
   */
  build(): MemoryQuery {
    const query: MemoryQuery = {
      type: this.state.type,
      limit: this.state.limit,
    };

    // Add optional fields
    if (this.state.content) query.content = this.state.content;
    if (this.state.embedding) query.embedding = this.state.embedding;
    if (this.state.key) query.key = this.state.key;
    if (this.state.keyPrefix) query.keyPrefix = this.state.keyPrefix;
    if (this.state.namespace) query.namespace = this.state.namespace;
    if (this.state.tags.length > 0) query.tags = this.state.tags;
    if (this.state.memoryType) query.memoryType = this.state.memoryType;
    if (this.state.accessLevel) query.accessLevel = this.state.accessLevel;
    if (this.state.ownerId) query.ownerId = this.state.ownerId;
    if (Object.keys(this.state.metadata).length > 0) {
      query.metadata = this.state.metadata;
    }
    if (this.state.createdAfter) query.createdAfter = this.state.createdAfter;
    if (this.state.createdBefore) query.createdBefore = this.state.createdBefore;
    if (this.state.updatedAfter) query.updatedAfter = this.state.updatedAfter;
    if (this.state.updatedBefore) query.updatedBefore = this.state.updatedBefore;
    if (this.state.offset > 0) query.offset = this.state.offset;
    if (this.state.threshold !== undefined) query.threshold = this.state.threshold;
    if (this.state.includeExpired) query.includeExpired = this.state.includeExpired;
    if (this.state.distanceMetric) query.distanceMetric = this.state.distanceMetric;

    return query;
  }

  /**
   * Clone this builder
   */
  clone(): QueryBuilder {
    const cloned = new QueryBuilder();
    cloned.state = {
      ...this.state,
      tags: [...this.state.tags],
      metadata: { ...this.state.metadata },
    };
    return cloned;
  }

  /**
   * Reset the builder to initial state
   */
  reset(): this {
    this.state = {
      type: 'hybrid',
      tags: [],
      metadata: {},
      limit: 10,
      offset: 0,
      includeExpired: false,
      sortDirection: 'desc',
    };
    return this;
  }
}

/**
 * Convenience function to create a new query builder
 */
export function query(): QueryBuilder {
  return new QueryBuilder();
}

/**
 * Predefined query templates for common use cases
 */
export const QueryTemplates = {
  /**
   * Find recent entries in a namespace
   */
  recentInNamespace(namespace: string, limit: number = 10): MemoryQuery {
    return query()
      .inNamespace(namespace)
      .newestFirst()
      .limit(limit)
      .build();
  },

  /**
   * Find entries by exact key
   */
  byKey(namespace: string, key: string): MemoryQuery {
    return query()
      .exact(key)
      .inNamespace(namespace)
      .limit(1)
      .build();
  },

  /**
   * Semantic search with threshold
   */
  semanticSearch(
    content: string,
    namespace?: string,
    threshold: number = 0.7,
    limit: number = 10
  ): MemoryQuery {
    const builder = query()
      .semantic(content)
      .threshold(threshold)
      .limit(limit);

    if (namespace) {
      builder.inNamespace(namespace);
    }

    return builder.build();
  },

  /**
   * Find entries with specific tags
   */
  withTags(tags: string[], namespace?: string, limit: number = 10): MemoryQuery {
    const builder = query()
      .byTags(tags)
      .limit(limit);

    if (namespace) {
      builder.inNamespace(namespace);
    }

    return builder.build();
  },

  /**
   * Find entries owned by a specific agent
   */
  ownedBy(ownerId: string, namespace?: string, limit: number = 10): MemoryQuery {
    const builder = query()
      .ownedBy(ownerId)
      .newestFirst()
      .limit(limit);

    if (namespace) {
      builder.inNamespace(namespace);
    }

    return builder.build();
  },

  /**
   * Find episodic memories within a time range
   */
  episodicInRange(
    after: Date | number,
    before: Date | number,
    limit: number = 100
  ): MemoryQuery {
    return query()
      .ofType('episodic')
      .createdBetween(after, before)
      .oldestFirst()
      .limit(limit)
      .build();
  },

  /**
   * Find hot entries (frequently accessed)
   */
  hotEntries(namespace?: string, limit: number = 10): MemoryQuery {
    const builder = query()
      .mostAccessed()
      .limit(limit);

    if (namespace) {
      builder.inNamespace(namespace);
    }

    return builder.build();
  },

  /**
   * Find stale entries (not accessed recently)
   */
  staleEntries(
    staleThresholdMs: number,
    namespace?: string,
    limit: number = 100
  ): MemoryQuery {
    const builder = query()
      .updatedBetween(0, Date.now() - staleThresholdMs)
      .sortBy('lastAccessedAt', 'asc')
      .limit(limit);

    if (namespace) {
      builder.inNamespace(namespace);
    }

    return builder.build();
  },
};

