// ----------------------------------------------------------------------------
// HnswLite — small brute-force-degrading HNSW used ONLY by RvfBackend.
// Inlined here by ADR-125 Phase 3 so the canonical `src/hnsw-index.ts` can be
// the single HNSW implementation in the public surface. Not exported.
// ----------------------------------------------------------------------------

interface HnswSearchResult {
  id: string;
  score: number;
}

class HnswLite {
  private vectors = new Map<string, Float32Array>();
  private neighbors = new Map<string, Set<string>>();
  private readonly dimensions: number;
  private readonly maxNeighbors: number;
  private readonly efConstruction: number;
  private readonly metric: string;

  constructor(dimensions: number, m: number, efConstruction: number, metric: string) {
    this.dimensions = dimensions;
    this.maxNeighbors = m;
    this.efConstruction = efConstruction;
    this.metric = metric;
  }

  get size(): number { return this.vectors.size; }

  add(id: string, vector: Float32Array): void {
    this.vectors.set(id, vector);
    if (this.vectors.size === 1) {
      this.neighbors.set(id, new Set());
      return;
    }
    const nearest = this.findNearest(vector, this.maxNeighbors);
    const neighborSet = new Set<string>();
    for (const n of nearest) {
      neighborSet.add(n.id);
      const nNeighbors = this.neighbors.get(n.id);
      if (nNeighbors) {
        nNeighbors.add(id);
        if (nNeighbors.size > this.maxNeighbors * 2) this.pruneNeighbors(n.id);
      }
    }
    this.neighbors.set(id, neighborSet);
  }

  remove(id: string): void {
    this.vectors.delete(id);
    const my = this.neighbors.get(id);
    if (my) for (const nId of my) this.neighbors.get(nId)?.delete(id);
    this.neighbors.delete(id);
  }

  search(query: Float32Array, k: number, threshold?: number): HnswSearchResult[] {
    if (this.vectors.size === 0) return [];
    if (this.vectors.size <= k * 2) return this.bruteForce(query, k, threshold);

    const visited = new Set<string>();
    const candidates: HnswSearchResult[] = [];

    let entryId: string | undefined;
    let bestScore = -1;
    for (const [id] of this.vectors) {
      const score = this.similarity(query, this.vectors.get(id)!);
      if (score > bestScore) { bestScore = score; entryId = id; }
      if (visited.size >= Math.min(this.efConstruction, this.vectors.size)) break;
      visited.add(id);
      candidates.push({ id, score });
    }

    if (entryId) {
      const queue = [entryId];
      let idx = 0;
      while (idx < queue.length && visited.size < this.efConstruction * 2) {
        const currentId = queue[idx++];
        const currentNeighbors = this.neighbors.get(currentId);
        if (!currentNeighbors) continue;
        for (const nId of currentNeighbors) {
          if (visited.has(nId)) continue;
          visited.add(nId);
          const vec = this.vectors.get(nId);
          if (!vec) continue;
          const score = this.similarity(query, vec);
          candidates.push({ id: nId, score });
          queue.push(nId);
        }
      }
    }

    candidates.sort((a, b) => b.score - a.score);
    let filtered = candidates;
    if (threshold !== undefined) filtered = filtered.filter(c => c.score >= threshold);
    return filtered.slice(0, k);
  }

  private bruteForce(query: Float32Array, k: number, threshold?: number): HnswSearchResult[] {
    const results: HnswSearchResult[] = [];
    for (const [id, vec] of this.vectors) {
      const score = this.similarity(query, vec);
      if (threshold !== undefined && score < threshold) continue;
      results.push({ id, score });
    }
    results.sort((a, b) => b.score - a.score);
    return results.slice(0, k);
  }

  private findNearest(query: Float32Array, k: number): HnswSearchResult[] {
    return this.bruteForce(query, k);
  }

  private pruneNeighbors(id: string): void {
    const my = this.neighbors.get(id);
    if (!my) return;
    const vec = this.vectors.get(id);
    if (!vec) return;
    const scored: HnswSearchResult[] = [];
    for (const nId of my) {
      const nVec = this.vectors.get(nId);
      if (!nVec) continue;
      scored.push({ id: nId, score: this.similarity(vec, nVec) });
    }
    scored.sort((a, b) => b.score - a.score);
    const keep = new Set(scored.slice(0, this.maxNeighbors).map(s => s.id));
    for (const nId of my) if (!keep.has(nId)) my.delete(nId);
  }

  private similarity(a: Float32Array, b: Float32Array): number {
    if (this.metric === 'dot') return dotProduct(a, b);
    if (this.metric === 'euclidean') return 1 / (1 + euclideanDistance(a, b));
    return cosineSimilarity(a, b);
  }
}

function cosineSimilarity(a: Float32Array, b: Float32Array): number {
  let dot = 0, normA = 0, normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  if (normA === 0 || normB === 0) return 0;
  return dot / (Math.sqrt(normA) * Math.sqrt(normB));
}

function dotProduct(a: Float32Array, b: Float32Array): number {
  let sum = 0;
  for (let i = 0; i < a.length; i++) sum += a[i] * b[i];
  return sum;
}

function euclideanDistance(a: Float32Array, b: Float32Array): number {
  let sum = 0;
  for (let i = 0; i < a.length; i++) { const d = a[i] - b[i]; sum += d * d; }
  return Math.sqrt(sum);
}

/** Validate a file path is safe (no null bytes, no traversal above root) */
function validatePath(p: string): void {
  if (p === ':memory:') return;
  if (p.includes('\0')) throw new Error('Path contains null bytes');
  const resolved = resolve(p);
  if (resolved.includes('\0')) throw new Error('Resolved path contains null bytes');
}

export interface RvfBackendConfig {
  databasePath: string;
  dimensions?: number;
  metric?: 'cosine' | 'euclidean' | 'dot';
  quantization?: 'fp32' | 'fp16' | 'int8';
  hnswM?: number;
  hnswEfConstruction?: number;
  maxElements?: number;
  verbose?: boolean;
  defaultNamespace?: string;
  autoPersistInterval?: number;
}

interface RvfHeader {
  magic: string;
  version: number;
  dimensions: number;
  metric: string;
  quantization: string;
  entryCount: number;
  createdAt: number;
  updatedAt: number;
}

const MAGIC = 'RVF\0';
const VERSION = 1;
const DEFAULT_DIMENSIONS = 1536;
const DEFAULT_M = 16;
const DEFAULT_EF_CONSTRUCTION = 200;
const DEFAULT_MAX_ELEMENTS = 100000;
const DEFAULT_PERSIST_INTERVAL = 30000;

export class RvfBackend implements IMemoryBackend {
  private entries = new Map<string, MemoryEntry>();
  private keyIndex = new Map<string, string>();
  private hnswIndex: HnswLite | null = null;
  private nativeDb: any = null;
  private config: Required<RvfBackendConfig>;
  private initialized = false;
  private dirty = false;
  private persisting = false;
  private persistTimer: ReturnType<typeof setInterval> | null = null;
  private queryTimes: number[] = [];
  private searchTimes: number[] = [];

  constructor(config: RvfBackendConfig) {
    const dimensions = config.dimensions ?? DEFAULT_DIMENSIONS;
    if (!Number.isInteger(dimensions) || dimensions < 1 || dimensions > 10000) {
      throw new Error(`Invalid dimensions: ${dimensions}. Must be an integer between 1 and 10000.`);
    }
    this.config = {
      databasePath: config.databasePath,
      dimensions,
      metric: config.metric ?? 'cosine',
      quantization: config.quantization ?? 'fp32',
      hnswM: config.hnswM ?? DEFAULT_M,
      hnswEfConstruction: config.hnswEfConstruction ?? DEFAULT_EF_CONSTRUCTION,
      maxElements: config.maxElements ?? DEFAULT_MAX_ELEMENTS,
      verbose: config.verbose ?? false,
      defaultNamespace: config.defaultNamespace ?? 'default',
      autoPersistInterval: config.autoPersistInterval ?? DEFAULT_PERSIST_INTERVAL,
    };
    validatePath(this.config.databasePath);
  }

  async initialize(): Promise<void> {
    if (this.initialized) return;

    const useNative = await this.tryNativeInit();
    if (!useNative) {
      this.hnswIndex = new HnswLite(
        this.config.dimensions,
        this.config.hnswM,
        this.config.hnswEfConstruction,
        this.config.metric,
      );
      await this.loadFromDisk();
    }

    if (this.config.autoPersistInterval > 0 && this.config.databasePath !== ':memory:') {
      this.persistTimer = setInterval(() => {
        if (this.dirty && !this.persisting) this.persistToDisk().catch(() => {});
      }, this.config.autoPersistInterval);
      if (this.persistTimer.unref) this.persistTimer.unref();
    }

    this.initialized = true;
    if (this.config.verbose) {
      const mode = this.nativeDb ? 'native @ruvector/rvf' : 'pure-TS fallback';
      console.log(`[RvfBackend] Initialized (${mode}), ${this.entries.size} entries loaded`);
    }
  }

  async shutdown(): Promise<void> {
    if (!this.initialized) return;

    if (this.persistTimer) {
      clearInterval(this.persistTimer);
      this.persistTimer = null;
    }

    if (this.dirty) {
      await this.persistToDisk();
    }

    if (this.nativeDb) {
      try { await this.nativeDb.close(); } catch {}
      this.nativeDb = null;
    }

    this.entries.clear();
    this.keyIndex.clear();
    this.hnswIndex = null;
    this.initialized = false;
  }

  async store(entry: MemoryEntry): Promise<void> {
    const ns = entry.namespace || this.config.defaultNamespace;
    const e = ns !== entry.namespace ? { ...entry, namespace: ns } : entry;
    this.entries.set(e.id, e);
    this.keyIndex.set(this.compositeKey(e.namespace, e.key), e.id);
    if (e.embedding && this.hnswIndex) {
      this.hnswIndex.add(e.id, e.embedding);
    }
    this.dirty = true;
  }

  async get(id: string): Promise<MemoryEntry | null> {
    const entry = this.entries.get(id);
    if (!entry) return null;
    entry.accessCount++;
    entry.lastAccessedAt = Date.now();
    return entry;
  }

  async getByKey(namespace: string, key: string): Promise<MemoryEntry | null> {
    const id = this.keyIndex.get(this.compositeKey(namespace, key));
    if (!id) return null;
    return this.get(id);
  }

  async update(id: string, updateData: MemoryEntryUpdate): Promise<MemoryEntry | null> {
    const entry = this.entries.get(id);
    if (!entry) return null;

    const updated: MemoryEntry = {
      ...entry,
      ...updateData,
      updatedAt: Date.now(),
      version: entry.version + 1,
    };
    this.entries.set(id, updated);
    this.dirty = true;
    return updated;
  }

  async delete(id: string): Promise<boolean> {
    const entry = this.entries.get(id);
    if (!entry) return false;
    this.entries.delete(id);
    this.keyIndex.delete(this.compositeKey(entry.namespace, entry.key));
    if (this.hnswIndex) this.hnswIndex.remove(id);
    this.dirty = true;
    return true;
  }

  async query(q: MemoryQuery): Promise<MemoryEntry[]> {
    const start = performance.now();
    let results = Array.from(this.entries.values());

    if (q.namespace) results = results.filter(e => e.namespace === q.namespace);
    if (q.key) results = results.filter(e => e.key === q.key);
    if (q.keyPrefix) results = results.filter(e => e.key.startsWith(q.keyPrefix!));
    if (q.tags?.length) results = results.filter(e => q.tags!.every(t => e.tags.includes(t)));
    if (q.memoryType) results = results.filter(e => e.type === q.memoryType);
    if (q.accessLevel) results = results.filter(e => e.accessLevel === q.accessLevel);
    if (q.ownerId) results = results.filter(e => e.ownerId === q.ownerId);
    if (q.createdAfter) results = results.filter(e => e.createdAt > q.createdAfter!);
    if (q.createdBefore) results = results.filter(e => e.createdAt < q.createdBefore!);
    if (q.updatedAfter) results = results.filter(e => e.updatedAt > q.updatedAfter!);
    if (q.updatedBefore) results = results.filter(e => e.updatedAt < q.updatedBefore!);
    if (!q.includeExpired) {
      const now = Date.now();
      results = results.filter(e => !e.expiresAt || e.expiresAt > now);
    }

    if (q.type === 'semantic' && q.embedding && this.hnswIndex) {
      const searchResults = this.hnswIndex.search(q.embedding, q.limit, q.threshold);
      const idSet = new Set(searchResults.map(r => r.id));
      results = results.filter(e => idSet.has(e.id));
    }

    const offset = q.offset ?? 0;
    results = results.slice(offset, offset + q.limit);

    this.recordTiming(this.queryTimes, start);
    return results;
  }

  async search(embedding: Float32Array, options: SearchOptions): Promise<SearchResult[]> {
    const start = performance.now();
    let results: SearchResult[];

    if (this.hnswIndex) {
      const raw = this.hnswIndex.search(embedding, options.k * 2, options.threshold);
      results = [];
      for (const r of raw) {
        const entry = this.entries.get(r.id);
        if (!entry) continue;
        if (options.filters?.namespace && entry.namespace !== options.filters.namespace) continue;
        if (options.filters?.tags && !options.filters.tags.every(t => entry.tags.includes(t))) continue;
        if (options.filters?.memoryType && entry.type !== options.filters.memoryType) continue;
        results.push({ entry, score: r.score, distance: 1 - r.score });
      }
      results = results.slice(0, options.k);
    } else {
      results = this.bruteForceSearch(embedding, options);
    }

    this.recordTiming(this.searchTimes, start);
    return results;
  }

  async bulkInsert(entries: MemoryEntry[]): Promise<void> {
    for (const entry of entries) {
      this.entries.set(entry.id, entry);
      this.keyIndex.set(this.compositeKey(entry.namespace, entry.key), entry.id);
      if (entry.embedding && this.hnswIndex) this.hnswIndex.add(entry.id, entry.embedding);
    }
    this.dirty = true;
  }

  async bulkDelete(ids: string[]): Promise<number> {
    let count = 0;
    for (const id of ids) {
      const entry = this.entries.get(id);
      if (entry) {
        this.entries.delete(id);
        this.keyIndex.delete(this.compositeKey(entry.namespace, entry.key));
        if (this.hnswIndex) this.hnswIndex.remove(id);
        count++;
      }
    }
    this.dirty = true;
    return count;
  }

  async count(namespace?: string): Promise<number> {
    if (!namespace) return this.entries.size;
    let c = 0;
    for (const entry of this.entries.values()) {
      if (entry.namespace === namespace) c++;
    }
    return c;
  }

  async listNamespaces(): Promise<string[]> {
    const ns = new Set<string>();
    for (const entry of this.entries.values()) ns.add(entry.namespace);
    return Array.from(ns);
  }

  async clearNamespace(namespace: string): Promise<number> {
    const toDelete: string[] = [];
    for (const [id, entry] of this.entries) {
      if (entry.namespace === namespace) toDelete.push(id);
    }
    for (const id of toDelete) {
      const entry = this.entries.get(id)!;
      this.entries.delete(id);
      this.keyIndex.delete(this.compositeKey(entry.namespace, entry.key));
      if (this.hnswIndex) this.hnswIndex.remove(id);
    }
    if (toDelete.length > 0) this.dirty = true;
    return toDelete.length;
  }

  async getStats(): Promise<BackendStats> {
    const entriesByNamespace: Record<string, number> = {};
    const entriesByType: Record<string, number> = {};
    let memoryUsage = 0;

    for (const entry of this.entries.values()) {
      entriesByNamespace[entry.namespace] = (entriesByNamespace[entry.namespace] ?? 0) + 1;
      entriesByType[entry.type] = (entriesByType[entry.type] ?? 0) + 1;
      memoryUsage += entry.content.length * 2;
      if (entry.embedding) memoryUsage += entry.embedding.byteLength;
    }

    const avgQuery = this.avg(this.queryTimes);
    const avgSearch = this.avg(this.searchTimes);

    return {
      totalEntries: this.entries.size,
      entriesByNamespace,
      entriesByType: entriesByType as Record<MemoryType, number>,
      memoryUsage,
      hnswStats: this.hnswIndex ? {
        vectorCount: this.hnswIndex.size,
        memoryUsage: this.hnswIndex.size * this.config.dimensions * 4,
        avgSearchTime: avgSearch,
        buildTime: 0,
      } : undefined,
      avgQueryTime: avgQuery,
      avgSearchTime: avgSearch,
    };
  }

  async healthCheck(): Promise<HealthCheckResult> {
    const issues: string[] = [];
    const recommendations: string[] = [];

    if (!this.initialized) issues.push('Backend not initialized');
    if (!this.hnswIndex && !this.nativeDb) {
      issues.push('No vector index available');
      recommendations.push('Install @ruvector/rvf for native HNSW performance');
    }

    const status = issues.length === 0
      ? 'healthy'
      : issues.some(i => i.includes('not initialized')) ? 'unhealthy' : 'degraded';

    return {
      status,
      components: {
        storage: { status: this.initialized ? 'healthy' : 'unhealthy', latency: 0 },
        index: { status: this.hnswIndex || this.nativeDb ? 'healthy' : 'degraded', latency: 0 },
        cache: { status: 'healthy', latency: 0 },
      },
      timestamp: Date.now(),
      issues,
      recommendations,
    };
  }

  private async tryNativeInit(): Promise<boolean> {
    try {
      const rvf = await import('@ruvector/rvf' as string);
      this.nativeDb = new rvf.RvfDatabase({
        path: this.config.databasePath,
        dimensions: this.config.dimensions,
        metric: this.config.metric,
        quantization: this.config.quantization,
        hnswM: this.config.hnswM,
        hnswEfConstruction: this.config.hnswEfConstruction,
        maxElements: this.config.maxElements,
      });
      await this.nativeDb.open();
      if (this.config.verbose) {
        console.log('[RvfBackend] Native @ruvector/rvf loaded successfully');
      }
      return true;
    } catch {
      if (this.config.verbose) {
        console.log('[RvfBackend] @ruvector/rvf not available, using pure-TS fallback');
      }
      return false;
    }
  }

  private compositeKey(namespace: string, key: string): string {
    return `${namespace}\0${key}`;
  }

  private bruteForceSearch(embedding: Float32Array, options: SearchOptions): SearchResult[] {
    const results: SearchResult[] = [];
    for (const entry of this.entries.values()) {
      if (!entry.embedding) continue;
      const score = cosineSimilarity(embedding, entry.embedding);
      if (options.threshold && score < options.threshold) continue;
      if (options.filters?.namespace && entry.namespace !== options.filters.namespace) continue;
      if (options.filters?.tags && !options.filters.tags.every(t => entry.tags.includes(t))) continue;
      results.push({ entry, score, distance: 1 - score });
    }
    results.sort((a, b) => b.score - a.score);
    return results.slice(0, options.k);
  }

  private recordTiming(arr: number[], start: number): void {
    arr.push(performance.now() - start);
    if (arr.length > 100) arr.shift();
  }

  private avg(arr: number[]): number {
    return arr.length > 0 ? arr.reduce((a, b) => a + b, 0) / arr.length : 0;
  }

  private async loadFromDisk(): Promise<void> {
    if (this.config.databasePath === ':memory:') return;
    if (!existsSync(this.config.databasePath)) return;

    try {
      const raw = await readFile(this.config.databasePath);
      if (raw.length < 8) return;

      const magic = String.fromCharCode(raw[0], raw[1], raw[2], raw[3]);
      if (magic !== MAGIC) return;

      const headerLen = raw.readUInt32LE(4);
      const MAX_HEADER_SIZE = 10 * 1024 * 1024; // 10MB max header
      if (headerLen > MAX_HEADER_SIZE || 8 + headerLen > raw.length) return;
      const headerJson = raw.subarray(8, 8 + headerLen).toString('utf-8');
      let header: RvfHeader;
      try {
        header = JSON.parse(headerJson);
      } catch {
        if (this.config.verbose) console.error('[RvfBackend] Corrupt RVF header');
        return;
      }
      if (!header || typeof header.entryCount !== 'number' || typeof header.version !== 'number') return;

      let offset = 8 + headerLen;
      for (let i = 0; i < header.entryCount; i++) {
        if (offset + 4 > raw.length) break;
        const entryLen = raw.readUInt32LE(offset);
        offset += 4;
        if (offset + entryLen > raw.length) break;

        const entryJson = raw.subarray(offset, offset + entryLen).toString('utf-8');
        offset += entryLen;

        const parsed = JSON.parse(entryJson);
        if (parsed.embedding) parsed.embedding = new Float32Array(parsed.embedding);

        const entry: MemoryEntry = parsed;
        this.entries.set(entry.id, entry);
        this.keyIndex.set(this.compositeKey(entry.namespace, entry.key), entry.id);
        if (entry.embedding && this.hnswIndex) this.hnswIndex.add(entry.id, entry.embedding);
      }
    } catch (err) {
      if (this.config.verbose) {
        console.error('[RvfBackend] Error loading from disk:', err);
      }
    }
  }

  private persistQueue: Promise<void> = Promise.resolve();

  private async persistToDisk(): Promise<void> {
    if (this.config.databasePath === ':memory:') return;
    // Queue writes so concurrent callers wait instead of silently dropping
    this.persistQueue = this.persistQueue.then(() => this.doPersist()).catch(() => {});
    return this.persistQueue;
  }

  private async doPersist(): Promise<void> {
    if (!this.dirty) return;
    if (this.persisting) return;
    this.persisting = true;

    try {
    const dir = dirname(this.config.databasePath);
    if (!existsSync(dir)) await mkdir(dir, { recursive: true });

    const entries = Array.from(this.entries.values());

    // Compute min createdAt without spread operator (avoids stack overflow for large arrays)
    let minCreatedAt = Date.now();
    for (const e of entries) {
      if (e.createdAt < minCreatedAt) minCreatedAt = e.createdAt;
    }

    const header: RvfHeader = {
      magic: MAGIC,
      version: VERSION,
      dimensions: this.config.dimensions,
      metric: this.config.metric,
      quantization: this.config.quantization,
      entryCount: entries.length,
      createdAt: entries.length > 0 ? minCreatedAt : Date.now(),
      updatedAt: Date.now(),
    };

    const headerBuf = Buffer.from(JSON.stringify(header), 'utf-8');
    const entryBuffers: Buffer[] = [];

    for (const entry of entries) {
      const serialized = {
        ...entry,
        embedding: entry.embedding ? Array.from(entry.embedding) : undefined,
      };
      const buf = Buffer.from(JSON.stringify(serialized), 'utf-8');
      const lenBuf = Buffer.alloc(4);
      lenBuf.writeUInt32LE(buf.length, 0);
      entryBuffers.push(lenBuf, buf);
    }

    const magicBuf = Buffer.from([0x52, 0x56, 0x46, 0x00]);
    const headerLenBuf = Buffer.alloc(4);
    headerLenBuf.writeUInt32LE(headerBuf.length, 0);

    const output = Buffer.concat([magicBuf, headerLenBuf, headerBuf, ...entryBuffers]);

    // Atomic write: write to temp file then rename (crash-safe)
    const tmpPath = this.config.databasePath + '.tmp';
    await writeFile(tmpPath, output);
    await rename(tmpPath, this.config.databasePath);
    this.dirty = false;
    } finally {
      this.persisting = false;
    }
  }
}

/**
 * RvfLearningStore - Persistent storage for SONA learning artifacts
 *
 * Stores patterns, LoRA adapters, EWC state, and trajectories in a
 * binary-header JSON-lines file format for fast append and rebuild.
 *
 * File format:
 *   4-byte magic "RVLS" + newline
 *   One JSON record per line: {"type":"pattern"|"lora"|"ewc"|"trajectory","data":{...}}
 *
 * @module @claude-flow/memory/rvf-learning-store
 */

import * as fs from 'node:fs';
import * as path from 'node:path';

// ===== Types =====

export interface RvfLearningStoreConfig {
  /** Path to the persistence file */
  storePath: string;
  /** SONA embedding dimension (default: 64) */
  dimensions?: number;
  /** Auto-persist interval in ms (default: 30000) */
  autoPersistInterval?: number;
  /** Enable verbose logging (default: false) */
  verbose?: boolean;
}

export interface PatternRecord {
  id: string;
  type: string;
  embedding: number[];
  successRate: number;
  useCount: number;
  lastUsed: string;
}

export interface LoraRecord {
  id: string;
  config: Record<string, unknown>;
  weights: string;
  frozen: boolean;
  numParameters: number;
}

export interface EwcRecord {
  tasksLearned: number;
  protectionStrength: number;
  forgettingRate: number;
  taskWeights: Record<string, number[]>;
}

export interface TrajectoryRecord {
  id: string;
  steps: Array<{
    type: string;
    input: string;
    output: string;
    durationMs: number;
    confidence: number;
  }>;
  outcome: string;
  durationMs: number;
  timestamp: string;
}

type RecordType = 'pattern' | 'lora' | 'ewc' | 'trajectory';

interface StoreLine {
  type: RecordType;
  data: PatternRecord | LoraRecord | EwcRecord | TrajectoryRecord;
}

// ===== Constants =====

const MAGIC_HEADER = 'RVLS';
const DEFAULT_DIMENSIONS = 64;
const DEFAULT_AUTO_PERSIST_MS = 30_000;

// ===== Helpers =====

function ensureDirectory(filePath: string): void {
  const dir = path.dirname(filePath);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

// ===== RvfLearningStore =====

/**
 * Persistent store for SONA learning artifacts.
 *
 * Maintains in-memory maps for fast reads and flushes to a JSON-lines
 * file with a binary header on persist(). On initialize(), the file is
 * read line-by-line to rebuild state.
 *
 * @example
 * ```typescript
 * const store = new RvfLearningStore({ storePath: './data/learning.rvls' });
 * await store.initialize();
 *
 * await store.savePatterns([{ id: 'p1', type: 'query_response', ... }]);
 * await store.persist();
 * await store.close();
 * ```
 */
export class RvfLearningStore {
  private config: Required<RvfLearningStoreConfig>;
  private patterns: Map<string, PatternRecord> = new Map();
  private loraAdapters: Map<string, LoraRecord> = new Map();
  private ewcState: EwcRecord | null = null;
  private trajectories: TrajectoryRecord[] = [];
  private dirty = false;
  private initialized = false;
  private autoPersistTimer: ReturnType<typeof setInterval> | null = null;

  constructor(config: RvfLearningStoreConfig) {
    this.config = {
      storePath: config.storePath,
      dimensions: config.dimensions ?? DEFAULT_DIMENSIONS,
      autoPersistInterval: config.autoPersistInterval ?? DEFAULT_AUTO_PERSIST_MS,
      verbose: config.verbose ?? false,
    };
  }

  /**
   * Initialize the store by loading any existing data from disk.
   * Creates the parent directory if it does not exist.
   */
  async initialize(): Promise<void> {
    if (this.initialized) return;

    ensureDirectory(this.config.storePath);

    if (fs.existsSync(this.config.storePath)) {
      await this.loadFromDisk();
    }

    if (this.config.autoPersistInterval > 0) {
      this.autoPersistTimer = setInterval(
        () => void this.persist().catch(() => {}),
        this.config.autoPersistInterval,
      );
      // Allow the process to exit even if the timer is active
      if (this.autoPersistTimer.unref) {
        this.autoPersistTimer.unref();
      }
    }

    this.initialized = true;
    this.log('Store initialized');
  }

  // ===== Pattern operations =====

  /**
   * Save or update patterns. Existing patterns with matching IDs are
   * overwritten; new patterns are added.
   *
   * @returns The number of patterns stored
   */
  async savePatterns(patterns: PatternRecord[]): Promise<number> {
    this.ensureInitialized();
    let count = 0;
    for (const pattern of patterns) {
      this.patterns.set(pattern.id, { ...pattern });
      count++;
    }
    this.dirty = true;
    return count;
  }

  /** Load all patterns currently held in memory */
  async loadPatterns(): Promise<PatternRecord[]> {
    this.ensureInitialized();
    return Array.from(this.patterns.values());
  }

  /** Return the number of stored patterns */
  async getPatternCount(): Promise<number> {
    this.ensureInitialized();
    return this.patterns.size;
  }

  // ===== LoRA operations =====

  /** Save or update a LoRA adapter record */
  async saveLoraAdapter(record: LoraRecord): Promise<void> {
    this.ensureInitialized();
    this.loraAdapters.set(record.id, { ...record });
    this.dirty = true;
  }

  /** Load all LoRA adapter records */
  async loadLoraAdapters(): Promise<LoraRecord[]> {
    this.ensureInitialized();
    return Array.from(this.loraAdapters.values());
  }

  /** Delete a LoRA adapter by ID */
  async deleteLoraAdapter(id: string): Promise<boolean> {
    this.ensureInitialized();
    const existed = this.loraAdapters.delete(id);
    if (existed) this.dirty = true;
    return existed;
  }

  // ===== EWC operations =====

  /** Save EWC state (replaces any existing state) */
  async saveEwcState(record: EwcRecord): Promise<void> {
    this.ensureInitialized();
    this.ewcState = { ...record };
    this.dirty = true;
  }

  /** Load the EWC state, or null if none has been stored */
  async loadEwcState(): Promise<EwcRecord | null> {
    this.ensureInitialized();
    return this.ewcState ? { ...this.ewcState } : null;
  }

  // ===== Trajectory operations =====

  /** Append a trajectory record (append-only, never overwritten) */
  async appendTrajectory(record: TrajectoryRecord): Promise<void> {
    this.ensureInitialized();
    this.trajectories.push({ ...record });
    this.dirty = true;
  }

  /**
   * Return stored trajectories, newest first.
   * @param limit Maximum number to return (default: all)
   */
  async getTrajectories(limit?: number): Promise<TrajectoryRecord[]> {
    this.ensureInitialized();
    const sorted = [...this.trajectories].reverse();
    return limit !== undefined ? sorted.slice(0, limit) : sorted;
  }

  /** Return the number of stored trajectories */
  async getTrajectoryCount(): Promise<number> {
    this.ensureInitialized();
    return this.trajectories.length;
  }

  // ===== Lifecycle =====

  /**
   * Flush all in-memory state to disk. The entire file is rewritten
   * to ensure consistency (patterns may have been updated in-place).
   */
  async persist(): Promise<void> {
    if (!this.dirty) return;

    ensureDirectory(this.config.storePath);

    const lines: string[] = [MAGIC_HEADER];

    // Patterns
    for (const pattern of this.patterns.values()) {
      lines.push(JSON.stringify({ type: 'pattern', data: pattern }));
    }

    // LoRA adapters
    for (const lora of this.loraAdapters.values()) {
      lines.push(JSON.stringify({ type: 'lora', data: lora }));
    }

    // EWC state
    if (this.ewcState) {
      lines.push(JSON.stringify({ type: 'ewc', data: this.ewcState }));
    }

    // Trajectories
    for (const traj of this.trajectories) {
      lines.push(JSON.stringify({ type: 'trajectory', data: traj }));
    }

    const content = lines.join('\n') + '\n';
    const tmpPath = this.config.storePath + '.tmp';

    await fs.promises.writeFile(tmpPath, content, 'utf-8');
    await fs.promises.rename(tmpPath, this.config.storePath);

    this.dirty = false;
    this.log(`Persisted: ${this.patterns.size} patterns, ${this.loraAdapters.size} LoRA, ${this.trajectories.length} trajectories`);
  }

  /** Persist and release resources */
  async close(): Promise<void> {
    if (this.autoPersistTimer) {
      clearInterval(this.autoPersistTimer);
      this.autoPersistTimer = null;
    }

    if (this.dirty) {
      await this.persist();
    }

    this.initialized = false;
    this.log('Store closed');
  }

  // ===== Stats =====

  /** Return summary statistics about the store */
  async getStats(): Promise<{
    patterns: number;
    loraAdapters: number;
    trajectories: number;
    hasEwcState: boolean;
    fileSizeBytes: number;
  }> {
    this.ensureInitialized();

    let fileSizeBytes = 0;
    try {
      const stat = await fs.promises.stat(this.config.storePath);
      fileSizeBytes = stat.size;
    } catch {
      // File may not exist yet if nothing has been persisted
    }

    return {
      patterns: this.patterns.size,
      loraAdapters: this.loraAdapters.size,
      trajectories: this.trajectories.length,
      hasEwcState: this.ewcState !== null,
      fileSizeBytes,
    };
  }

  // ===== Private =====

  private async loadFromDisk(): Promise<void> {
    let content: string;
    try {
      content = await fs.promises.readFile(this.config.storePath, 'utf-8');
    } catch {
      return;
    }

    const lines = content.split('\n').filter((l) => l.trim().length > 0);
    if (lines.length === 0) return;

    // Verify magic header
    if (lines[0] !== MAGIC_HEADER) {
      this.log(`Warning: invalid magic header "${lines[0]}", expected "${MAGIC_HEADER}"`);
      return;
    }

    let parsed = 0;
    let errors = 0;

    for (let i = 1; i < lines.length; i++) {
      try {
        const record = JSON.parse(lines[i]) as StoreLine;
        this.applyRecord(record);
        parsed++;
      } catch {
        errors++;
        this.log(`Warning: failed to parse line ${i + 1}`);
      }
    }

    this.log(`Loaded from disk: ${parsed} records, ${errors} errors`);
  }

  private applyRecord(record: StoreLine): void {
    switch (record.type) {
      case 'pattern': {
        const p = record.data as PatternRecord;
        this.patterns.set(p.id, p);
        break;
      }
      case 'lora': {
        const l = record.data as LoraRecord;
        this.loraAdapters.set(l.id, l);
        break;
      }
      case 'ewc': {
        this.ewcState = record.data as EwcRecord;
        break;
      }
      case 'trajectory': {
        this.trajectories.push(record.data as TrajectoryRecord);
        break;
      }
      default:
        this.log(`Warning: unknown record type "${record.type}"`);
    }
  }

  private ensureInitialized(): void {
    if (!this.initialized) {
      throw new Error('RvfLearningStore has not been initialized. Call initialize() first.');
    }
  }

  private log(message: string): void {
    if (this.config.verbose) {
      // eslint-disable-next-line no-console
      console.log(`[RvfLearningStore] ${message}`);
    }
  }
}

/**
 * RVF Migration Utility — bidirectional migration between RVF and legacy
 * formats (JSON files, sql.js / better-sqlite3 databases).
 * @module @claude-flow/memory/rvf-migration
 */
import { readFile, writeFile, rename, mkdir } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { RvfBackend } from './rvf-backend.js';
import type { MemoryEntry, MemoryType, AccessLevel } from './types.js';
import { generateMemoryId } from './types.js';

/** Options for controlling the migration process. */
export interface RvfMigrationOptions {
  verbose?: boolean;
  /** Entries per batch (default 500). */
  batchSize?: number;
  /** Embedding dimensions for target RVF file (default 1536). */
  dimensions?: number;
  onProgress?: (progress: { current: number; total: number; phase: string }) => void;
}

/** Result returned after a migration completes. */
export interface RvfMigrationResult {
  success: boolean;
  entriesMigrated: number;
  sourceFormat: string;
  targetFormat: string;
  durationMs: number;
  errors: string[];
}

// -- Internal helpers -------------------------------------------------------

function fillDefaults(raw: Record<string, unknown>): MemoryEntry {
  const now = Date.now();
  return {
    id: (raw.id as string) ?? generateMemoryId(),
    key: (raw.key as string) ?? '',
    content: (raw.content as string) ?? '',
    type: (raw.type as MemoryType) ?? 'semantic',
    namespace: (raw.namespace as string) ?? 'default',
    tags: (raw.tags as string[]) ?? [],
    metadata: (raw.metadata as Record<string, unknown>) ?? {},
    ownerId: raw.ownerId as string | undefined,
    accessLevel: (raw.accessLevel as AccessLevel) ?? 'private',
    createdAt: (raw.createdAt as number) ?? now,
    updatedAt: (raw.updatedAt as number) ?? now,
    expiresAt: raw.expiresAt as number | undefined,
    version: (raw.version as number) ?? 1,
    references: (raw.references as string[]) ?? [],
    accessCount: (raw.accessCount as number) ?? 0,
    lastAccessedAt: (raw.lastAccessedAt as number) ?? now,
    embedding: deserializeEmbedding(raw.embedding),
  };
}

function deserializeEmbedding(value: unknown): Float32Array | undefined {
  if (!value) return undefined;
  if (value instanceof Float32Array) return value;
  if (value instanceof Buffer || value instanceof Uint8Array) {
    if (value.byteLength === 0) return undefined;
    const out = new Float32Array(value.byteLength / 4);
    const view = new DataView(value.buffer, value.byteOffset, value.byteLength);
    for (let i = 0; i < out.length; i++) out[i] = view.getFloat32(i * 4, true);
    return out;
  }
  if (Array.isArray(value)) return new Float32Array(value as number[]);
  return undefined;
}

function serializeForJson(entry: MemoryEntry): Record<string, unknown> {
  return { ...entry, embedding: entry.embedding ? Array.from(entry.embedding) : undefined };
}

function validateMigrationPath(p: string): void {
  if (!p || typeof p !== 'string') throw new Error('Path must be a non-empty string');
  if (p.includes('\0')) throw new Error('Path contains null bytes');
}

async function ensureDir(filePath: string): Promise<void> {
  validateMigrationPath(filePath);
  const dir = dirname(resolve(filePath));
  if (!existsSync(dir)) await mkdir(dir, { recursive: true });
}

async function atomicWrite(targetPath: string, data: string | Buffer): Promise<void> {
  validateMigrationPath(targetPath);
  const abs = resolve(targetPath);
  const tmp = abs + '.tmp.' + Date.now();
  await ensureDir(abs);
  await writeFile(tmp, data, typeof data === 'string' ? 'utf-8' : undefined);
  await rename(tmp, abs);
}

function mkResult(
  success: boolean, entriesMigrated: number, sourceFormat: string,
  targetFormat: string, startMs: number, errors: string[],
): RvfMigrationResult {
  return { success, entriesMigrated, sourceFormat, targetFormat, durationMs: Date.now() - startMs, errors };
}

function normalizeSqliteRow(row: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = { ...row };
  for (const col of ['tags', 'metadata', 'references'] as const) {
    if (typeof out[col] === 'string') {
      try { out[col] = JSON.parse(out[col] as string); } catch { out[col] = col === 'metadata' ? {} : []; }
    }
  }
  return out;
}

// -- SQLite reader (better-sqlite3 first, then sql.js) ----------------------

interface SqliteRow { [key: string]: unknown }

async function readSqliteRows(dbPath: string): Promise<SqliteRow[]> {
  // Attempt better-sqlite3
  try {
    const mod = await import('better-sqlite3' as string);
    const Database = mod.default ?? mod;
    const db = new Database(dbPath, { readonly: true });
    try { return db.prepare('SELECT * FROM memory_entries').all() as SqliteRow[]; }
    finally { db.close(); }
  } catch { /* unavailable */ }
  // Attempt sql.js
  try {
    const mod = await import('sql.js' as string);
    const SQL = await (mod.default ?? mod)();
    const db = new SQL.Database(await readFile(dbPath));
    try {
      const stmt = db.prepare('SELECT * FROM memory_entries');
      const rows: SqliteRow[] = [];
      while (stmt.step()) rows.push(stmt.getAsObject() as SqliteRow);
      stmt.free();
      return rows;
    } finally { db.close(); }
  } catch { /* unavailable */ }
  throw new Error('Cannot read SQLite: install better-sqlite3 or sql.js');
}

// -- Batch migration helper -------------------------------------------------

async function migrateBatches(
  items: Record<string, unknown>[],
  rvfPath: string,
  options: RvfMigrationOptions,
  normalize?: (r: Record<string, unknown>) => Record<string, unknown>,
): Promise<{ migrated: number; errors: string[] }> {
  const batchSize = options.batchSize ?? 500;
  const dimensions = options.dimensions ?? 1536;
  const backend = new RvfBackend({ databasePath: rvfPath, dimensions, verbose: options.verbose });
  await backend.initialize();
  let migrated = 0;
  const errors: string[] = [];
  try {
    for (let i = 0; i < items.length; i += batchSize) {
      const batch = items.slice(i, i + batchSize);
      const entries: MemoryEntry[] = [];
      for (const item of batch) {
        try {
          entries.push(fillDefaults(normalize ? normalize(item) : item));
        } catch (e) { errors.push(`Entry ${item.id ?? i}: ${(e as Error).message}`); }
      }
      if (entries.length > 0) { await backend.bulkInsert(entries); migrated += entries.length; }
      options.onProgress?.({ current: Math.min(i + batchSize, items.length), total: items.length, phase: 'migrating' });
    }
  } finally { await backend.shutdown(); }
  return { migrated, errors };
}

/**
 * Bidirectional migration utility between RVF and legacy memory formats.
 *
 * All methods are static — no instantiation required.
 */
export class RvfMigrator {
  /** Migrate a JSON memory file to RVF format. */
  static async fromJsonFile(
    jsonPath: string, rvfPath: string, options: RvfMigrationOptions = {},
  ): Promise<RvfMigrationResult> {
    const start = Date.now();
    const raw = await readFile(jsonPath, 'utf-8');
    let parsed: unknown;
    try { parsed = JSON.parse(raw); }
    catch (e) { return mkResult(false, 0, 'json', 'rvf', start, [`Invalid JSON: ${(e as Error).message}`]); }
    const items = Array.isArray(parsed) ? parsed : [parsed as Record<string, unknown>];
    const { migrated, errors } = await migrateBatches(items, rvfPath, options);
    if (options.verbose) console.log(`[RvfMigrator] Migrated ${migrated} entries from JSON to RVF`);
    return mkResult(errors.length === 0, migrated, 'json', 'rvf', start, errors);
  }

  /** Migrate a SQLite (better-sqlite3 / sql.js) database to RVF. */
  static async fromSqlite(
    dbPath: string, rvfPath: string, options: RvfMigrationOptions = {},
  ): Promise<RvfMigrationResult> {
    const start = Date.now();
    let rows: SqliteRow[];
    try { rows = await readSqliteRows(dbPath); }
    catch (e) { return mkResult(false, 0, 'sqlite', 'rvf', start, [(e as Error).message]); }
    options.onProgress?.({ current: 0, total: rows.length, phase: 'reading' });
    const { migrated, errors } = await migrateBatches(rows, rvfPath, options, normalizeSqliteRow);
    if (options.verbose) console.log(`[RvfMigrator] Migrated ${migrated} entries from SQLite to RVF`);
    return mkResult(errors.length === 0, migrated, 'sqlite', 'rvf', start, errors);
  }

  /** Export an RVF file back to a JSON array (backward compatibility). */
  static async toJsonFile(rvfPath: string, jsonPath: string): Promise<RvfMigrationResult> {
    const start = Date.now();
    const backend = new RvfBackend({ databasePath: rvfPath });
    await backend.initialize();
    let entries: MemoryEntry[];
    try { entries = await backend.query({ type: 'hybrid', limit: Number.MAX_SAFE_INTEGER }); }
    finally { await backend.shutdown(); }
    const warnings: string[] = [];
    if (entries.length === 0) warnings.push('Source RVF file contained no entries');
    await atomicWrite(jsonPath, JSON.stringify(entries.map(serializeForJson), null, 2));
    return mkResult(true, entries.length, 'rvf', 'json', start, warnings);
  }

  /**
   * Detect file format by magic bytes.
   * - RVF\0 (0x52 0x56 0x46 0x00) -> 'rvf'
   * - SQLi  (0x53 0x51 0x4C 0x69) -> 'sqlite'
   * - Leading [ or {              -> 'json'
   */
  static async detectFormat(filePath: string): Promise<'rvf' | 'json' | 'sqlite' | 'unknown'> {
    if (!existsSync(filePath)) return 'unknown';
    const fd = await import('node:fs').then(m => m.promises.open(filePath, 'r'));
    try {
      const buf = Buffer.alloc(16);
      await fd.read(buf, 0, 16, 0);
      if (buf[0] === 0x52 && buf[1] === 0x56 && buf[2] === 0x46 && buf[3] === 0x00) return 'rvf';
      if (buf[0] === 0x53 && buf[1] === 0x51 && buf[2] === 0x4C && buf[3] === 0x69) return 'sqlite';
      const head = buf.toString('utf-8').trimStart();
      if (head.startsWith('[') || head.startsWith('{')) return 'json';
      return 'unknown';
    } finally { await fd.close(); }
  }

  /** Auto-detect source format and migrate to RVF. */
  static async autoMigrate(
    sourcePath: string, targetRvfPath: string, options: RvfMigrationOptions = {},
  ): Promise<RvfMigrationResult> {
    const format = await RvfMigrator.detectFormat(sourcePath);
    if (options.verbose) console.log(`[RvfMigrator] Detected source format: ${format}`);
    switch (format) {
      case 'json':   return RvfMigrator.fromJsonFile(sourcePath, targetRvfPath, options);
      case 'sqlite': return RvfMigrator.fromSqlite(sourcePath, targetRvfPath, options);
      case 'rvf':    return { success: true, entriesMigrated: 0, sourceFormat: 'rvf', targetFormat: 'rvf', durationMs: 0, errors: [] };
      default:       return { success: false, entriesMigrated: 0, sourceFormat: 'unknown', targetFormat: 'rvf', durationMs: 0, errors: [`Unrecognized format: ${sourcePath}`] };
    }
  }
}

import { describe, it, expect, vi } from 'vitest';
import {
  smartSearch,
  defaultQueryExpansions,
  type SearchCandidate,
